    exact(body, ['expectedVersion', 'requestId', 'actor', 'note', 'filename', 'kind', 'mediaType', 'sourceUrl', 'observedAt'],
      ['expectedVersion', 'requestId', 'actor', 'filename', 'kind', 'mediaType']);
