.wi-totals dd { font-size: 1.2rem; font-variant-numeric: tabular-nums; margin: .35rem 0 0; overflow-wrap: anywhere; }
.wi-issues { max-height: 24rem; overflow-y: auto; padding-left: 1.4rem; }
.wi-issues li { margin: .45rem 0; }
.wi-tabs { display: flex; gap: .5rem; margin: 1rem 0; }
.wi-tabs [aria-pressed="true"] { background: #e5e5e5; border-color: #333; font-weight: 650; }
.wi-pagination { display: flex; justify-content: space-between; align-items: center; gap: .75rem; flex-wrap: wrap; margin: .8rem 0; }
.wi-dialog { width: min(70rem,calc(100vw - 2rem)); max-height: calc(100vh - 3rem); overflow: auto; border: 1px solid #555; padding: 1.3rem; color: #202020; background: #fff; }
.wi-dialog::backdrop { background: #0008; }
.wi-dialog form > .wi-actions { position: sticky; bottom: -1.3rem; padding: .9rem 0; background: #fff; border-top: 1px solid var(--wi-line); margin-top: 1rem; }
.wi-dialog .wi-table td { min-width: 5rem; }
.wi-correction { display: grid; grid-template-columns: minmax(10rem,1fr) minmax(15rem,3fr); gap: 1rem; padding: .65rem 0; border-bottom: 1px solid var(--wi-line); }
.work-intake-desk .wi-check { flex-direction: row; align-items: center; gap: .6rem; font-weight: 400; }
.work-intake-desk .wi-check input { width: 20px; min-height: 20px; height: 20px; flex-shrink: 0; }
@media(max-width: 950px) {
  .wi-format { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .wi-totals { grid-template-columns: repeat(3,minmax(0,1fr)); }
}
@media(max-width: 600px) {
  .wi-fields, .wi-format, .wi-correction { grid-template-columns: 1fr; }
  .wi-totals { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .wi-section { padding: .7rem; }
  .wi-pagination { justify-content: flex-start; }
  .wi-pagination span { order: -1; width: 100%; }
  .wi-actions { align-items: stretch; }
  .wi-heading .wi-actions { width: 100%; }
