SCHEMA = "stellar-forge.sf47-contributor-engagements.v1"
ENGINE_VERSION = 1
PURPOSE = "CONTRIBUTOR_ENGAGEMENTS"
RECEIVING_PURPOSE = "CONTRIBUTOR_ENGAGEMENTS_RECEIVING"
STATUSES = ("PROPOSED", "CONFIRMED", "DECLINED", "WITHDRAWN")
SOURCE_FIELDS = {"sourceIds", "sourceNote", "sourceBasis"}
ZERO = Decimal("0")


def fail(message, code="INVALID_ENGAGEMENT", status=422):
    raise Problem(message, status, code)


def obj(value, fields, label):
    if not isinstance(value, dict) or set(value) - set(fields):
        fail(label + ": use the declared object fields.")
    return value


def rows(value, label, maximum):
    if not isinstance(value, list) or len(value) > maximum or any(not isinstance(row, dict) for row in value):
        fail(label + ": use at most " + str(maximum) + " object rows.")
    return value


def ident(value, label="Engagement identity"):
    if not isinstance(value, str) or not re.fullmatch(r"[a-z][a-z0-9-]{1,99}", value):
        fail(label + ": use an original lowercase record identity.")
    return value


def sources(data, context):
    return domain.source_fields(data, context["sources"])


def source_ids(document):
    result = set()
    for row in document["agreements"]:
        for part in (row, row["availability"], row["compensation"], row["acceptance"]):
            result.update(part["sourceIds"])
    return sorted(result)


def normalize(context, raw):
    raw = obj(deepcopy(raw), {"schema", "name", "asOfDate", "agreements", "supersedes", "note"}, "Engagement edition")
    if raw.get("schema") != SCHEMA:
        fail("Use the supported contributor engagement edition.")
    people = {row["id"]: row for row in context["records"]["contributors"]}
    seen, contributor_ids, agreements = set(), set(), []
    for row in rows(raw.get("agreements", []), "Contributor agreements", portfolios.MAX_RESOURCES):
        obj(row, {"id", "contributorId", "role", "scope", "startDate", "endDate",
                  "availability", "compensation", "acceptance", "allocations", *SOURCE_FIELDS}, "Agreement")
        rid = ident(row.get("id"))
        person = row.get("contributorId")
        if rid in seen or person in contributor_ids:
            fail("Retain one current agreement row per named contributor, with distinct agreement IDs.")
        if person not in people:
            fail("Select a retained Operations contributor.")
        seen.add(rid)
        contributor_ids.add(person)
        start = domain.calendar(row.get("startDate"), "Agreement start")
        end = domain.calendar(row.get("endDate"), "Agreement finish")
        if end < start:
            fail("The agreement finish must follow its start.")
        availability = obj(row.get("availability"), {"hoursByWeekday", "hoursByDate", "note", *SOURCE_FIELDS}, "Availability")
        resource = portfolios.normalize_resources([{"id": "agreement", "name": people[person]["name"],
            "hoursByWeekday": availability.get("hoursByWeekday"), "hoursByDate": availability.get("hoursByDate", {}),
            "note": availability.get("note", "")}])[0]
        if any(stamp < start or stamp > end for stamp in resource["hoursByDate"]):
            fail("Dated availability exceptions must lie inside the recorded agreement period.")
        availability = {key: resource[key] for key in ("hoursByWeekday", "hoursByDate", "note")} | sources(availability, context)

        compensation = obj(row.get("compensation"), {"basis", "rateUsd", "totalUsd", "paymentTerms",
            "paymentMode", "note", *SOURCE_FIELDS}, "Compensation")
        basis = domain.enum(compensation.get("basis", "UNSPECIFIED"), ("HOURLY", "FIXED", "IN_KIND", "UNSPECIFIED"), "Compensation basis")
        rate = None if compensation.get("rateUsd") in (None, "") else domain.quantity(compensation["rateUsd"], "Agreed USD hourly rate", 4)
        total = None if compensation.get("totalUsd") in (None, "") else domain.usd(compensation["totalUsd"], "Agreed total USD fee")
        if basis == "HOURLY" and rate is None:
            fail("An hourly agreement needs its actual hourly rate.")
        if basis == "FIXED" and total is None:
            fail("A fixed agreement needs its actual total fee.")
        if basis in ("IN_KIND", "UNSPECIFIED") and (rate is not None or total not in (None, "0.00")):
            fail("Choose the commercial basis corresponding to the entered fee.")
        compensation = {"basis": basis, "rateUsd": rate, "totalUsd": total,
            "paymentTerms": text(compensation.get("paymentTerms", ""), "Original payment terms", 12000),
            "paymentMode": domain.enum(compensation.get("paymentMode", "original"),
                ("original", "accrual", "completion"), "Reviewed native payment schedule"),
            "note": text(compensation.get("note", ""), "Compensation and timing basis", 12000),
            **sources(compensation, context)}

        acceptance = obj(row.get("acceptance"), {"status", "by", "at", "note", *SOURCE_FIELDS}, "Acceptance")
        status = domain.enum(acceptance.get("status", "PROPOSED"), STATUSES, "Recorded agreement acceptance")
        by = text(acceptance.get("by", ""), "Person confirming the agreement", 300)
        at = domain.timestamp(acceptance.get("at"), "Original agreement confirmation", True)
        if status == "CONFIRMED" and (not by or not at):
            fail("Record who confirmed the agreement and its original timestamp.")
        acceptance = {"status": status, "by": by, "at": at,
            "note": text(acceptance.get("note", ""), "Original acceptance observation", 12000),
            **sources(acceptance, context)}

        allocations, cost_ids = [], set()
        for allocation in rows(row.get("allocations", []), "Remaining grant-package allocations", 200):
            obj(allocation, {"costId", "remainingHours", "remainingCostUsd", "note"}, "Package allocation")
            cost = domain.cost_id(allocation.get("costId"), context["plan"])
            if cost is None or cost in cost_ids:
                fail("Select each original grant work package once within an agreement.")
            cost_ids.add(cost)
            allocations.append({"costId": cost,
                "remainingHours": domain.quantity(allocation.get("remainingHours"), "Remaining allocated hours", 4),
                "remainingCostUsd": domain.usd(allocation.get("remainingCostUsd"), "Remaining uninvoiced allocation"),
                "note": text(allocation.get("note", ""), "Remaining allocation basis", 4000)})
        agreements.append({"id": rid, "contributorId": person,
            "role": text(row.get("role"), "Agreed role", 500, True),
            "scope": text(row.get("scope"), "Agreed scope", 12000, True),
            "startDate": start, "endDate": end, "availability": availability,
            "compensation": compensation, "acceptance": acceptance, "allocations": allocations,
            **sources(row, context)})
    previous = raw.get("supersedes")
    if previous is not None:
        obj(previous, {"reviewId", "reviewSha256"}, "Previous engagement edition")
        previous = {"reviewId": ident(previous.get("reviewId"), "Previous review"),
                    "reviewSha256": domain.sha(previous.get("reviewSha256"), "Previous complete review", False)}
    return {"schema": SCHEMA, "name": text(raw.get("name"), "Engagement edition name", 300, True),
        "asOfDate": domain.calendar(raw.get("asOfDate"), "Remaining-work as-of date"),
        "agreements": agreements, "supersedes": previous,
        "note": text(raw.get("note", ""), "Edition basis", 12000)}


def binding(context, document):
    people = {row["id"]: row for row in context["records"]["contributors"]}
    return {"planContentSha256": context["plan"]["contentSha256"],
        "planSourceSha256": context["plan"]["source"]["sha256"], "mode": context["program"]["mode"],
        "contributors": [deepcopy(people[rid]) for rid in sorted({r["contributorId"] for r in document["agreements"]})],
        "sources": [deepcopy(context["sources"][sid]) for sid in source_ids(document)]}


def source(context, document):
    return {**forecasts.source_identity(context), "bindingSha256": digest(binding(context, document))}


def capacity(row):
    """Count the entered calendar exactly without expanding a long agreement."""
    start, end = date.fromisoformat(row["startDate"]), date.fromisoformat(row["endDate"])
    length = (end - start).days + 1
    whole, remainder = divmod(length, 7)
    counts = [whole] * 7
    for offset in range(remainder):
        counts[(start.weekday() + offset) % 7] += 1
    weekly, overrides = row["availability"]["hoursByWeekday"], row["availability"]["hoursByDate"]
    known, missing = ZERO, 0
    for weekday, count in enumerate(counts):
        if weekly[weekday] is None:
            missing += count
        else:
            known += Decimal(weekly[weekday]) * count
    for stamp, entered in overrides.items():
        original = weekly[date.fromisoformat(stamp).weekday()]
        if original is None:
            missing -= 1
        else:
            known -= Decimal(original)
        known += Decimal(entered)
    return {"calendarDays": length, "knownAvailableHours": forecasts.hours(known),
            "unenteredDates": missing, "complete": missing == 0}


def report(context, document):
    people = {row["id"]: row for row in context["records"]["contributors"]}
    entries, packages, issues = [], {}, []
    counts = {state.lower(): 0 for state in STATUSES}
    totals = {state: {"hours": ZERO, "cost": ZERO} for state in STATUSES}
    for row in document["agreements"]:
        status = row["acceptance"]["status"]
        counts[status.lower()] += 1
        available = capacity(row)
        allocated = sum((Decimal(x["remainingHours"]) for x in row["allocations"]), ZERO)
        cost = sum((Decimal(x["remainingCostUsd"]) for x in row["allocations"]), ZERO)
        totals[status]["hours"] += allocated
        totals[status]["cost"] += cost
        person = people[row["contributorId"]]
        entry = {"id": row["id"], "contributor": {k: person[k] for k in ("id", "name", "kind", "contact")},
            "role": row["role"], "status": status, "startDate": row["startDate"], "endDate": row["endDate"],
            "remainingHours": forecasts.hours(allocated), "remainingCostUsd": forecasts.money(cost),
            "capacity": available, "sourceIds": sorted(set(sid for part in
                (row, row["availability"], row["compensation"], row["acceptance"]) for sid in part["sourceIds"]))}
        if not available["complete"]:
            issues.append({"code": "AVAILABILITY_UNENTERED", "engagementId": row["id"],
                "message": "Availability has " + str(available["unenteredDates"]) + " unentered dates."})
        if row["endDate"] <= document["asOfDate"] and allocated:
            issues.append({"code": "REMAINING_WORK_AFTER_AGREEMENT", "engagementId": row["id"],
                "message": "Remaining work extends beyond this recorded agreement's elapsed period."})
        if status == "CONFIRMED" and person["kind"] == "ROLE":
            issues.append({"code": "ROLE_CONTRIBUTOR", "engagementId": row["id"],
                "message": "The selected contributor is a role record; the confirmation retains its named confirming person."})
        if status == "CONFIRMED" and not row["compensation"]["paymentTerms"]:
            issues.append({"code": "PAYMENT_TERMS_UNENTERED", "engagementId": row["id"],
                "message": "The original payment terms have not been entered."})
        for allocation in row["allocations"]:
            package = packages.setdefault(allocation["costId"], {"costId": allocation["costId"],
                "confirmedHours": ZERO, "confirmedCostUsd": ZERO, "proposedHours": ZERO,
                "proposedCostUsd": ZERO, "engagementIds": []})
            if status in ("CONFIRMED", "PROPOSED"):
                prefix = status.lower()
                package[prefix + "Hours"] += Decimal(allocation["remainingHours"])
                package[prefix + "CostUsd"] += Decimal(allocation["remainingCostUsd"])
                package["engagementIds"].append(row["id"])
        entries.append(entry)
    package_rows = []
    for package in packages.values():
        package_rows.append({k: forecasts.money(v) if k.endswith("Usd") else forecasts.hours(v)
                             if isinstance(v, Decimal) else v for k, v in package.items()})
    return {"schema": SCHEMA + ".report", "name": document["name"], "asOfDate": document["asOfDate"],
        "mode": context["program"]["mode"], "agreements": len(entries), **counts,
        "allocatedHours": forecasts.hours(totals["CONFIRMED"]["hours"] + totals["PROPOSED"]["hours"]),
        "remainingCostUsd": forecasts.money(totals["CONFIRMED"]["cost"] + totals["PROPOSED"]["cost"]),
        "byAcceptance": {k: {"remainingHours": forecasts.hours(v["hours"]), "remainingCostUsd": forecasts.money(v["cost"])}
                         for k, v in totals.items()},
        "entries": entries, "packages": package_rows, "issues": issues,
        "paymentTimingBasis": "Recorded agreement terms and each explicitly selected original Forecast payment mode."}


def preview(context, raw):
    document = normalize(context, raw)
    value = {"schema": SCHEMA, "engineVersion": ENGINE_VERSION, "source": source(context, document),
             "document": document, "report": report(context, document)}
    value["previewSha256"] = digest(value)
    return value


def snapshot_context(review):
    value = review["snapshot"]
    return {**deepcopy(value), "program": {**deepcopy(value["program"]), "version": review["version"] - 1},
            "sources": {row["id"]: deepcopy(row) for row in value["sources"]}}


def validate_review(review, pinned_plan=None):
    try:
        if not isinstance(review, dict) or review.get("purpose") != PURPOSE:
            fail("Select a complete contributor engagement review.")
        ident(review.get("id"), "Original engagement review")
        domain.integer(review.get("version"), "Engagement save version", 2, 10000000)
        domain.timestamp(review.get("createdAt"), "Engagement save timestamp")
        text(review.get("actor"), "Recording operator", 300, True)
        if digest({k: v for k, v in review.items() if k != "sha256"}) != review.get("sha256"):
            fail("The complete engagement review differs from its saved identity.", "ENGAGEMENT_CHANGED", 409)
        if digest(review["snapshot"]) != review.get("businessSha256"):
            fail("The original engagement business snapshot changed.", "ENGAGEMENT_CHANGED", 409)
        context = snapshot_context(review)
        if pinned_plan and (context["plan"]["contentSha256"] != pinned_plan["contentSha256"]
                            or context["plan"]["source"]["sha256"] != pinned_plan["source"]["sha256"]):
            fail("The engagement edition belongs to another pinned plan.", "ENGAGEMENT_SOURCE_CHANGED", 409)
        retained = review["engagements"]
        rebuilt = preview(context, retained["document"])
        if rebuilt != retained:
            fail("The complete engagement edition differs from its original source calculation.", "ENGAGEMENT_CHANGED", 409)
        return review
    except (KeyError, TypeError, ValueError, AttributeError, ArithmeticError) as error:
        if isinstance(error, Problem):
            raise
        fail("The complete engagement review is unreadable: " + str(error))


def summary(review):
    value = review["engagements"]["report"]
    return {k: deepcopy(review[k]) for k in ("id", "version", "createdAt", "actor", "note",
                                             "purpose", "sha256", "businessSha256")} | {
        k: deepcopy(value[k]) for k in ("name", "asOfDate", "agreements", "confirmed", "proposed",
                                        "declined", "withdrawn", "allocatedHours", "remainingCostUsd")} | {
        "supersedes": deepcopy(review["engagements"]["document"]["supersedes"])}


def raw_review(operations, program_id, review_id):
    row = operations.db.execute("SELECT body_json FROM ops_reviews WHERE program_id=? AND id=?",
                               (program_id, ident(review_id, "Engagement review"))).fetchone()
    if row is None:
        fail("The original engagement edition is unavailable.", "ENGAGEMENT_NOT_FOUND", 404)
    return validate_review(json.loads(row[0]))


def load_reviews(operations, program_id, purpose=PURPOSE):
    return [json.loads(row[0]) for row in operations.db.execute(
        "SELECT body_json FROM ops_reviews WHERE program_id=? AND json_extract(body_json,'$.purpose')=? ORDER BY rowid DESC",
        (program_id, purpose))]


def previous_review(operations, context, document):
    selected = document["supersedes"]
    if selected is None:
        return None
    previous = raw_review(operations, context["program"]["id"], selected["reviewId"])
    if previous["sha256"] != selected["reviewSha256"]:
        fail("The preceding complete engagement edition changed.", "ENGAGEMENT_PREVIOUS_CHANGED", 409)
    validate_review(previous, context["plan"])
    return previous


def check_current(context, review):
    validate_review(review, context["plan"])
    original = review["engagements"]
    try:
        current = digest(binding(context, original["document"]))
    except KeyError:
        fail("A selected original contributor or agreement source is unavailable.", "ENGAGEMENT_SOURCE_CHANGED", 409)
    if current != original["source"]["bindingSha256"]:
        fail("A selected contributor, source or pinned plan changed. Review its current engagement edition.",
             "ENGAGEMENT_SOURCE_CHANGED", 409)


def seed(operations, context, review_id=None):
    selected = raw_review(operations, context["program"]["id"], review_id) if review_id else None
    if selected:
        document = deepcopy(selected["engagements"]["document"])
        document["supersedes"] = {"reviewId": selected["id"], "reviewSha256": selected["sha256"]}
    else:
        document = {"schema": SCHEMA, "name": "Contributor engagements", "asOfDate": now()[:10],
                    "agreements": [], "supersedes": None, "note": ""}
    document = normalize(context, document)
    return {"document": document, "source": source(context, document),
        "contributors": deepcopy(context["records"]["contributors"]),
        "packages": deepcopy(context["plan"]["scenario"]["future_costs"]),
        "sources": list(deepcopy(context["sources"]).values()), "previous": summary(selected) if selected else None}


def prepare(operations, context, data, actor, next_version, note):
    obj(data, {"document", "expectedPreviewSha256"}, "Engagement save")
    candidate = preview(context, data.get("document"))
    if candidate["previewSha256"] != domain.sha(data.get("expectedPreviewSha256"), "Reviewed engagement edition", False):
        fail("The engagement inputs or selected sources differ from the reviewed preview.", "ENGAGEMENT_PREVIEW_CHANGED", 409)
    previous = previous_review(operations, context, candidate["document"])
    snapshot = operations._business(context)
    review = {"id": "review-" + uuid.uuid4().hex, "version": next_version, "createdAt": now(),
        "actor": actor, "note": note, "purpose": PURPOSE, "businessSha256": digest(snapshot),
        "snapshot": snapshot, "report": domain.report(**context), "engagements": candidate}
    review["sha256"] = digest(review)
    validate_review(review, context["plan"])
    operations.db.execute("INSERT INTO ops_reviews VALUES(?,?,?)",
                          (context["program"]["id"], review["id"], canonical(review)))
    return {"before": summary(previous) if previous else None, "after": summary(review),
            "kind": "review", "recordId": review["id"], "reviewSha256": review["sha256"]}


def show(operations, context, review_id):
    review = raw_review(operations, context["program"]["id"], review_id)
    original = review["engagements"]
    reason = None
    try:
        check_current(context, review)
    except Problem as error:
        reason = str(error)
    receiving = [receiving_summary(row) for row in load_reviews(operations, context["program"]["id"], RECEIVING_PURPOSE)
                 if row["engagementReceiving"]["book"]["id"] == review["id"]]
    return {"review": review, **{k: deepcopy(original[k]) for k in ("document", "source", "report", "previewSha256")},
        "current": {"programId": context["program"]["id"], "version": context["program"]["version"],
            "sourceChanged": reason is not None, "reason": reason,
            "retainedOriginalProgramId": original["source"]["programId"]}, "receivings": receiving}


def receiving_summary(review):
    value = review["engagementReceiving"]
    return {k: deepcopy(review[k]) for k in ("id", "version", "createdAt", "actor", "note", "purpose", "sha256")} | {
        "book": deepcopy(value["book"]), "forecast": deepcopy(value["forecast"]), "portfolio": deepcopy(value["portfolio"]),
        "allocationStatus": value["allocationStatus"], "readyAlternativeIds": deepcopy(value["readyAlternativeIds"])}


def list_editions(operations, program_id):
    return {"engagements": [summary(row) for row in load_reviews(operations, program_id)],
            "receivings": [receiving_summary(row) for row in load_reviews(operations, program_id, RECEIVING_PURPOSE)]}


def html(review):
    validate_review(review)
    original = review["engagements"]
    document, result = original["document"], original["report"]
    people = {row["contributor"]["id"]: row["contributor"] for row in result["entries"]}
    def e(value):
        return escape("" if value is None else str(value), quote=True)
    def table(headers, body):
        return "<table><thead><tr>" + "".join("<th>" + e(x) + "</th>" for x in headers) + "</tr></thead><tbody>" + "".join(
            "<tr>" + "".join("<td>" + e(x) + "</td>" for x in row) + "</tr>" for row in body) + "</tbody></table>"
    sections = []
    for row in document["agreements"]:
        availability, compensation, acceptance = row["availability"], row["compensation"], row["acceptance"]
        sections.append("<section><h2>" + e(people[row["contributorId"]]["name"]) + " — " + e(row["role"]) +
            "</h2><p>" + e(row["scope"]) + "</p>" +
            table(["Agreement", "Value"], [["Identity", row["id"]], ["Period", row["startDate"] + " through " + row["endDate"]],
                ["Acceptance", acceptance["status"]], ["Confirmed by", acceptance["by"]], ["Original timestamp", acceptance["at"]],
                ["Compensation", compensation["basis"]], ["Hourly USD", compensation["rateUsd"]], ["Total USD", compensation["totalUsd"]],
                ["Payment terms", compensation["paymentTerms"]], ["Native payment mode", compensation["paymentMode"]],
                ["Timing basis", compensation["note"]]]) +
            table(["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
                  [["Unentered" if x is None else x for x in availability["hoursByWeekday"]]]) +
            table(["Date exception", "Available hours"], sorted(availability["hoursByDate"].items())) +
            table(["Original package", "Remaining hours", "Remaining uninvoiced USD", "Basis"],
                  [[x["costId"], x["remainingHours"], x["remainingCostUsd"], x["note"]] for x in row["allocations"]]) +
            "<h3>Original sources</h3><ul>" + "".join('<li><a href="sources/' + e(sid) + '">' + e(sid) + "</a></li>"
                for sid in sorted(set(sid for part in (row, availability, compensation, acceptance) for sid in part["sourceIds"]))) +
            "</ul>" + "".join("<p><strong>" + e(label) + ":</strong> " + e(part["sourceNote"]) + "</p>"
                for label, part in (("Agreement basis", row), ("Availability basis", availability),
                                    ("Compensation basis", compensation), ("Acceptance basis", acceptance))) + "</section>")
    return ("<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
        "<title>" + e(document["name"]) + "</title><style>body{font:15px system-ui,sans-serif;color:#161616;background:#fff;max-width:1100px;margin:32px auto;padding:0 24px;line-height:1.5}h1,h2,h3{line-height:1.2}section{margin:36px 0;padding-top:18px;border-top:1px solid #999}table{border-collapse:collapse;width:100%;margin:16px 0;font-size:14px}th,td{text-align:left;vertical-align:top;padding:8px;border:1px solid #aaa;white-space:pre-wrap;overflow-wrap:anywhere}th{background:#eee}a{color:inherit}small{overflow-wrap:anywhere}@media print{body{margin:0;max-width:none}h2,h3{break-after:avoid}tr{break-inside:avoid}}</style>"
        "<h1>" + e(document["name"]) + "</h1><p>As of " + e(document["asOfDate"]) + " · " + e(result["mode"]) +
        " · " + e(result["confirmed"]) + " confirmed contributors</p><p>" + e(document["note"]) +
        "</p><small>Edition " + e(review["id"]) + " · " + e(review["sha256"]) + "</small>" + "".join(sections) +
        "<footer><p>Reopen the complete case through the original Operations import. All source attachments, agreement editions, forecasts, portfolios and receiving joins are retained in that case.</p></footer></html>").encode("utf-8")


def selected_files(context, reviews, review_id):
    selected = next((row for row in reviews if row["id"] == review_id and row.get("purpose") == PURPOSE), None)
    if selected is None:
        fail("Select a complete engagement edition for export.", "ENGAGEMENT_NOT_FOUND", 404)
    validate_review(selected, context["plan"])
    choice = {"schema": SCHEMA + ".selection", "reviewId": selected["id"], "reviewSha256": selected["sha256"],
              "originalProgramId": selected["engagements"]["source"]["programId"]}
    return {"engagement-selection.json": (canonical(choice) + "\n").encode(), "engagement.html": html(selected)}


def validate_selection(document, files):
    names = {"engagement-selection.json", "engagement.html"}
    if not names.intersection(files):
        return None
    if not names.issubset(files):
        fail("The selected complete engagement handover is missing a member.")
    value = json.loads(files["engagement-selection.json"])
    obj(value, {"schema", "reviewId", "reviewSha256", "originalProgramId"}, "Engagement handover selection")
    if value.get("schema") != SCHEMA + ".selection":
        fail("Use the original engagement handover selection.")
    selected = next((row for row in document["reviews"] if row["id"] == value.get("reviewId") and row.get("purpose") == PURPOSE), None)
    if selected is None:
        fail("The selected engagement edition is absent from its complete case.")
    validate_review(selected, document["plan"])
    expected = {"schema": SCHEMA + ".selection", "reviewId": selected["id"], "reviewSha256": selected["sha256"],
                "originalProgramId": selected["engagements"]["source"]["programId"]}
    if value != expected or files["engagement.html"] != html(selected):
        fail("The selected engagement handover differs from its original edition.")
    return value


def validate_import(context, reviews, events, saved_forecasts, saved_portfolios, files):
    books = {row["id"]: row for row in reviews if row.get("purpose") == PURPOSE}
    receivers = {row["id"]: row for row in reviews if row.get("purpose") == RECEIVING_PURPOSE}
    if {event.get("recordId") for event in events if event.get("action") == "engagement.prepare"} != set(books):
        fail("The complete operations history is missing an engagement edition.")
    if {event.get("recordId") for event in events if event.get("action") == "engagement.receiving"} != set(receivers):
        fail("The complete operations history is missing an engagement receiving record.")
    for review in books.values():
        validate_review(review, context["plan"])
        version = review["version"]
        if not 2 <= version <= len(events):
            fail("The engagement edition has no original save position.")
        event = events[version - 1]
        if (event.get("action") != "engagement.prepare" or event.get("recordId") != review["id"]
                or event.get("after") != summary(review) or review["engagements"]["source"]["version"] != version - 1):
            fail("The engagement edition does not join its original save event.")
        original = snapshot_context(review)
        for sid in source_ids(review["engagements"]["document"]):
            if original["sources"][sid] != context["sources"].get(sid):
                fail("An engagement source differs from the complete case's original attachment.")
        for person in binding(original, review["engagements"]["document"])["contributors"]:
            prior = next((entry.get("after") for entry in reversed(events[:version - 1])
                if entry.get("kind") == "contributors" and entry.get("recordId") == person["id"]), None)
            if prior is None:
                prior = next((entry.get("before") for entry in events[version - 1:]
                    if entry.get("kind") == "contributors" and entry.get("recordId") == person["id"]), None)
            if prior is None:
                prior = next((row for row in context["records"]["contributors"] if row["id"] == person["id"]), None)
            if prior != person:
                fail("A named contributor does not join its original case history.")
        previous = review["engagements"]["document"]["supersedes"]
        if previous:
            old = books.get(previous["reviewId"])
            if old is None or old["sha256"] != previous["reviewSha256"] or old["version"] >= version:
                fail("The preceding engagement edition is absent or differs.")
    from engagement_handover import validate_receiving
    for review in receivers.values():
        validate_receiving(review, books, saved_forecasts, saved_portfolios, context["plan"])
        if not 2 <= review["version"] <= len(events):
            fail("The receiving review has no original save position.")
        event = events[review["version"] - 1]
        if (event.get("action") != "engagement.receiving" or event.get("recordId") != review["id"]
                or event.get("after") != receiving_summary(review)):
            fail("The complete receiving record differs from its original case event.")
    return validate_selection({"reviews": reviews, "plan": context["plan"]}, files)

"""Receive sourced contributor editions through the original Forecast/Portfolio.

This module prepares complete native inputs and checks the retained outputs of
their normal writers. It opens no database or separate allocation engine.
"""
from __future__ import annotations

from copy import deepcopy
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal
import json
import uuid

from model import canonical, digest, now, short_id, text
import operations_domain as domain
import operations_engagements as engagements
import forecast as forecasts
import portfolio as portfolios
import portfolio_installations

ZERO = Decimal("0")
SCHEMA = engagements.SCHEMA + ".receiving"


class _NativeValidation:
    """Reuse successful native calculations only within one receiving operation.

    Every key contains the whole original argument values and the native function.
    A changed source, snapshot, input, report or pinned plan therefore runs the
    original validator again. Nothing is shared between requests or persisted.
    """

    def __init__(self):
        self._values = {}

    def call(self, function, *args):
        try:
            before = digest(args)
        except (TypeError, ValueError, OverflowError):
            # Preserve the original validator's behavior for non-JSON input.
            return function(*args)
        key = (function, before)
        if key in self._values:
            try:
                return deepcopy(self._values[key])
            except MemoryError:
                # A cache is optional; the original native function remains valid.
                pass
        value = function(*args)
        try:
            # Only a calculation that left its complete inputs unchanged can
            # supply a later identical call. Copies never expose cached state.
            if before == digest(args):
                self._values[key] = deepcopy(value)
        except (TypeError, ValueError, OverflowError, MemoryError):
            pass
        return value


def reference(value):
    return {"id": value["id"], "sha256": value["sha256"]}


def selected_agreements(context, book, selection, saved, *, _validation=None):
    engagements.check_current(context, book)
    if (selection.get("reviewId") != book["id"] or selection.get("reviewSha256") != book["sha256"]
            or selection.get("forecastId") != saved["id"]):
        engagements.fail("Keep the exact selected engagement edition and native forecast.",
                         "ENGAGEMENT_SELECTION_CHANGED", 409)
    if _validation is None:
        portfolios.check_source(context, saved)
    else:
        _validation.call(portfolios.check_source, context, saved)
    document = book["engagements"]["document"]
    if document["asOfDate"] != saved["inputs"]["asOfDate"]:
        engagements.fail("Use the same as-of date for the agreement's remaining amounts and the original forecast.")
    values = selection.get("agreementIds")
    if (not isinstance(values, list) or not values or any(not isinstance(v, str) for v in values)
            or len(values) != len(set(values))):
        engagements.fail("Select distinct recorded agreement IDs.")
    index = {row["id"]: row for row in document["agreements"]}
    if any(value not in index for value in values):
        engagements.fail("A selected agreement is absent from the original edition.")
    chosen = [index[value] for value in values]
    as_of = date.fromisoformat(document["asOfDate"])
    for row in chosen:
        if row["acceptance"]["status"] != "CONFIRMED":
            engagements.fail("Choose confirmed agreements for the committed-resource handover.")
        confirmed = datetime.fromisoformat(row["acceptance"]["at"].replace("Z", "+00:00")).astimezone(timezone.utc).date()
        if confirmed > as_of:
            engagements.fail("The original agreement confirmation follows this remaining-work as-of date.")
        if row["endDate"] <= document["asOfDate"] and any(Decimal(x["remainingHours"]) for x in row["allocations"]):
            engagements.fail("Record the current remaining-work period for the selected agreement before allocating its hours.")
    return chosen


def contributions(chosen):
    result = {}
    for agreement in chosen:
        for allocation in agreement["allocations"]:
            value = result.setdefault(allocation["costId"], {"hours": ZERO, "cost": ZERO, "agreements": []})
            value["hours"] += Decimal(allocation["remainingHours"])
            value["cost"] += Decimal(allocation["remainingCostUsd"])
            value["agreements"].append(agreement)
    if not result:
        engagements.fail("Allocate the selected confirmed contributors to at least one original grant package.")
    return result


def forecast_preview(context, book, saved, raw, *, _validation=None):
    raw = engagements.obj(deepcopy(raw), {"reviewId", "reviewSha256", "forecastId", "agreementIds",
        "remainders", "paymentModes", "name", "note"}, "Engagement forecast selection")
    chosen = selected_agreements(context, book, raw, saved, _validation=_validation)
    allocated = contributions(chosen)
    baseline = {row["id"]: row for row in saved["report"]["packages"]}
    if set(allocated) - set(baseline):
        engagements.fail("The selected allocation is absent from the original forecast packages.")
    remainder_index, remainder_rows = {}, []
    if "remainders" in raw:
        for row in engagements.rows(raw["remainders"], "Explicit unassigned package remainders", len(allocated)):
            engagements.obj(row, {"costId", "remainingHours", "remainingCostUsd", "note"}, "Package remainder")
            cost = row.get("costId")
            if cost not in allocated or cost in remainder_index:
                engagements.fail("Enter each affected package remainder exactly once.")
            remainder_index[cost] = {"costId": cost,
                "remainingHours": domain.quantity(row.get("remainingHours"), "Unassigned remaining hours", 4),
                "remainingCostUsd": domain.usd(row.get("remainingCostUsd"), "Unassigned remaining uninvoiced cost"),
                "note": text(row.get("note", ""), "Unassigned remainder basis", 1000)}
        if set(remainder_index) != set(allocated):
            engagements.fail("Explicit remainders must cover every affected original work package.")
    else:
        for cost, amount in allocated.items():
            old = baseline[cost]
            remainder_index[cost] = {"costId": cost,
                "remainingHours": forecasts.hours(max(ZERO, Decimal(old["remainingHours"]) - amount["hours"])),
                "remainingCostUsd": forecasts.money(max(ZERO, Decimal(old["remainingCostUsd"]) - amount["cost"])),
                "note": "Original remaining package estimate less selected confirmed allocations; a larger confirmed allocation increases the reviewed total."}
    modes = {}
    if "paymentModes" in raw:
        for row in engagements.rows(raw["paymentModes"], "Reviewed package payment modes", len(allocated)):
            engagements.obj(row, {"costId", "paymentMode", "note"}, "Package payment mode")
            cost = row.get("costId")
            if cost not in allocated or cost in modes:
                engagements.fail("Enter each affected package payment mode exactly once.")
            modes[cost] = {"costId": cost, "paymentMode": domain.enum(row.get("paymentMode"),
                ("original", "accrual", "completion"), "Original Forecast payment mode"),
                "note": text(row.get("note", ""), "Reviewed payment timing basis", 1000)}
        if set(modes) != set(allocated):
            engagements.fail("Explicit payment modes must cover every affected original package.")
    else:
        for cost, amount in allocated.items():
            values = {row["compensation"]["paymentMode"] for row in amount["agreements"]}
            if len(values) != 1:
                engagements.fail(cost + ": choose the reviewed native payment schedule for the combined package.")
            modes[cost] = {"costId": cost, "paymentMode": next(iter(values)),
                "note": "Common native payment mode from the selected original contributor agreements."}

    selection = {"reviewId": book["id"], "reviewSha256": book["sha256"], "forecastId": saved["id"],
        "agreementIds": list(raw["agreementIds"]),
        "remainders": [remainder_index[key] for key in sorted(allocated)],
        "paymentModes": [modes[key] for key in sorted(allocated)],
        "name": text(raw.get("name") or "Agreed delivery — " + book["engagements"]["document"]["name"],
                     "Received forecast name", 300, True),
        "note": text(raw.get("note", ""), "Contributor forecast basis", 4000)}
    inputs = deepcopy(saved["inputs"])
    inputs["name"] = selection["name"]
    inputs["note"] = text(inputs.get("note", "") + "\n\nContributor agreement edition " + book["id"] +
        ". " + selection["note"], "Complete forecast basis", 12000)
    overrides = {row["costId"]: deepcopy(row) for row in inputs["packageOverrides"]}
    projection = []
    first = (date.fromisoformat(inputs["asOfDate"]) + timedelta(days=1)).isoformat()
    for cost in sorted(allocated):
        amount, remainder, mode, old = allocated[cost], remainder_index[cost], modes[cost], baseline[cost]
        remaining_hours = amount["hours"] + Decimal(remainder["remainingHours"])
        remaining_cost = amount["cost"] + Decimal(remainder["remainingCostUsd"])
        starts = [max(first, row["startDate"]) for row in amount["agreements"]]
        ends = [max(first, row["endDate"]) for row in amount["agreements"]]
        if Decimal(remainder["remainingHours"]) or Decimal(remainder["remainingCostUsd"]):
            starts.append(old["startDate"])
            ends.append(old["endDate"])
        original = overrides.get(cost, {"costId": cost, "remainingCostUsd": None, "remainingHours": None,
            "startDate": None, "endDate": None, "paymentMode": "original", "directCashIds": [], "note": ""})
        original.update({"remainingHours": forecasts.hours(remaining_hours),
            "remainingCostUsd": forecasts.money(remaining_cost), "startDate": min(starts), "endDate": max(ends),
            "paymentMode": mode["paymentMode"],
            "note": text("Contributor agreement edition " + book["id"] + "; confirmed allocations " +
                forecasts.hours(amount["hours"]) + " hours / USD " + forecasts.money(amount["cost"]) +
                "; unassigned remainder " + remainder["remainingHours"] + " hours / USD " + remainder["remainingCostUsd"] +
                ". " + remainder["note"] + " " + mode["note"], "Package receiving basis", 4000)})
        overrides[cost] = original
        projection.append({"costId": cost, "engagementIds": [row["id"] for row in amount["agreements"]],
            "originalHours": old["remainingHours"], "originalCostUsd": old["remainingCostUsd"],
            "confirmedHours": forecasts.hours(amount["hours"]), "confirmedCostUsd": forecasts.money(amount["cost"]),
            "remainderHours": remainder["remainingHours"], "remainderCostUsd": remainder["remainingCostUsd"],
            "remainingHours": original["remainingHours"], "remainingCostUsd": original["remainingCostUsd"],
            "hoursDelta": forecasts.hours(remaining_hours - Decimal(old["remainingHours"])),
            "costDeltaUsd": forecasts.money(remaining_cost - Decimal(old["remainingCostUsd"])),
            "paymentMode": mode["paymentMode"], "directCashIds": deepcopy(original["directCashIds"]),
            "startDate": original["startDate"], "endDate": original["endDate"]})
    existing_order = [row["costId"] for row in inputs["packageOverrides"]]
    inputs["packageOverrides"] = [overrides[key] for key in existing_order] + [
        overrides[key] for key in sorted(set(overrides) - set(existing_order))]
    candidate = (forecasts.preview(context, inputs) if _validation is None else
                 _validation.call(forecasts.preview, context, inputs))
    return {"selection": selection, "inputs": candidate["inputs"], "forecast": candidate,
        "projection": {"packages": projection, "timingBasis": candidate["report"].get("paymentTimingBasis",
            "Each original package uses its selected native Forecast payment mode and retains its original direct payments.")},
        "source": {"book": reference(book), "baseForecast": reference(saved),
                   "bindingSha256": book["engagements"]["source"]["bindingSha256"],
                   "selectionSha256": digest(selection)}}


def resource(agreement, person, resource_id, calendar):
    # apply() has normalized this exact calendar against the original saved forecast.
    normalized = calendar
    start = date.fromisoformat(normalized["startDate"])
    end = start + timedelta(days=normalized["horizonDays"] - 1)
    overrides = {stamp: value for stamp, value in agreement["availability"]["hoursByDate"].items()
                 if start.isoformat() <= stamp <= end.isoformat()}
    for offset in range(normalized["horizonDays"]):
        stamp = (start + timedelta(days=offset)).isoformat()
        if stamp < agreement["startDate"] or stamp > agreement["endDate"]:
            overrides[stamp] = "0"
    return {"id": resource_id, "name": person["name"],
        "hoursByWeekday": deepcopy(agreement["availability"]["hoursByWeekday"]),
        "hoursByDate": dict(sorted(overrides.items())),
        "note": text("Confirmed " + agreement["role"] + ": " + agreement["startDate"] + " through " +
            agreement["endDate"] + ". " + agreement["availability"]["note"],
            "Received contributor availability", 12000)}


def portfolio_preview(context, book, saved, raw, *, _validation=None):
    raw = engagements.obj(deepcopy(raw), {"reviewId", "reviewSha256", "forecastId", "agreementIds",
        "resourceMap", "inputs", "name", "note"}, "Engagement portfolio selection")
    chosen = selected_agreements(context, book, raw, saved, _validation=_validation)
    allocated = contributions(chosen)
    mapping, resource_ids = {}, set()
    for row in engagements.rows(raw.get("resourceMap"), "Named resource mappings", len(chosen)):
        engagements.obj(row, {"engagementId", "resourceId"}, "Resource mapping")
        agreement_id = row.get("engagementId")
        if agreement_id not in {r["id"] for r in chosen} or agreement_id in mapping:
            engagements.fail("Map every selected agreement exactly once.")
        resource_id = short_id(row.get("resourceId"), "Original or new Portfolio resource ID")
        if resource_id in resource_ids:
            engagements.fail("Each named contributor needs a distinct resource in the shared allocation.")
        resource_ids.add(resource_id)
        mapping[agreement_id] = resource_id
    if set(mapping) != {row["id"] for row in chosen}:
        engagements.fail("Map every selected confirmed contributor to a Portfolio resource.")

    original_inputs = deepcopy(raw["inputs"]) if "inputs" in raw else portfolios.seed(context, saved)["inputs"]
    if not isinstance(original_inputs, dict):
        engagements.fail("Retain a complete original Portfolio input object.")
    inputs = deepcopy(original_inputs)
    inputs.update({"forecastId": saved["id"], "forecastSha256": saved["sha256"],
        "name": text(raw.get("name") or "Committed allocation — " + book["engagements"]["document"]["name"],
                     "Received allocation name", 300, True)})
    note = text(raw.get("note", ""), "Contributor allocation basis", 4000)
    inputs["note"] = text(inputs.get("note", "") + "\n\nContributor agreement edition " + book["id"] +
        ". " + note, "Complete allocation basis", 12000)
    people = {row["id"]: row for row in context["records"]["contributors"]}
    original_fields = {key: deepcopy(inputs.get(key)) for key in ("calendar", "resources", "tasks")}
    if not isinstance(original_fields["resources"], list) or not isinstance(original_fields["tasks"], list):
        engagements.fail("Retain the complete original resources and source-task array.")
    changes = []

    def apply(fields, alternative_id):
        calendar = portfolios.normalize_calendar(fields["calendar"], saved)
        old_resources = portfolios.normalize_resources(fields["resources"])
        lookup = {row["id"]: deepcopy(row) for row in old_resources}
        for agreement in chosen:
            rid = mapping[agreement["id"]]
            previous = lookup.get(rid)
            lookup[rid] = resource(agreement, people[agreement["contributorId"]], rid, calendar)
            changes.append({"alternativeId": alternative_id, "engagementId": agreement["id"],
                "contributorId": agreement["contributorId"], "resourceId": rid,
                "replacesExistingResource": previous is not None,
                "period": {"startDate": agreement["startDate"], "endDate": agreement["endDate"]},
                "beforeResourceSha256": digest(previous) if previous else None,
                "resourceSha256": digest(lookup[rid])})
        order = [row["id"] for row in old_resources]
        resources = [lookup[rid] for rid in order] + [lookup[rid] for rid in sorted(set(lookup) - set(order))]
        tasks = deepcopy(fields["tasks"])
        task_ids = [row.get("id") for row in tasks if isinstance(row, dict)]
        if len(task_ids) != len(tasks) or len(task_ids) != len(set(task_ids)):
            engagements.fail("Retain the original complete distinct task assignments.")
        task_map = {row["id"]: row for row in tasks}
        for cost, amount in allocated.items():
            task = task_map.get("package/" + cost)
            if task is None or not isinstance(task.get("effortHours"), dict):
                engagements.fail("The original grant-package task is unavailable in the selected full allocation.")
            effort = deepcopy(task["effortHours"])
            for rid in resource_ids:
                effort.pop(rid, None)
            for agreement in amount["agreements"]:
                value = next(row for row in agreement["allocations"] if row["costId"] == cost)
                effort[mapping[agreement["id"]]] = value["remainingHours"]
            task["effortHours"] = effort
        return {"calendar": calendar, "resources": resources, "tasks": tasks}

    updated = apply(original_fields, "base")
    inputs.update(updated)
    alternatives = original_inputs.get("alternatives", [])
    if not isinstance(alternatives, list):
        engagements.fail("Retain the complete original allocation alternatives.")
    updated_alternatives = []
    for alternative in alternatives:
        if not isinstance(alternative, dict):
            engagements.fail("Retain complete original allocation alternative objects.")
        changed = deepcopy(alternative)
        fields = {key: deepcopy(alternative.get(key, original_fields[key])) for key in original_fields}
        applied = apply(fields, alternative.get("id"))
        changed["resources"] = applied["resources"]
        changed["tasks"] = applied["tasks"]
        # The original calendar/Installation phase selections stay exactly authored.
        updated_alternatives.append(changed)
    inputs["alternatives"] = updated_alternatives
    candidate = (portfolios.preview(context, saved, inputs) if _validation is None else
                 _validation.call(portfolios.preview, context, saved, inputs))
    selection = {"reviewId": book["id"], "reviewSha256": book["sha256"], "forecastId": saved["id"],
        "agreementIds": list(raw["agreementIds"]),
        "resourceMap": [{"engagementId": row["id"], "resourceId": mapping[row["id"]]} for row in chosen],
        "inputs": original_inputs, "name": inputs["name"], "note": note}
    return {"selection": selection, "inputs": candidate["inputs"], "portfolio": candidate,
        "projection": {"resources": changes, "affectedPackageIds": sorted(allocated),
                       "comparison": deepcopy(candidate["report"]["comparison"])},
        "source": {"book": reference(book), "forecast": reference(saved),
                   "bindingSha256": book["engagements"]["source"]["bindingSha256"],
                   "selectionSha256": digest(selection)}}


def lookup_forecast(operations, context, forecast_id, *, _validation=None):
    value = operations._portfolio_forecast(context["program"]["id"], forecast_id)
    if _validation is None:
        forecasts.validate_saved(value, context["plan"])
    else:
        _validation.call(forecasts.validate_saved, value, context["plan"])
    return value


def preview_forecast(operations, context, selection):
    book = engagements.raw_review(operations, context["program"]["id"], selection.get("reviewId"))
    saved = lookup_forecast(operations, context, selection.get("forecastId"))
    return forecast_preview(context, book, saved, selection)


def preview_portfolio(operations, context, selection):
    book = engagements.raw_review(operations, context["program"]["id"], selection.get("reviewId"))
    saved = lookup_forecast(operations, context, selection.get("forecastId"))
    context = portfolio_installations.capture(operations, context, selection.get("inputs"))
    return portfolio_preview(context, book, saved, selection)


def validate_join(book, saved_forecast, saved_portfolio, base_forecast, data, pinned_plan=None,
                  *, _validation=None):
    validation = _validation if _validation is not None else _NativeValidation()
    validation.call(engagements.validate_review, book, pinned_plan)
    validation.call(forecasts.validate_saved, base_forecast, pinned_plan)
    validation.call(forecasts.validate_saved, saved_forecast, pinned_plan)
    validation.call(portfolios.validate_saved, saved_portfolio, pinned_plan)
    if (data.get("reviewId") != book["id"] or data.get("reviewSha256") != book["sha256"]
            or data.get("forecastId") != saved_forecast["id"] or data.get("portfolioId") != saved_portfolio["id"]):
        engagements.fail("Keep the complete original agreement, forecast and allocation selection.", "ENGAGEMENT_RECEIVING_CHANGED", 409)
    finance = forecast_preview(saved_forecast["snapshot"], book, base_forecast, data["forecastSelection"],
                               _validation=validation)
    allocation = portfolio_preview(saved_portfolio["snapshot"], book, saved_forecast, data["portfolioSelection"],
                                   _validation=validation)
    if (data["forecastSelection"] != finance["selection"] or data["portfolioSelection"] != allocation["selection"]
            or saved_forecast["inputs"] != finance["inputs"] or saved_forecast["report"] != finance["forecast"]["report"]
            or saved_portfolio["inputs"] != allocation["inputs"] or saved_portfolio["report"] != allocation["portfolio"]["report"]
            or saved_portfolio["baseForecastSnapshot"] != saved_forecast):
        engagements.fail("The saved native outputs differ from the complete reviewed contributor handover.",
                         "ENGAGEMENT_RECEIVING_CHANGED", 409)
    return finance, allocation


def receive(operations, context, data, actor, next_version, note):
    engagements.obj(data, {"reviewId", "reviewSha256", "forecastId", "portfolioId",
                           "forecastSelection", "portfolioSelection"}, "Complete contributor receiving")
    if not isinstance(data.get("forecastSelection"), dict) or not isinstance(data.get("portfolioSelection"), dict):
        engagements.fail("Retain both complete normalized native handover selections.")
    book = engagements.raw_review(operations, context["program"]["id"], data.get("reviewId"))
    engagements.check_current(context, book)
    validation = _NativeValidation()
    saved_forecast = lookup_forecast(operations, context, data.get("forecastId"), _validation=validation)
    base = lookup_forecast(operations, context, data["forecastSelection"].get("forecastId"), _validation=validation)
    raw = operations.db.execute("SELECT body_json FROM ops_portfolios WHERE program_id=? AND id=?",
                                (context["program"]["id"], data.get("portfolioId"))).fetchone()
    if not raw:
        engagements.fail("The original saved allocation is unavailable.", "PORTFOLIO_NOT_FOUND", 404)
    saved_portfolio = json.loads(raw[0])
    finance, allocation = validate_join(book, saved_forecast, saved_portfolio, base, data, context["plan"],
                                        _validation=validation)
    snapshot = operations._business(context)
    received = {"schema": SCHEMA, "engineVersion": engagements.ENGINE_VERSION,
        "book": reference(book), "baseForecast": reference(base), "forecast": reference(saved_forecast),
        "portfolio": reference(saved_portfolio), "forecastSelection": finance["selection"],
        "portfolioSelection": allocation["selection"],
        "financialProjection": finance["projection"], "allocationProjection": allocation["projection"],
        "allocationStatus": saved_portfolio["report"]["alternatives"][0]["status"],
        "readyAlternativeIds": [row["id"] for row in saved_portfolio["report"]["alternatives"] if row["status"] == "READY"]}
    review = {"id": "review-" + uuid.uuid4().hex, "version": next_version, "createdAt": now(),
        "actor": actor, "note": note, "purpose": engagements.RECEIVING_PURPOSE,
        "businessSha256": digest(snapshot), "snapshot": snapshot, "report": domain.report(**context),
        "engagementReceiving": received}
    review["sha256"] = digest(review)
    validate_receiving(review, {book["id"]: book}, [base, saved_forecast], [saved_portfolio], context["plan"],
                       _validation=validation)
    operations.db.execute("INSERT INTO ops_reviews VALUES(?,?,?)",
                          (context["program"]["id"], review["id"], canonical(review)))
    return {"before": None, "after": engagements.receiving_summary(review), "kind": "review",
            "recordId": review["id"], "reviewSha256": review["sha256"],
            "book": reference(book), "forecast": reference(saved_forecast), "portfolio": reference(saved_portfolio)}


def _validate_receiving(review, books, saved_forecasts, saved_portfolios, pinned_plan=None,
                        *, _validation=None):
    if not isinstance(review, dict) or review.get("purpose") != engagements.RECEIVING_PURPOSE:
        engagements.fail("Select a complete contributor receiving review.")
    engagements.ident(review.get("id"), "Original receiving review")
    domain.integer(review.get("version"), "Receiving save version", 2, 10000000)
    domain.timestamp(review.get("createdAt"), "Receiving save timestamp")
    text(review.get("actor"), "Receiving operator", 300, True)
    if (digest({key: value for key, value in review.items() if key != "sha256"}) != review.get("sha256")
            or digest(review["snapshot"]) != review.get("businessSha256")):
        engagements.fail("The complete contributor receiving review changed.", "ENGAGEMENT_RECEIVING_CHANGED", 409)
    value = review["engagementReceiving"]
    if value.get("schema") != SCHEMA or value.get("engineVersion") != engagements.ENGINE_VERSION:
        engagements.fail("Use the supported complete contributor receiving edition.")
    forecasts_by_id = {row["id"]: row for row in saved_forecasts}
    portfolios_by_id = {row["id"]: row for row in saved_portfolios}
    book = books.get(value["book"]["id"])
    base = forecasts_by_id.get(value["baseForecast"]["id"])
    forecast = forecasts_by_id.get(value["forecast"]["id"])
    portfolio = portfolios_by_id.get(value["portfolio"]["id"])
    if any(item is None for item in (book, base, forecast, portfolio)):
        engagements.fail("The complete case is missing an original receiving component.")
    for label, original in (("book", book), ("baseForecast", base), ("forecast", forecast), ("portfolio", portfolio)):
        if reference(original) != value[label] or original["version"] >= review["version"]:
            engagements.fail("An original receiving component differs from its retained selection.")
    finance, allocation = validate_join(book, forecast, portfolio, base, {
        "reviewId": book["id"], "reviewSha256": book["sha256"], "forecastId": forecast["id"],
        "portfolioId": portfolio["id"], "forecastSelection": value["forecastSelection"],
        "portfolioSelection": value["portfolioSelection"]}, pinned_plan, _validation=_validation)
    if finance["projection"] != value["financialProjection"] or allocation["projection"] != value["allocationProjection"]:
        engagements.fail("The contributor receiving projections differ from the original native outputs.")
    if (value.get("allocationStatus") != portfolio["report"]["alternatives"][0]["status"]
            or value.get("readyAlternativeIds") != [row["id"] for row in portfolio["report"]["alternatives"] if row["status"] == "READY"]):
        engagements.fail("The retained allocation outcome differs from the original native comparison.")
    return review


def validate_receiving(review, books, saved_forecasts, saved_portfolios, pinned_plan=None,
                       *, _validation=None):
    try:
        return _validate_receiving(review, books, saved_forecasts, saved_portfolios, pinned_plan,
                                   _validation=_validation)
    except (KeyError, TypeError, ValueError, AttributeError, ArithmeticError, IndexError) as error:
        from model import Problem
        if isinstance(error, Problem):
            raise
        engagements.fail("The complete contributor receiving record is unreadable: " + str(error))

"""Reviewed baseline amendments in the existing SF47 operations transaction.

The native planner remains the calculation and revision authority. This module
selects its saved revisions and retains complete amendment decisions. Explicit
package mappings change only budget attribution on existing work, invoice and
deployment records; original observations remain in the complete case history.
"""
