}

/* Neutral, compact operator layout. */
.commercial-desk { color:#202124; background:#fff; font:inherit; max-width:1200px; margin:0 auto; }
.commercial-desk * { box-sizing:border-box; }
.commercial-desk h2 { font-size:1.35rem; margin:0 0 .5rem; }
.commercial-desk h3 { font-size:1.1rem; margin:0 0 .75rem; }
.commercial-desk h4 { font-size:1rem; margin:0 0 .35rem; }
.commercial-desk p { line-height:1.5; margin:.4rem 0 .9rem; }
.commercial-desk button { border:1px solid #777; border-radius:3px; background:#f7f7f7; color:#202124; padding:.55rem .8rem; font:inherit; cursor:pointer; }
.commercial-desk button:hover:not(:disabled) { background:#ececec; }
.commercial-desk button:disabled { opacity:.55; cursor:default; }
.commercial-desk :focus-visible { outline:2px solid #333; outline-offset:3px; }
.commercial-heading { display:flex; flex-wrap:wrap; gap:.75rem 1.25rem; justify-content:space-between; align-items:flex-start; }
.commercial-heading > div:first-child { flex:1 1 18rem; }
.commercial-actions { display:flex; gap:.5rem; flex-wrap:wrap; align-items:center; margin:.5rem 0; }
.commercial-card,.commercial-connection { margin:1.1rem 0; border:1px solid #c4c4c4; border-radius:3px; padding:1.1rem; }
.commercial-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,15rem),1fr)); gap:1rem; margin:.6rem 0 1rem; }
.commercial-field { display:flex; flex-direction:column; gap:.4rem; min-width:0; margin:.4rem 0 1rem; }
.commercial-field > span { font-weight:600; }
.commercial-field input,.commercial-field select,.commercial-field textarea { width:100%; max-width:100%; min-height:2.5rem; border:1px solid #999; border-radius:2px; background:#fff; color:#202124; font:inherit; padding:.5rem; }
.commercial-field select[multiple] { min-height:6rem; }
.commercial-field small { color:#555; line-height:1.4; }
.commercial-milestone { border:1px solid #bbb; margin:1rem 0; padding:.9rem; min-width:0; }
.commercial-milestone legend { font-weight:600; padding:0 .3rem; max-width:100%; }
.commercial-terms { white-space:pre-wrap; overflow-wrap:anywhere; }
.commercial-summary { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,11rem),1fr)); gap:.75rem 1rem; margin:1rem 0; }
.commercial-summary div { min-width:0; }
.commercial-summary dt { color:#555; font-size:.9rem; }
.commercial-summary dd { margin:.25rem 0 0; font-weight:600; overflow-wrap:anywhere; font-variant-numeric:tabular-nums; }
.commercial-saved-milestone { border-top:1px solid #ddd; padding:1rem 0 .5rem; }
.commercial-preview { border:1px solid #888; padding:1rem; margin:1rem 0; background:#fafafa; }
.commercial-table-scroll { max-width:100%; overflow-x:auto; }
.commercial-desk table { width:100%; border-collapse:collapse; margin:.5rem 0; }
.commercial-desk th,.commercial-desk td { padding:.6rem; border-bottom:1px solid #ccc; text-align:left; vertical-align:top; }
.commercial-desk th:not(:first-child),.commercial-desk td:not(:first-child) { text-align:right; white-space:nowrap; font-variant-numeric:tabular-nums; }
.commercial-total { text-align:right; font-weight:700; }
.commercial-empty { border-left:3px solid #aaa; padding:.5rem .75rem; background:#f7f7f7; }
.commercial-message:empty { display:none; }
.commercial-message { padding:.75rem; border:1px solid #999; background:#f5f5f5; }
.commercial-message[role=alert] { border-left:4px solid #444; }
.commercial-connection summary { cursor:pointer; font-weight:600; padding:.2rem 0; }
@media (max-width:600px) {
  .commercial-card,.commercial-connection { padding:.8rem; }
  .commercial-heading { display:block; }
  .commercial-actions > button { flex:1 1 10rem; }
  .commercial-preview { padding:.7rem; }
  .commercial-desk th,.commercial-desk td { padding:.45rem; }
}

