def fail(message, code="INVALID_IMPLEMENTATION_EVIDENCE", status=422):
    raise Problem(message, status, code)


def obj(value, fields, label):
    if not isinstance(value, dict) or set(value) - set(fields):
        fail("Use the declared " + label + ".")
    return value


def utc_now():
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def instant(value, label="UTC observation cutoff"):
    value = text(value, label, 40, True)
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if parsed.tzinfo is None or parsed.utcoffset().total_seconds() != 0 or \
                parsed.isoformat(timespec="milliseconds").replace("+00:00", "Z") != value:
            raise ValueError()
    except (ValueError, AttributeError) as exc:
        raise Problem("Use a UTC time including milliseconds for " + label + ".", 422,
                      "IMPLEMENTATION_CUTOFF") from exc
    return value


def at(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def scalar_id(value, label="Original implementation identity"):
    value = text(value, label, 160, True)
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,159}", value):
        fail("Use the retained " + label.lower() + ".")
    return value


def _typed_equal(left, right):
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if isinstance(left, dict) and isinstance(right, dict):
        return set(left) == set(right) and all(_typed_equal(left[key], right[key]) for key in left)
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(_typed_equal(a, b) for a, b in zip(left, right))
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    return type(left) is type(right) and left == right


def original_state(raw):
    """Unwrap original bytes, without re-rendering or executing their contents."""
    try:
        document = json.loads(raw.decode("utf-8"))
        schema = document["schema"]
        if schema == "stellar-forge.merchant-commissioning.v1":
            state, format_name = document, "commissioning"
        elif schema == "stellar-forge.merchant-workspace.v1":
            state, format_name = document["commissioning"], "workspace"
        elif schema == "stellar-forge.merchant-support-handoff.v1":
            workspace = document["workspaceText"].encode("utf-8")
            support = document["supportText"].encode("utf-8")
            if hashlib.sha256(workspace).hexdigest() != document["sha256"]["workspace"] or \
                    hashlib.sha256(support).hexdigest() != document["sha256"]["support"]:
                fail("The original Support source hashes differ.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
            state = json.loads(document["workspaceText"])["commissioning"]
            format_name = "support-handoff"
        else:
            fail("Select the original implementation, merchant workspace or Support handoff.",
                 "IMPLEMENTATION_SOURCE_KIND")
        if not isinstance(state, dict) or state.get("schema") != "stellar-forge.merchant-commissioning.v1":
            fail("The source contains no original implementation.", "IMPLEMENTATION_NOT_PRESENT")
        if not isinstance(state.get("blobs"), dict):
            fail("The original implementation file store is missing.")
        return document, state, format_name
    except (ValueError, UnicodeError, KeyError, TypeError) as exc:
        if isinstance(exc, Problem):
            raise
        raise Problem("The complete original implementation source is unreadable.", 422,
                      "IMPLEMENTATION_SOURCE_INVALID") from exc


def original_files(raw):
    _, state, _ = original_state(raw)
    result = {}
    for sha, blob in state["blobs"].items():
        domain.sha(sha, "Original file SHA-256", False)
        if not isinstance(blob, dict) or set(blob) != {"bytes", "data"} or \
                not isinstance(blob["bytes"], int) or isinstance(blob["bytes"], bool) or \
                not isinstance(blob["data"], str):
            fail("The original file descriptor changed.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
        try:
            value = base64.b64decode(blob["data"], validate=True)
        except (ValueError, TypeError) as exc:
            raise Problem("An original file encoding changed.", 409, "IMPLEMENTATION_SOURCE_CHANGED") from exc
        if base64.b64encode(value).decode("ascii") != blob["data"] or len(value) != blob["bytes"] or \
                hashlib.sha256(value).hexdigest() != sha:
            fail("An original implementation file differs from its retained hash.",
                 "IMPLEMENTATION_SOURCE_CHANGED", 409)
        result[sha] = value
    return result


def validate_native(native, metadata, raw=None):
    if not isinstance(native, dict) or native.get("schema") != SOURCE_SCHEMA or \
            not isinstance(native.get("state"), dict) or not isinstance(native.get("originalState"), dict):
        fail("The retained native implementation projection is incomplete.")
    instant(native.get("asOfAt"))
    if native.get("source", {}).get("sha256") != metadata["sha256"] or \
            native.get("source", {}).get("bytes") != metadata["bytes"]:
        fail("The implementation projection identifies another source.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
    domain.sha(native.get("projectionSha256"), "Original Node projection digest", False)
    if not isinstance(native.get("reader"), dict) or not native["reader"]:
        fail("Retain the original native reader identities.")
    for value in native["reader"].values():
        domain.sha(value, "Original reader source SHA-256", False)
    state = native["state"]
    for key in ("tasks", "receiving", "measurements", "materials", "editions", "events"):
        rows = state.get(key)
        if not isinstance(rows, list) or any(not isinstance(row, dict) for row in rows):
            fail("The original implementation " + key + " are incomplete.")
        ids = [scalar_id(row.get("id")) for row in rows]
        if len(set(ids)) != len(ids):
            fail("The native source repeats an original " + key + " identity.")
    for key, source_key in (("receivingStatus", "receiving"), ("measurementStatus", "measurements")):
        statuses = native.get(key)
        if not isinstance(statuses, list) or len(statuses) != len(state[source_key]) or \
                {row.get("id") for row in statuses} != {row["id"] for row in state[source_key]}:
            fail("The native observation-status projection is incomplete.")
        for row in statuses:
            if not isinstance(row.get("withinCutoff"), bool) or not isinstance(row.get("activeEdition"), bool):
                fail("Retain explicit original observation status.")
    if not isinstance(native.get("comparisons"), list) or not isinstance(native.get("summary"), dict) or \
            not isinstance(native.get("currentSummary"), dict) or not isinstance(native.get("originalReportHtml"), str):
        fail("The complete producer calculation and readable original report are required.")
    for key in ("originalFiles", "sourceBundles", "externalFiles"):
        if not isinstance(native.get(key), list):
            fail("Retain the producer's complete original source-bundle inventory.")
    external = {}
    for row in native["externalFiles"]:
        if not isinstance(row, dict) or not isinstance(row.get("sourceFile"), dict):
            fail("An original external file reference is missing.")
        sha = domain.sha(row.get("sha256"), "External original SHA-256", False)
        size = domain.integer(row.get("bytes"), "External original bytes", 0, 1024 * 1024 * 1024)
        if sha in external and external[sha] != size:
            fail("The original source inventory reuses a digest with different bytes.")
        external[sha] = size
    if raw is not None:
        if len(raw) != metadata["bytes"] or hashlib.sha256(raw).hexdigest() != metadata["sha256"]:
            fail("The original implementation bytes changed.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
        document, source_state, format_name = original_state(raw)
        projected = deepcopy(source_state)
        projected.pop("blobs")
        if not _typed_equal(projected, native["originalState"]) or \
                native.get("origin", {}).get("format") != format_name or document["schema"] != native["source"]["schema"]:
            fail("The frozen projection does not retain its original source fields.",
                 "IMPLEMENTATION_SOURCE_CHANGED", 409)
        expected = deepcopy(projected)
        # The producer fills omitted plan strings; all original supplied fields stay exact.
        if isinstance(expected.get("plan"), dict) and isinstance(state.get("plan"), dict):
            expected["plan"] = {key: expected["plan"].get(key, "") for key in state["plan"]}
        if not _typed_equal(expected, state):
            fail("The normalized implementation differs from its original source.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
        files = original_files(raw)
        expected_files = [{"sha256": sha, "bytes": len(value)} for sha, value in sorted(files.items())]
        if native.get("files") != expected_files:
            fail("The original implementation file inventory is incomplete.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
    return native


def inspect(raw, as_of):
    import os
    as_of = instant(as_of)
    selected = os.environ.get("SF47_SUPPORT_NODE") or shutil.which("node")
    if not selected or not Path(selected).is_absolute() or not Path(selected).is_file():
        fail("The installed original Support reader needs its configured Node executable.",
             "IMPLEMENTATION_NODE_UNAVAILABLE", 503)
    if not raw or len(raw) > MAX_SOURCE:
        fail("Select a complete original source up to 8 MiB.", "IMPLEMENTATION_SOURCE_SIZE", 413)
    if not _READER.acquire(blocking=False):
        fail("Another implementation source is being read. Continue this same source selection when it finishes.",
             "IMPLEMENTATION_READER_BUSY", 409)
    try:
        try:
            completed = subprocess.run([selected, "--max-old-space-size=192", str(_HELPER), "--as-of", as_of],
                input=raw, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30, check=False)
        except subprocess.TimeoutExpired as exc:
            raise Problem("The original source reader timed out. Its saved source remains available.",
                          503, "IMPLEMENTATION_READER_TIMEOUT") from exc
        except OSError as exc:
            raise Problem("The installed original reader could not start.", 503,
                          "IMPLEMENTATION_READER_UNAVAILABLE") from exc
        if len(completed.stdout) > MAX_READER_OUTPUT:
            fail("The complete native projection exceeds the receiving bound.", "IMPLEMENTATION_REVIEW_SIZE", 413)
        try:
            result = json.loads(completed.stdout)
        except (ValueError, UnicodeError) as exc:
            raise Problem("The native reader did not return a complete source projection.", 503,
                          "IMPLEMENTATION_READER_UNAVAILABLE") from exc
        if not isinstance(result, dict) or result.get("ok") is not True:
            error = result.get("error", {}) if isinstance(result, dict) else {}
            code = error.get("code", "IMPLEMENTATION_SOURCE_INVALID")
            if not isinstance(code, str) or not re.fullmatch(r"[A-Z0-9_]{1,100}", code):
                code = "IMPLEMENTATION_SOURCE_INVALID"
            fail(str(error.get("message", "The selected source is invalid."))[:1200], code,
                 413 if error.get("status") == 413 else 422)
        if completed.returncode:
            fail("The native source read did not finish.", "IMPLEMENTATION_READER_UNAVAILABLE", 503)
        metadata = {"sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}
        return validate_native(result.get("result"), metadata, raw)
    finally:
        _READER.release()


def verify_projection(native, metadata, raw):
    """Reopen the exact source through the maintained producer before using it."""
    validate_native(native, metadata, raw)
    actual = inspect(raw, native["asOfAt"])
    if actual.get("reader") != native.get("reader"):
        fail("The installed implementation reader differs from this frozen review. Retain its historical projection and use the original published reader release to verify it.",
             "IMPLEMENTATION_READER_PROVENANCE_MISMATCH", 409)
    if not _typed_equal(actual, native):
        fail("The frozen implementation projection differs from the producer's actual read of the exact original source and cutoff.",
             "IMPLEMENTATION_PROJECTION_MISMATCH", 409)
    return actual


def verify_review(review, read_source):
    validate_review(review)
    native = review["implementation"]["native"]
    metadata, raw = read_source(review["implementation"]["inputs"]["sourceId"])
    verify_projection(native, metadata, raw)
    for source in review["implementation"]["bindings"]["sources"]:
        actual, original = read_source(source["id"])
        if actual["sha256"] != source["sha256"] or len(original) != source["bytes"] or hashlib.sha256(original).hexdigest() != source["sha256"]:
            fail("A frozen original evidence file is unavailable or changed.", "IMPLEMENTATION_ORIGINAL_FILE_CHANGED", 409)
    return review


def normalize(context, native, value):
    value = obj(value, INPUTS, "implementation evidence input")
    source_id = value.get("sourceId")
    if source_id not in context["sources"]:
        fail("Select an original source retained in this case.", "IMPLEMENTATION_SOURCE_NOT_FOUND", 404)
    source = context["sources"][source_id]
    if domain.sha(value.get("sourceSha256"), "Selected source SHA-256", False) != source["sha256"] or \
            native["source"]["sha256"] != source["sha256"]:
        fail("The selected original source changed.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
    cutoff = instant(value.get("asOfAt"))
    if cutoff != native["asOfAt"]:
        fail("The native projection uses another observation cutoff.", "IMPLEMENTATION_PREVIEW_CONFLICT", 409)
    tranche = domain.integer(value.get("tranche"), "Evidence tranche", 1, 3, True)
    selections = value.get("selections", [])
    if not isinstance(selections, list) or len(selections) > MAX_SELECTIONS:
        fail("Select at most two hundred original observations.", "IMPLEMENTATION_SELECTION_LIMIT", 413)
    selected, seen = [], set()
    source_maps = {kind: {row["id"]: row for row in native["state"][key]} for kind, key in KINDS.items()}
    targets = {kind: {row["id"]: row for row in context["records"][kind]} for kind in LINKS.values()}
    for item in selections:
        obj(item, ("kind", "id", "use", *LINKS, "note"), "original observation link")
        kind = domain.enum(item.get("kind"), tuple(KINDS), "Original observation kind")
        ident = scalar_id(item.get("id"))
        if ident not in source_maps[kind] or (kind, ident) in seen:
            fail("Select each retained original observation once.")
        seen.add((kind, ident))
        row = {"kind": kind, "id": ident,
               "use": domain.enum(item.get("use", "EVIDENCE"), ("EVIDENCE", "CONTEXT"), "Review use"),
               "note": text(item.get("note", ""), "Linking observation", 12000)}
        for field, target in LINKS.items():
            row[field] = domain.reference_list(item.get(field, []), targets[target], "Linked " + target, 100)
        selected.append(row)
    refs = value.get("installationRefs", [])
    if not isinstance(refs, list) or len(refs) > 20:
        fail("Select at most twenty original installation editions.")
    normalized_refs, seen_refs = [], set()
    for row in refs:
        obj(row, ("id", "revision", "sha256"), "selected installation edition")
        ident = installations.identity(row.get("id"))
        number = installations.revision(row.get("revision"))
        if (ident, number) in seen_refs:
            fail("Select an installation edition once.")
        seen_refs.add((ident, number))
        normalized_refs.append({"id": ident, "revision": number,
                                "sha256": domain.sha(row.get("sha256"), "Installation edition SHA-256", False)})
    external = {row["sha256"]: row["bytes"] for row in native["externalFiles"]}
    file_refs = value.get("originalFileRefs", [])
    if not isinstance(file_refs, list) or len(file_refs) > MAX_FILE_REFS:
        fail("Select at most five thousand exact original source-file bindings.", "IMPLEMENTATION_FILE_LIMIT", 413)
    normalized_files, seen_files = [], set()
    for row in file_refs:
        obj(row, ("sha256", "sourceId"), "original source-file binding")
        sha = domain.sha(row.get("sha256"), "Original file SHA-256", False)
        original = context["sources"].get(row.get("sourceId"))
        if sha in seen_files or sha not in external:
            fail("Bind each declared external original file once.")
        if not original or original["sha256"] != sha or original["bytes"] != external[sha]:
            fail("Select the exact retained original file with its declared byte count and SHA-256.",
                 "IMPLEMENTATION_ORIGINAL_FILE_CHANGED", 409)
        seen_files.add(sha)
        normalized_files.append({"sha256": sha, "sourceId": original["id"]})
    return {"name": text(value.get("name"), "Evidence review name", 500, True),
            "sourceId": source_id, "sourceSha256": source["sha256"], "asOfAt": cutoff, "tranche": tranche,
            "installationRefs": normalized_refs, "originalFileRefs": normalized_files, "selections": selected,
            "note": text(value.get("note", ""), "Review basis", 12000)}


def select_installations(rows, refs):
    available = {(row["id"], row["revision"]): row for row in rows}
    selected = []
    for ref in refs:
        row = available.get((ref["id"], ref["revision"]))
        if row is None or row["sha256"] != ref["sha256"]:
            fail("The exact selected installation edition is unavailable.", "IMPLEMENTATION_INSTALLATION_CHANGED", 409)
        selected.append(deepcopy(row))
    return selected


def seed(context, metadata, native):
    validate_native(native, metadata)
    return {"schema": SCHEMA + ".seed", "caseId": context["program"]["id"], "version": context["program"]["version"],
            "source": deepcopy(metadata), "native": native,
            "inputs": {"name": (native["state"]["plan"].get("title") or native["origin"]["name"] or "Implementation evidence")[:500],
                       "sourceId": metadata["id"], "sourceSha256": metadata["sha256"], "asOfAt": native["asOfAt"],
                       "tranche": None, "installationRefs": [], "originalFileRefs": [], "selections": [], "note": ""}}


def bindings(context, inputs, selected_installations):
    records, source_ids = {}, {inputs["sourceId"], *(row["sourceId"] for row in inputs["originalFileRefs"])}
    for field, kind in LINKS.items():
        ids = {ident for row in inputs["selections"] for ident in row[field]}
        available = {row["id"]: row for row in context["records"][kind]}
        records[kind] = [deepcopy(available[ident]) for ident in sorted(ids)]
        for row in records[kind]:
            source_ids.update(row.get("sourceIds", []))
    for row in selected_installations:
        source_ids.update(row["preview"]["snapshot"]["sources"])
    return {"records": records, "installations": deepcopy(selected_installations),
            "sources": [deepcopy(context["sources"][ident]) for ident in sorted(source_ids)]}


def evaluate(context, native, supplied, selected_installations):
    inputs = normalize(context, native, supplied)
    validate_native(native, context["sources"][inputs["sourceId"]])
    if [{"id": row["id"], "revision": row["revision"], "sha256": row["sha256"]}
            for row in selected_installations] != inputs["installationRefs"]:
        fail("The selected installation snapshots differ from the reviewed references.")
    linked = bindings(context, inputs, selected_installations)
    maps = {kind: {row["id"]: row for row in native["state"][collection]} for kind, collection in KINDS.items()}
    receive_status = {row["id"]: row for row in native["receivingStatus"]}
    measurement_status = {row["id"]: row for row in native["measurementStatus"]}
    comparison = {row["measurementId"]: row for row in native["comparisons"]}
    issues, selected = [], []
    def finding(code, message, item=None, blocking=False):
        issues.append({"code": code, "message": message, "kind": item["kind"] if item else None,
                       "id": item["id"] if item else None, "blocking": blocking})
    if not inputs["selections"]:
        finding("NO_SELECTION", "Select the original observations that this review will retain.", blocking=True)
    external = {row["sha256"]: row for row in native["externalFiles"]}
    bound_files = {row["sha256"]: row for row in inputs["originalFileRefs"]}
    for sha, original_file in external.items():
        if sha not in bound_files:
            finding("ORIGINAL_FILE_UNAVAILABLE", "Retain and select the exact original source-bundle file " +
                    original_file["name"] + " (" + sha + ") before using the complete evidence package.", blocking=True)
    for item in inputs["selections"]:
        original = maps[item["kind"]][item["id"]]
        status = receive_status.get(item["id"], {}) if item["kind"] == "receiving" else \
                 measurement_status.get(item["id"], {}) if item["kind"] == "measurement" else {}
        row = {"link": deepcopy(item), "original": deepcopy(original), "status": deepcopy(status)}
        evidence = item["use"] == "EVIDENCE"
        if item["kind"] == "task":
            historical = original["retired"] or original["status"] == "retired" or \
                         original["editionId"] not in (None, native["state"]["activeEditionId"])
            row["status"] = {"historical": historical, "state": original["status"]}
            if historical:
                finding("HISTORICAL_TASK", "This task belongs to historical or retired work in the selected source.",
                        item, evidence)
            finding("TASK_DEFINITION", "A saved task definition or Done status is separate from technical and customer receiving.", item)
        else:
            if not status["withinCutoff"]:
                finding("AFTER_CUTOFF", "The original observed or recorded time follows the selected cutoff.", item, evidence)
            if status.get("supersededBy"):
                finding("CORRECTED_OBSERVATION", "The selected observation was corrected by " + status["supersededBy"] + " by this cutoff.", item, evidence)
            if status.get("currentSupersededBy") and status["currentSupersededBy"] != status.get("supersededBy"):
                finding("LATER_CORRECTION", "A correction after the cutoff remains in the selected source history.", item)
            if not status["activeEdition"]:
                finding("HISTORICAL_EDITION", "This observation belongs to another retained workorder edition.", item)
            if item["kind"] == "receiving":
                if not status.get("subjectMatches"):
                    finding("RECEIVING_SUBJECT_CHANGED", "The received task definition or delivered file set differs from the selected source's current definition.", item, evidence)
                if status["withinCutoff"] and not status.get("supersededBy") and not status.get("latestTaskIds"):
                    finding("LATER_RECEIVING", "A later observation is effective for these tasks and receiving kind at this cutoff.", item, evidence)
                if original["outcome"] != "accepted":
                    finding("RECORDED_RECEIVING_RESULT", "Original " + original["kind"] + " receiving records " + original["outcome"] + ".", item)
            else:
                row["comparison"] = deepcopy(comparison.get(item["id"]))
                if original["phase"] != "baseline" and not (row["comparison"] or {}).get("comparable"):
                    finding("NO_COMPARABLE_BASELINE", "The producer has no earlier comparable baseline for this selected task, output and unit.", item)
        if not any(item[field] for field in LINKS):
            finding("NO_RECORD_LINK", "This source observation has no selected Operations record link.", item)
        for purchase in linked["records"]["purchases"]:
            if purchase["id"] not in item["purchaseIds"]:
                continue
            material_ids = original.get("materialIds", [])
            materials = [m for m in native["state"]["materials"] if m["id"] in material_ids]
            if purchase.get("deliveredSha256") and purchase["deliveredSha256"] not in {m["sha256"] for m in materials}:
                finding("PURCHASE_LINK_ONLY", "The selected purchase is an explicit operator association; its output hash is not one of this observation's selected material hashes.", item)
        selected.append(row)
    if native["origin"].get("exportedAt") and at(native["origin"]["exportedAt"]) > at(inputs["asOfAt"]):
        finding("LATER_SOURCE_EXPORT", "This source was exported after the observation cutoff. Its complete selected task definitions remain the definition basis; no earlier task state is inferred.")
    selected_evidence = [row for row in selected if row["link"]["use"] == "EVIDENCE"]
    summary = {"selected": len(selected), "evidence": len(selected_evidence),
               "context": len(selected) - len(selected_evidence),
               "tasks": sum(row["link"]["kind"] == "task" for row in selected),
               "measurements": sum(row["link"]["kind"] == "measurement" for row in selected),
               "technicalAcceptedTasks": len({ident for row in selected_evidence
                   if row["link"]["kind"] == "receiving" and row["original"]["kind"] == "technical"
                   for ident in row["status"].get("currentAcceptedTaskIds", [])}),
               "customerAcceptedTasks": len({ident for row in selected_evidence
                   if row["link"]["kind"] == "receiving" and row["original"]["kind"] == "customer"
                   for ident in row["status"].get("currentAcceptedTaskIds", [])}),
               "comparisons": sum(bool(row.get("comparison", {}).get("comparable")) for row in selected if row.get("comparison")),
               "linkedInstallations": len(selected_installations), "externalOriginalFiles": len(external),
               "boundOriginalFiles": len(bound_files), "missingOriginalFiles": len(external) - len(bound_files)}
    result = {"schema": SCHEMA, "source": {"programId": context["program"]["id"],
              "version": context["program"]["version"], "sourceId": inputs["sourceId"],
              "sha256": inputs["sourceSha256"], "bytes": native["source"]["bytes"],
              "nativeSha256": digest(native)}, "inputs": inputs, "native": deepcopy(native),
              "bindings": linked, "selected": selected, "summary": summary, "issues": issues,
              "ready": not any(row["blocking"] for row in issues)}
    result["previewSha256"] = digest(result)
    return result


def prepare(ops, context, data, actor, version):
    obj(data, ("inputs", "expectedPreviewSha256"), "implementation preparation")
    inputs = data.get("inputs")
    if not isinstance(inputs, dict):
        fail("Use the selected original evidence inputs.")
    metadata, raw = ops.source(context["program"]["id"], inputs.get("sourceId"))
    native = inspect(raw, inputs.get("asOfAt"))
    selected = select_installations(installations.load(ops, context["program"]["id"]), inputs.get("installationRefs", []))
    candidate = evaluate(context, native, inputs, selected)
    if candidate["previewSha256"] != domain.sha(data.get("expectedPreviewSha256"), "Reviewed evidence preview", False):
        fail("The original source, selection or linked case changed. Preview the retained draft again.",
             "IMPLEMENTATION_PREVIEW_CONFLICT", 409)
    if context["program"]["mode"] != "WALKTHROUGH" and at(candidate["inputs"]["asOfAt"]) > at(utc_now()):
        fail("A future cutoff remains a plan. Freeze an actual observation cutoff.",
             "IMPLEMENTATION_FUTURE_CUTOFF", 409)
    if not candidate["inputs"]["selections"]:
        fail("Select the original observations before freezing this review.")
    count = ops.db.execute("SELECT COUNT(*) FROM ops_reviews WHERE program_id=?",
                           (context["program"]["id"],)).fetchone()[0]
    if count >= MAX_REVIEWS:
        fail("The original case has reached its retained-review bound.", "IMPLEMENTATION_REVIEW_LIMIT", 413)
    snapshot = ops._business(context)
    row = {"id": "review-" + uuid.uuid4().hex, "version": version, "createdAt": now(), "actor": actor,
           "note": candidate["inputs"]["note"] or candidate["inputs"]["name"],
           "businessSha256": digest(snapshot), "snapshot": snapshot, "report": domain.report(**context),
           "purpose": PURPOSE, "implementation": candidate}
    if len(canonical(row).encode("utf-8")) > MAX_REVIEW:
        fail("The complete evidence review exceeds 8 MiB. Preserve its original source and select a smaller review scope.",
             "IMPLEMENTATION_REVIEW_SIZE", 413)
    ops.db.execute("INSERT INTO ops_reviews VALUES(?,?,?)", (context["program"]["id"], row["id"], canonical(row)))
    return {"before": None, "after": {key: row[key] for key in ("id", "version", "purpose", "businessSha256")} |
            {"evidenceSha256": candidate["previewSha256"]}, "kind": "review", "recordId": row["id"],
            "unchanged": False, "previewSha256": candidate["previewSha256"], "evidenceReady": candidate["ready"]}


def validate_review(review):
    if review.get("purpose") != PURPOSE:
        fail("Select an original implementation evidence review.", "IMPLEMENTATION_REVIEW_NOT_FOUND", 404)
    candidate, snapshot = review.get("implementation"), review.get("snapshot")
    if not isinstance(candidate, dict) or not isinstance(snapshot, dict) or digest(snapshot) != review.get("businessSha256"):
        fail("The original evidence review snapshot changed.", "IMPLEMENTATION_REVIEW_CHANGED", 409)
    if candidate.get("schema") != SCHEMA or candidate.get("source", {}).get("version") != review["version"] - 1:
        fail("The evidence review no longer joins its source case version.")
    if digest(candidate.get("native")) != candidate["source"].get("nativeSha256"):
        fail("The original producer projection changed.", "IMPLEMENTATION_REVIEW_CHANGED", 409)
    context = {**snapshot, "program": {**snapshot["program"], "version": review["version"] - 1},
               "sources": {row["id"]: row for row in snapshot["sources"]}}
    actual = evaluate(context, candidate["native"], candidate["inputs"], candidate["bindings"]["installations"])
    if not _typed_equal(actual, candidate):
        fail("The evidence review differs from its original source and explicit links.", "IMPLEMENTATION_REVIEW_CHANGED", 409)
    return review


def current_binding(context, candidate):
    differences = []
    for kind, rows in candidate["bindings"]["records"].items():
        current = {row["id"]: row for row in context["records"][kind]}
        for row in rows:
            if not _typed_equal(current.get(row["id"]), row):
                differences.append({"kind": kind, "id": row["id"], "reason": "The linked original record changed after this review."})
    refs = {row["id"]: row for row in context.get("installationRefs", [])}
    for row in candidate["bindings"]["installations"]:
        expected = {"id": row["id"], "revision": row["revision"], "sha256": row["sha256"]}
        if refs.get(row["id"]) != expected:
            differences.append({"kind": "installation", "id": row["id"], "reason": "The selected installation is a retained earlier edition."})
    for source in candidate["bindings"]["sources"]:
        current = context["sources"].get(source["id"])
        if not current or (current["sha256"], current["bytes"]) != (source["sha256"], source["bytes"]):
            differences.append({"kind": "source", "id": source["id"], "reason": "The exact original source is unavailable."})
    return {"current": not differences, "differences": differences,
            "definitionBasis": candidate["native"]["definitionBasis"]}


def summary(review, context=None):
    candidate = review["implementation"]
    result = {"implementationName": candidate["inputs"]["name"], "implementationTranche": candidate["inputs"]["tranche"],
              "implementationSourceId": candidate["inputs"]["sourceId"], "implementationSourceSha256": candidate["inputs"]["sourceSha256"],
              "implementationAsOfAt": candidate["inputs"]["asOfAt"], "evidenceReady": candidate["ready"],
              "evidenceSummary": candidate["summary"], "evidenceSha256": candidate["previewSha256"]}
    if context is not None:
        result["implementationCurrent"] = current_binding(context, candidate)
    return result


def validate_import(context, reviews, events, saved_installations, files):
    ids = set()
    available_installations = {(row["id"], row["revision"], row["sha256"]): row for row in saved_installations}
    record_states = installations._record_matches(events, context["records"])
    for review in reviews:
        if review.get("purpose") != PURPOSE:
            continue
        validate_review(review)
        ids.add(review["id"])
        candidate = review["implementation"]
        source_id = candidate["inputs"]["sourceId"]
        metadata = context["sources"].get(source_id)
        if not metadata:
            fail("The complete case is missing its original implementation source.")
        verify_projection(candidate["native"], metadata, files["sources/" + source_id])
        for row in candidate["bindings"]["installations"]:
            if available_installations.get((row["id"], row["revision"], row["sha256"])) != row or row["version"] >= review["version"]:
                fail("The evidence review lost its exact earlier installation edition.")
        for rows in candidate["bindings"]["records"].values():
            for row in rows:
                if row["version"] >= review["version"] or digest(row) not in record_states.get((row["id"], row["version"]), set()):
                    fail("A linked evidence record is missing from the original case history.")
        for source in candidate["bindings"]["sources"]:
            current = context["sources"].get(source["id"])
            if not current or current["sha256"] != source["sha256"] or current["bytes"] != source["bytes"]:
                fail("An evidence source is missing from the complete case.")
        event = events[review["version"] - 1]
        if event.get("action") != "implementation.prepare" or event.get("recordId") != review["id"] or \
                event.get("after", {}).get("evidenceSha256") != candidate["previewSha256"] or \
                event.get("after", {}).get("businessSha256") != review["businessSha256"]:
            fail("The evidence review does not retain its original preparation event.")
    if {row.get("recordId") for row in events if row.get("action") == "implementation.prepare"} != ids:
        fail("The complete case is missing an original implementation evidence review.")


def completion_evidence(context, reviews, tranche, as_of):
    items, issues = [], []
    for review in reviews:
        validate_review(review)
        candidate = review["implementation"]
        binding = current_binding(context, candidate)
        items.append({"reviewId": review["id"], "previewSha256": candidate["previewSha256"],
                      "sourceCurrent": binding["current"], "ready": candidate["ready"],
                      "tranche": candidate["inputs"]["tranche"], "review": deepcopy(review)})
        reasons = []
        if not binding["current"]:
            reasons.append("The linked original delivery records or installation edition changed after this evidence review.")
        if candidate["inputs"]["tranche"] != tranche:
            reasons.append("The selected evidence review has not been assigned to this tranche.")
        if candidate["inputs"]["asOfAt"][:10] > as_of or review["createdAt"][:10] > as_of:
            reasons.append("The evidence review or observation cutoff follows this completion date.")
        if not candidate["ready"]:
            reasons.append("The selected evidence review retains unresolved current-versus-historical source findings.")
        for reason in reasons:
            issues.append({"code": "IMPLEMENTATION_EVIDENCE", "costId": None, "reviewId": review["id"], "message": reason})
    return items, issues


def _table(title, columns, rows):
    escape = lambda value: html.escape(str(value if value is not None else ""), quote=True)
    header = "".join("<th>" + escape(label) + "</th>" for key, label in columns)
    body = "".join("<tr>" + "".join("<td>" + escape(canonical(row.get(key)) if isinstance(row.get(key), (dict, list)) else row.get(key)) + "</td>"
                                  for key, label in columns) + "</tr>" for row in rows)
    return "<h2>" + escape(title) + "</h2><table><thead><tr>" + header + "</tr></thead><tbody>" + body + "</tbody></table>"


def html_document(review):
    candidate = review["implementation"]
    escape = lambda value: html.escape(str(value if value is not None else ""), quote=True)
    sections = [
        _table("Selected original observations", (("kind", "Kind"), ("id", "Original ID"), ("use", "Review use"),
                ("deploymentIds", "Deployments"), ("workIds", "Work"), ("purchaseIds", "Purchases"), ("outcomeIds", "Outcomes"), ("note", "Operator link")),
               candidate["inputs"]["selections"]),
        _table("Preserved source findings", (("code", "Finding"), ("kind", "Kind"), ("id", "Original ID"),
                ("message", "Observation"), ("blocking", "Needs review")), candidate["issues"]),
        _table("Original task measurements", (("id", "ID"), ("phase", "Phase"), ("observedAt", "Observed"),
                ("taskDefinition", "Task"), ("inputDescription", "Input"), ("outputDescription", "Output"),
                ("unit", "Unit"), ("units", "Quantity"), ("activeMinutes", "Active minutes"),
                ("elapsedMinutes", "Elapsed minutes"), ("manualCorrections", "Manual corrections"),
                ("actor", "Recorded by"), ("supersedesId", "Corrects")), candidate["native"]["state"]["measurements"]),
        _table("Original comparisons at the selected cutoff", (("measurementId", "Observation"), ("baselineId", "Baseline"),
                ("comparable", "Comparable"), ("sameVolume", "Same volume"), ("values", "Recorded total comparison"),
                ("perUnit", "Per-unit comparison"), ("reason", "Unresolved basis")), candidate["native"]["comparisons"]),
        _table("Technical and customer receiving", (("id", "ID"), ("kind", "Receiving kind"), ("outcome", "Recorded outcome"),
                ("observedAt", "Observed"), ("taskIds", "Original tasks"), ("materialIds", "Original files"),
                ("actor", "Receiver"), ("reference", "Reference"), ("notes", "Observation"),
                ("supersedesId", "Corrects")), candidate["native"]["state"]["receiving"]),
        _table("Observation effectiveness", (("id", "ID"), ("withinCutoff", "By cutoff"), ("activeEdition", "Selected edition"),
                ("subjectMatches", "Matches selected source definition"), ("supersededBy", "Corrected by cutoff"),
                ("currentSupersededBy", "Current correction"), ("effectiveTaskIds", "Effective selected tasks")),
               candidate["native"]["receivingStatus"])]
    page = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>' + escape(candidate["inputs"]["name"]) + '</title><style>body{font:16px system-ui;max-width:1250px;margin:2rem auto;padding:0 1rem;color:#222}table{width:100%;border-collapse:collapse;font-size:.85rem}td,th{padding:.55rem;border:1px solid #bbb;text-align:left;vertical-align:top;overflow-wrap:anywhere}p,td{white-space:pre-wrap}small{color:#555}@media print{thead{display:table-header-group}tr{break-inside:avoid}body{max-width:none;font-size:11pt}}</style></head><body><h1>' + escape(candidate["inputs"]["name"]) + '</h1><p>' + escape(review["snapshot"]["program"]["name"]) + ' · ' + escape(review["snapshot"]["program"]["mode"]) + '</p><p>Observation cutoff: ' + escape(candidate["inputs"]["asOfAt"]) + '</p><p>' + escape(candidate["native"]["definitionBasis"]) + '</p><p>This is a review of original implementation evidence and explicit record associations. Technical receiving, customer receiving, work approval, purchase settlement and issuer acceptance retain their own original records. Missing measurements remain blank; recorded zero remains zero. No payment or external acceptance is created by this review.</p><p>Original source: ' + escape(candidate["inputs"]["sourceId"]) + ' · SHA-256 ' + escape(candidate["inputs"]["sourceSha256"]) + '</p><p>' + escape(candidate["inputs"]["note"]) + '</p>' + "".join(sections) + '<p>The complete frozen review, all linked original record snapshots, native reader identities, full source JSON and every embedded original file are included in this package. Producer receiving/report.html is the complete current-source report; this document records the chosen observation cutoff and evidence scope.</p><small>' + escape(review["id"]) + ' · ' + escape(review["createdAt"]) + ' · ' + escape(review["actor"]) + '</small></body></html>'
    return page.encode("utf-8")


def file_map(review, read_source):
    validate_review(review)
    candidate = review["implementation"]
    native = candidate["native"]
    source_id = candidate["inputs"]["sourceId"]
    metadata, source_raw = read_source(source_id)
    verify_projection(native, metadata, source_raw)
    files = {"implementation-review.json": (canonical(review) + "\n").encode("utf-8"),
             "implementation.html": html_document(review),
             "producer-receiving/report.html": native["originalReportHtml"].encode("utf-8"),
             "original-files.json": (canonical({"sourceId": source_id, "files": native["files"],
                "editions": native["state"]["editions"], "materials": native["state"]["materials"],
                "originalFiles": native["originalFiles"], "externalFileBindings": candidate["inputs"]["originalFileRefs"]}) + "\n").encode("utf-8")}
    for sha, raw in original_files(source_raw).items():
        files["original-files/" + sha] = raw
    bound_files = {row["sha256"]: row["sourceId"] for row in candidate["inputs"]["originalFileRefs"]}
    for original in native["externalFiles"]:
        sha = original["sha256"]
        if sha not in bound_files:
            fail("The frozen evidence retains an unavailable original source-bundle file: " + original["name"],
                 "IMPLEMENTATION_ORIGINAL_FILE_UNAVAILABLE", 409)
        actual, raw = read_source(bound_files[sha])
        if actual["sha256"] != sha or len(raw) != original["bytes"] or hashlib.sha256(raw).hexdigest() != sha:
            fail("The retained original source-bundle member changed.", "IMPLEMENTATION_ORIGINAL_FILE_CHANGED", 409)
        files["original-files/" + sha] = raw
    files["source-bundles.json"] = (canonical(native["sourceBundles"]) + "\n").encode("utf-8")
    for source in candidate["bindings"]["sources"]:
        actual, raw = read_source(source["id"])
        if actual["sha256"] != source["sha256"] or len(raw) != source["bytes"] or hashlib.sha256(raw).hexdigest() != source["sha256"]:
            fail("An original evidence source changed.", "IMPLEMENTATION_SOURCE_CHANGED", 409)
        files["sources/" + source["id"]] = raw
    for name, rows, columns in (
        ("links", candidate["inputs"]["selections"], ["kind", "id", "use", *LINKS, "note"]),
        ("tasks", native["state"]["tasks"], ["id", "editionId", "title", "acceptance", "owner", "dueOn", "status", "retired", "dependencies", "notes"]),
        ("receiving", native["state"]["receiving"], ["id", "editionId", "kind", "outcome", "observedAt", "recordedAt", "taskIds", "materialIds", "actor", "reference", "notes", "subjectSha256", "supersedesId"]),
        ("receiving-status", native["receivingStatus"], ["id", "withinCutoff", "activeEdition", "subjectMatches", "supersededBy", "currentSupersededBy", "latestTaskIds", "effectiveTaskIds"]),
        ("measurements", native["state"]["measurements"], ["id", "editionId", "phase", "comparisonKey", "taskDefinition", "inputDescription", "outputDescription", "unit", "units", "activeMinutes", "elapsedMinutes", "manualCorrections", "observedAt", "recordedAt", "actor", "materialIds", "reference", "notes", "supersedesId"]),
        ("measurement-status", native["measurementStatus"], ["id", "withinCutoff", "activeEdition", "supersededBy", "currentSupersededBy"]),
        ("comparisons", native["comparisons"], ["measurementId", "baselineId", "comparable", "sameVolume", "values", "perUnit", "reason"]),
        ("findings", candidate["issues"], ["code", "kind", "id", "message", "blocking"])):
        files[name + ".csv"] = csv_bytes(columns, [{key: canonical(value) if isinstance(value, (dict, list)) else value
                                                  for key, value in row.items()} for row in rows])
    return files


def review_files(review, read_source):
    files = file_map(review, read_source)
    manifest = {"schema": SCHEMA + ".bundle", "reviewId": review["id"],
                "previewSha256": review["implementation"]["previewSha256"],
                "files": [{"path": name, "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}
                          for name, raw in sorted(files.items())]}
    files["MANIFEST.json"] = (canonical(manifest) + "\n").encode("utf-8")
    if sum(map(len, files.values())) > MAX_BUNDLE:
        fail("The complete selected evidence package exceeds the original 32 MiB export bound.",
             "IMPLEMENTATION_EXPORT_SIZE", 413)
    output = io.BytesIO()
    with zipfile.ZipFile(output, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
        for name, raw in sorted(files.items()):
            info = zipfile.ZipInfo(name, (2026, 1, 1, 0, 0, 0))
            info.external_attr = 0o600 << 16
            info.compress_type = zipfile.ZIP_DEFLATED
            archive.writestr(info, raw)
    raw = output.getvalue()
    if len(raw) > MAX_BUNDLE:
        fail("The compressed evidence package exceeds the supported bound.", "IMPLEMENTATION_EXPORT_SIZE", 413)
    return raw

"""Saved customer installations in the original SF47 Operations case.

Every edition retains its selected native records and source identities. The
original case owns work, payment, support, acceptance observations and receiving.
"""
from __future__ import annotations

from collections import Counter, defaultdict
from copy import deepcopy
from html import escape
import hashlib
import json
import re
import uuid

from model import Problem, canonical, digest, now, text
import operations_domain as domain
import operations_workshare_installations as workshares
import operations_commercial_installations as commercial
import operations_installation_workflows as workflows
import operations_dispatch as dispatch
import operations_use_calendar as use_calendar

SCHEMA = "stellar-forge.sf47-installation.v1"
SELECTION_SCHEMA = SCHEMA + ".selection"
MAX_INSTALLATIONS = 100
MAX_EDITIONS = 500
MAX_DOCUMENT_BYTES = 128 * 1024
STAGES = ("PLANNED", "COMMISSIONING", "OPERATING", "HANDED_OVER", "RETIRED")
CHECK_STATES = ("OPEN", "IN_PROGRESS", "ACCEPTED", "CHANGES_REQUIRED", "NOT_APPLICABLE")
COLLECTIONS = ("deployments", "contributors", "work", "purchases", "outcomes")


def fail(message, code="INVALID_INSTALLATION", status=422):
    raise Problem(message, status, code)


def object_value(value, allowed, label):
    if not isinstance(value, dict) or set(value) - set(allowed):
        fail("Use the declared " + label + " fields.")
    return value


def identity(value):
    if not isinstance(value, str) or not re.fullmatch(r"installation-[a-f0-9]{32}", value):
        fail("Select the original installation identity.")
    return value


def revision(value, allow_zero=False):
    return domain.integer(value, "Installation edition", 0 if allow_zero else 1, MAX_EDITIONS)


def short_text(value, label, limit=4000, required=False):
    return text(value if value is not None else "", label, limit, required)


def atomic(value, label):
    if value is None or value == "":
        return None
    if not isinstance(value, str) or not re.fullmatch(r"(?:0|[1-9][0-9]{0,29})", value):
        fail(label + ": retain a nonnegative whole atomic amount as decimal text.")
    return value


def install(db):
    db.execute("""
        CREATE TABLE IF NOT EXISTS ops_installations(
            program_id TEXT NOT NULL REFERENCES ops_programs(id),
            installation_id TEXT NOT NULL,revision INTEGER NOT NULL,body_json TEXT NOT NULL,
            PRIMARY KEY(program_id,installation_id,revision))
    """)


def load(operations, program_id):
    return [json.loads(row[0]) for row in operations.db.execute(
        "SELECT body_json FROM ops_installations WHERE program_id=? ORDER BY installation_id,revision",
        (program_id,))]


def load_heads(operations, program_id):
    """Read only current editions for lists and coordination; exports use load."""
    return [json.loads(row[0]) for row in operations.db.execute(
        "SELECT saved.body_json FROM ops_installations AS saved "
        "JOIN (SELECT installation_id,MAX(revision) AS revision FROM ops_installations "
        "WHERE program_id=? GROUP BY installation_id) AS heads "
        "ON saved.installation_id=heads.installation_id AND saved.revision=heads.revision "
        "WHERE saved.program_id=? ORDER BY saved.installation_id",
        (program_id, program_id))]


def summary(row):
    value = row["preview"]
    report = value["report"]
    return {"id": row["id"], "revision": row["revision"], "version": row["version"],
            "sha256": row["sha256"], "name": value["document"]["name"],
            "stage": value["document"]["stage"], "createdAt": row["createdAt"], "actor": row["actor"],
            "merchantDeploymentId": value["document"]["merchantDeploymentId"],
            "buyerDeploymentIds": value["document"]["buyerDeploymentIds"],
            "sourceVersion": value["source"]["version"],
            "configurationComplete": report["configurationComplete"],
            "acceptedChecks": report["acceptedChecks"], "totalChecks": report["totalChecks"],
            "openFindings": len(report["findings"]),
            **({"useCalendar": {key: value["document"]["useCalendar"][key]
                                for key in ("name", "startDate", "endDate", "tranche")}}
               if value["document"].get("useCalendar") else {})}


def latest_refs(rows):
    latest = {}
    for row in rows:
        if row["id"] not in latest or row["revision"] > latest[row["id"]]["revision"]:
            latest[row["id"]] = row
    return [{"id": row["id"], "revision": row["revision"], "sha256": row["sha256"]}
            for row in sorted(latest.values(), key=lambda value: value["id"])]


def latest_summaries(rows):
    wanted = {(ref["id"], ref["revision"]) for ref in latest_refs(rows)}
    return sorted([summary(row) for row in rows if (row["id"], row["revision"]) in wanted],
                  key=lambda row: (row["createdAt"], row["id"]), reverse=True)


def get(operations, program_id, installation_id, selected_revision=None):
    ident = identity(installation_id)
    parameters = (program_id, ident)
    suffix = " ORDER BY revision DESC LIMIT 1"
    if selected_revision is not None:
        parameters += (revision(selected_revision),)
        suffix = " AND revision=?"
    stored = operations.db.execute(
        "SELECT body_json FROM ops_installations WHERE program_id=? AND installation_id=?" + suffix,
        parameters).fetchone()
    if not stored:
        fail("The original installation edition is unavailable.", "INSTALLATION_NOT_FOUND", 404)
    row = json.loads(stored[0])
    if digest({key: value for key, value in row.items() if key != "sha256"}) != row.get("sha256"):
        fail("The saved installation differs from its retained identity.", "INSTALLATION_CHANGED", 409)
    return row


def normalized(context, raw):
    raw = object_value(deepcopy(raw), ("name", "stage", "merchantDeploymentId", "buyerDeploymentIds",
        "workorder", "task", "source", "payment", "receiving", "assignments", "checks", "workshare", "workflowPeriods", "coordination", "commercial", "useCalendar"), "installation")
    records, sources, plan = context["records"], context["sources"], context["plan"]
    maps = {kind: {row["id"]: row for row in records[kind]} for kind in COLLECTIONS}
    retained = lambda value, label: domain.reference_list(value if value is not None else [], sources, label)
    merchant = raw.get("merchantDeploymentId") or None
    if merchant is not None:
        if merchant not in maps["deployments"] or maps["deployments"][merchant]["role"] not in ("MERCHANT", "BOTH"):
            fail("Select a retained merchant or combined deployment.", "INSTALLATION_DEPLOYMENT")
    buyers = domain.reference_list(raw.get("buyerDeploymentIds", []), maps["deployments"], "Buyer deployments", 20)
    if any(maps["deployments"][key]["role"] not in ("BUYER", "BOTH") for key in buyers):
        fail("Select retained buyer or combined deployments.", "INSTALLATION_DEPLOYMENT")
    deployments = set(buyers) | ({merchant} if merchant else set())

    source_workorder = object_value(raw.get("workorder", {}), ("sourceId", "reference", "payer", "scope", "terms"),
                                   "original workorder")
    workorder_id = source_workorder.get("sourceId") or None
    if workorder_id is not None:
        retained([workorder_id], "Original workorder")
    workorder = {"sourceId": workorder_id,
                 **{key: short_text(source_workorder.get(key), label, 8000 if key in ("scope", "terms") else 1000)
                    for key, label in (("reference", "Original workorder reference"), ("payer", "Commissioning payer"),
                                       ("scope", "Original scope and implementation assignment"),
                                       ("terms", "Original commercial terms"))}}
    task_raw = object_value(raw.get("task", {}), ("name", "purpose", "request", "completeOutput", "repeatTrigger", "pricedUnit"),
                            "customer task")
    task = {key: short_text(task_raw.get(key), label, 8000 if key == "request" else 4000)
            for key, label in (("name", "Useful task"), ("purpose", "Customer purpose"),
                ("request", "Complete original request"), ("completeOutput", "Whole task completion"),
                ("repeatTrigger", "Reason for another useful result"), ("pricedUnit", "Merchant priced unit"))}
    source_raw = object_value(raw.get("source", {}), ("sourceIds", "reference", "mode", "population", "meaning", "authority", "changePolicy"),
                              "source specification")
    source = {"sourceIds": retained(source_raw.get("sourceIds"), "Selected source files"),
              "mode": domain.enum(source_raw.get("mode", "UNSELECTED"), ("UNSELECTED", "SNAPSHOT", "LIVE", "MIXED"), "Source behavior"),
              **{key: short_text(source_raw.get(key), label) for key, label in (
                  ("reference", "Source edition or live-operation identity"), ("population", "Complete source population"),
                  ("meaning", "Keys, types, units and time meaning"), ("authority", "Source rights and authority"),
                  ("changePolicy", "Source change and withdrawal"))}}
    payment_raw = object_value(raw.get("payment", {}), ("network", "asset", "recipient", "priceAtomic", "taskBudgetAtomic",
        "taskUnits", "authority", "termsSourceIds", "facilitators"), "payment selection")
    providers = payment_raw.get("facilitators", [])
    if not isinstance(providers, list) or len(providers) > 10:
        fail("Use up to ten explicit facilitator selections.")
    facilitators, seen = [], set()
    for provider in providers:
        provider = object_value(provider, ("operatorId", "endpoint", "sourceIds", "note"), "facilitator selection")
        operator = short_text(provider.get("operatorId"), "Facilitator operator identity", 500, True)
        endpoint = domain.url(provider.get("endpoint"), "Facilitator endpoint", False)
        key = (operator, endpoint)
        if key in seen:
            fail("Keep each selected facilitator operator and endpoint once.")
        seen.add(key)
        facilitators.append({"operatorId": operator, "endpoint": endpoint,
                             "sourceIds": retained(provider.get("sourceIds"), "Facilitator sources"),
                             "note": short_text(provider.get("note"), "Facilitator selection basis")})
    payment = {**{key: short_text(payment_raw.get(key), label, limit) for key, label, limit in (
                    ("network", "Payment network", 200), ("asset", "Payment asset", 500),
                    ("recipient", "Payment recipient", 500), ("authority", "Buyer approval and aggregate spending authority", 4000))},
               "priceAtomic": atomic(payment_raw.get("priceAtomic"), "Original unit price"),
               "taskBudgetAtomic": atomic(payment_raw.get("taskBudgetAtomic"), "Whole task budget"),
               "taskUnits": domain.integer(payment_raw.get("taskUnits"), "Expected priced units", 0, 10**12, True),
               "termsSourceIds": retained(payment_raw.get("termsSourceIds"), "Original payment terms"),
               "facilitators": facilitators}
    receiving_raw = object_value(raw.get("receiving", {}), ("application", "host", "operator", "acceptanceRule",
        "changeAndWithdraw", "recovery", "maintenance", "sourceIds"), "customer receiving")
    receiving = {"sourceIds": retained(receiving_raw.get("sourceIds"), "Receiving sources"),
                 **{key: short_text(receiving_raw.get(key), label) for key, label in (
                    ("application", "Receiving application and version"), ("host", "Authorized receiving host"),
                    ("operator", "Receiving operator"), ("acceptanceRule", "Useful output acceptance"),
                    ("changeAndWithdraw", "Second-operator change or withdrawal"), ("recovery", "Original recovery procedure"),
                    ("maintenance", "Maintainer, support destination and ownership"))}}
    assignment_raw = object_value(raw.get("assignments", {}), ("costIds", "commercialRef", "note"), "delivery assignments")
    cost_ids = assignment_raw.get("costIds", [])
    if (not isinstance(cost_ids, list) or len(cost_ids) > 200 or any(not isinstance(item, str) for item in cost_ids)
            or len(cost_ids) != len(set(cost_ids))):
        fail("Select distinct original funded work packages.")
    for value in cost_ids:
        if not isinstance(value, str) or domain.cost_id(value, plan) is None:
            fail("Select an original funded work package.")
    assignments = {"costIds": cost_ids,
                   "commercialRef": short_text(assignment_raw.get("commercialRef"), "Separate commercial workorder", 4000),
                   "note": short_text(assignment_raw.get("note"), "Original funding and effort assignment", 8000)}
    checks_raw = raw.get("checks", [])
    if not isinstance(checks_raw, list) or len(checks_raw) > 100:
        fail("Use up to one hundred distinct acceptance steps.")
    checks, check_ids = [], set()
    for original in checks_raw:
        value = object_value(original, ("id", "title", "criterion", "tranche", "required", "state", "operator", "observedAt",
            "note", "sourceIds", "workIds", "purchaseIds", "outcomeIds"), "installation acceptance")
        ident = value.get("id")
        if not isinstance(ident, str) or not re.fullmatch(r"[a-z][a-z0-9-]{0,79}", ident) or ident in check_ids:
            fail("Give each acceptance step a distinct retained lowercase identity.")
        check_ids.add(ident)
        required = value.get("required", True)
        if not isinstance(required, bool):
            fail("The acceptance requirement must be true or false.")
        state = domain.enum(value.get("state", "OPEN"), CHECK_STATES, "Acceptance state")
        operator = short_text(value.get("operator"), "Accountable acceptance operator", 500)
        observed = domain.timestamp(value.get("observedAt"), "Actual acceptance observation", True)
        note = short_text(value.get("note"), "Acceptance result and correction", 8000)
        if state == "ACCEPTED" and (not operator or not observed or not note):
            fail("Accepted work needs its actual operator, observation time and result.")
        if state == "NOT_APPLICABLE" and not note:
            fail("Retain the reason this acceptance step is not applicable.")
        links = {}
        for field, kind in (("workIds", "work"), ("purchaseIds", "purchases"), ("outcomeIds", "outcomes")):
            links[field] = domain.reference_list(value.get(field, []), maps[kind], "Original " + kind, 200)
        if any(maps["purchases"][key]["deploymentId"] not in deployments for key in links["purchaseIds"]):
            fail("An installation purchase must belong to one of its selected deployments.", "INSTALLATION_PURCHASE")
        checks.append({"id": ident, "title": short_text(value.get("title"), "Acceptance title", 500, True),
                       "criterion": short_text(value.get("criterion"), "Original acceptance criterion", 8000, state == "ACCEPTED"),
                       "tranche": domain.integer(value.get("tranche"), "Acceptance tranche", 1, 3, True),
                       "required": required, "state": state, "operator": operator, "observedAt": observed,
                       "note": note, "sourceIds": retained(value.get("sourceIds"), "Acceptance sources"), **links})
    result = {"name": short_text(raw.get("name"), "Installation name", 300, True),
              "stage": domain.enum(raw.get("stage", "PLANNED"), STAGES, "Installation stage"),
              "merchantDeploymentId": merchant, "buyerDeploymentIds": buyers, "workorder": workorder,
              "task": task, "source": source, "payment": payment, "receiving": receiving,
              "assignments": assignments, "checks": checks}
    if "commercial" in raw:
        result["commercial"] = commercial.normalize_binding(context, raw["commercial"])
    if "workshare" in raw:
        result["workshare"] = workshares.normalize_binding(context, raw["workshare"])
    if "workflowPeriods" in raw:
        result["workflowPeriods"] = workflows.normalize_binding(context, raw["workflowPeriods"])
    if "coordination" in raw:
        result["coordination"] = dispatch.normalize(raw["coordination"], check_ids)
    if "useCalendar" in raw:
        result["useCalendar"] = use_calendar.normalize(context, raw["useCalendar"], result) if raw["useCalendar"] is not None else None
    if len(canonical(result).encode("utf-8")) > MAX_DOCUMENT_BYTES:
        fail("The complete installation input exceeds 128 KiB.", status=413)
    return result


def capture(context, document):
    """Select complete original rows, then close their source/contributor links."""
    selected = {kind: set() for kind in domain.KINDS}
    selected["deployments"].update(document["buyerDeploymentIds"])
    if document["merchantDeploymentId"]:
        selected["deployments"].add(document["merchantDeploymentId"])
    source_ids = set(document["source"]["sourceIds"] + document["payment"]["termsSourceIds"]
                     + document["receiving"]["sourceIds"])
    calendar_refs = use_calendar.references(document)
    source_ids.update(calendar_refs["sourceIds"])
    selected["purchases"].update(calendar_refs["purchaseIds"])
    if document["workorder"]["sourceId"]:
        source_ids.add(document["workorder"]["sourceId"])
    if document.get("commercial"):
        source_ids.add(document["commercial"]["sourceId"])
        source_ids.update(row["sourceId"] for row in document["commercial"]["sourceFiles"])
    if document.get("workshare"):
        source_ids.add(document["workshare"]["sourceId"])
        if document["workshare"]["packetSourceId"]:
            source_ids.add(document["workshare"]["packetSourceId"])
    if document.get("workflowPeriods"):
        source_ids.add(document["workflowPeriods"]["sourceId"])
    for row in document["payment"]["facilitators"]:
        source_ids.update(row["sourceIds"])
    for row in document["checks"]:
        source_ids.update(row["sourceIds"])
        for field, kind in (("workIds", "work"), ("purchaseIds", "purchases"), ("outcomeIds", "outcomes")):
            selected[kind].update(row[field])
    originals = {kind: {row["id"]: row for row in context["records"][kind]} for kind in domain.KINDS}
    for kind in ("work", "outcomes"):
        for key in selected[kind]:
            contributor = originals[kind][key].get("contributorId")
            if contributor:
                selected["contributors"].add(contributor)
    records = {kind: [deepcopy(originals[kind][key]) for key in sorted(selected[kind])]
               for kind in domain.KINDS}
    for values in records.values():
        for row in values:
            source_ids.update(row.get("sourceIds", []))
    return {"program": deepcopy(context["program"]), "plan": deepcopy(context["plan"]), "records": records,
            "sources": {key: deepcopy(context["sources"][key]) for key in sorted(source_ids)}}


def report(snapshot, document):
    findings = []
    def missing(path, value, description):
        if value in (None, "", [], "UNSELECTED"):
            findings.append({"field": path, "kind": "DECISION", "message": description})
    for path, value, description in (
        ("merchantDeploymentId", document["merchantDeploymentId"], "Select the accountable merchant deployment."),
        ("buyerDeploymentIds", document["buyerDeploymentIds"], "Select the original receiving buyer deployment."),
        ("workorder.sourceId", document["workorder"]["sourceId"], "Select the complete original commissioning/workorder source."),
        ("workorder.payer", document["workorder"]["payer"], "Record the commissioning payer."),
        ("task.request", document["task"]["request"], "Name the complete original request."),
        ("task.completeOutput", document["task"]["completeOutput"], "State what finishes the customer's whole task."),
        ("task.repeatTrigger", document["task"]["repeatTrigger"], "Record the event that makes a later result useful."),
        ("task.pricedUnit", document["task"]["pricedUnit"], "Name the merchant's priced unit."),
        ("source.mode", document["source"]["mode"], "Choose snapshot, live or mixed source behavior."),
        ("source.population", document["source"]["population"], "Describe the full selected population."),
        ("source.meaning", document["source"]["meaning"], "Retain its keys, types, units and time meaning."),
        ("source.authority", document["source"]["authority"], "Identify the selected source rights and authority."),
        ("payment.network", document["payment"]["network"], "Select the original payment network."),
        ("payment.asset", document["payment"]["asset"], "Select the original payment asset."),
        ("payment.recipient", document["payment"]["recipient"], "Retain the original payment recipient."),
        ("payment.authority", document["payment"]["authority"], "Record the buyer approval and complete-task spending authority."),
        ("receiving.application", document["receiving"]["application"], "Name the receiving application and version."),
        ("receiving.host", document["receiving"]["host"], "Name the authorized receiving host."),
        ("receiving.operator", document["receiving"]["operator"], "Name the receiving operator."),
        ("receiving.acceptanceRule", document["receiving"]["acceptanceRule"], "State the useful-result acceptance."),
        ("receiving.changeAndWithdraw", document["receiving"]["changeAndWithdraw"], "Record the second operator's source or terms change."),
        ("receiving.recovery", document["receiving"]["recovery"], "Select the original recovery procedure."),
        ("receiving.maintenance", document["receiving"]["maintenance"], "Name the maintainer and support destination.")):
        missing(path, value, description)
    for row in document["checks"]:
        if row["required"] and row["state"] not in ("ACCEPTED", "NOT_APPLICABLE"):
            findings.append({"field": "checks." + row["id"], "kind": "ACCEPTANCE",
                             "message": row["title"] + ": " + row["state"].replace("_", " ").lower()})
    for key, label in (("priceAtomic", "unit price"), ("taskBudgetAtomic", "whole task budget")):
        if document["payment"][key] is None:
            findings.append({"field": "payment." + key, "kind": "PAYMENT", "message": "Original " + label + " is unentered."})
    payment = document["payment"]
    total = None
    if payment["priceAtomic"] is not None and payment["taskUnits"] is not None:
        total = str(int(payment["priceAtomic"]) * payment["taskUnits"])
        if payment["taskBudgetAtomic"] is not None and int(total) > int(payment["taskBudgetAtomic"]):
            findings.append({"field": "payment.taskBudgetAtomic", "kind": "PAYMENT",
                             "message": "The selected priced units exceed the entered whole-task atomic budget."})
    work = snapshot["records"]["work"]
    work_groups = {}
    from decimal import Decimal
    for row in work:
        key = (row.get("fundingBasis"), row.get("costId"))
        item = work_groups.setdefault(key, {"fundingBasis": key[0], "costId": key[1],
                                           "recordedHours": Decimal(0), "acceptedHours": Decimal(0)})
        if row["state"] != "VOID":
            item["recordedHours"] += Decimal(row["hours"])
            if row["state"] == "ACCEPTED":
                item["acceptedHours"] += Decimal(row["hours"])
        if row.get("costId") and row["costId"] not in document["assignments"]["costIds"]:
            findings.append({"field": "work." + row["id"], "kind": "ASSIGNMENT",
                             "message": "Selected work retains a funded package outside this installation's assignment."})
    for row in work_groups.values():
        row["recordedHours"], row["acceptedHours"] = str(row["recordedHours"]), str(row["acceptedHours"])
    purchases = snapshot["records"]["purchases"]
    groups = {}
    for row in purchases:
        key = (row["network"], row["asset"])
        item = groups.setdefault(key, {"network": key[0], "asset": key[1], "purchases": 0,
                                      "settledAtomic": 0, "reportedFeesAtomic": 0, "unknownFees": 0})
        item["purchases"] += 1
        if row["state"] != "VOID" and row["settlementStatus"] == "SETTLED":
            item["settledAtomic"] += int(row["amountStroops"])
        if row["state"] != "VOID":
            if row.get("feesStroops") is None:
                item["unknownFees"] += 1
            else:
                item["reportedFeesAtomic"] += int(row["feesStroops"])
    for row in groups.values():
        row["settledAtomic"], row["reportedFeesAtomic"] = str(row["settledAtomic"]), str(row["reportedFeesAtomic"])
    costs = {row["id"]: row for row in snapshot["plan"]["scenario"]["future_costs"]}
    return {"name": document["name"], "stage": document["stage"], "configurationComplete": not any(row["kind"] != "ACCEPTANCE" for row in findings),
            "acceptedChecks": sum(row["state"] == "ACCEPTED" for row in document["checks"]),
            "totalChecks": len(document["checks"]), "findings": findings,
            "pricedTaskAtomic": total, "pricedTaskBasis": "Entered unit price multiplied by entered priced units",
            "packages": [deepcopy(costs[key]) for key in document["assignments"]["costIds"]],
            "work": sorted(work_groups.values(), key=lambda row: (row["fundingBasis"] or "", row["costId"] or "")),
            "purchaseStates": dict(sorted(Counter(row["settlementStatus"] + "/" + row["outputStatus"] + "/" + row["state"]
                                                for row in purchases).items())),
            "purchaseAmounts": sorted(groups.values(), key=lambda row: (row["network"], row["asset"])),
            "sourceFiles": len(snapshot["sources"]), "sourceBytes": sum(row["bytes"] for row in snapshot["sources"].values()),
            **({"workflowPeriods": workflows.report(document)} if document.get("workflowPeriods") else {}),
            **({"useCalendar": use_calendar.report(snapshot, document)} if document.get("useCalendar") else {})}


def differences(before, after, path=""):
    result = []
    if isinstance(before, dict) and isinstance(after, dict):
        for key in sorted(set(before) | set(after)):
            result += differences(before.get(key), after.get(key), (path + "." if path else "") + key)
    elif before != after:
        result.append({"field": path or "installation", "before": before, "after": after})
    return result


def _source(context):
    program, plan = context["program"], context["plan"]
    return {"caseId": program["id"], "version": program["version"], "mode": program["mode"],
            "planId": plan["id"], "planRevision": plan["revision"], "planContentSha256": plan["contentSha256"],
            "planSourceSha256": plan["source"]["sha256"]}


def _current(context, expected):
    expected = domain.integer(expected, "Reviewed operations version", 1, 10000000)
    if context["program"]["version"] != expected:
        fail("The original case changed. Reopen it before reviewing this installation.", "OPERATIONS_CONFLICT", 409)


def seed(context):
    checks = []
    for cost in context["plan"]["scenario"]["future_costs"]:
        check_id = re.sub(r"[^a-z0-9-]", "-", cost["id"].lower()).strip("-")[:80]
        checks.append({"id": check_id, "title": cost["id"], "criterion": cost.get("measurable_proof", ""),
                       "tranche": cost["tranche"], "required": True, "state": "OPEN", "operator": "",
                       "observedAt": None, "note": "", "sourceIds": [], "workIds": [], "purchaseIds": [], "outcomeIds": []})
    return normalized(context, {"name": "Customer installation", "stage": "PLANNED",
        "merchantDeploymentId": None, "buyerDeploymentIds": [], "workorder": {}, "task": {}, "source": {},
        "payment": {}, "receiving": {}, "assignments": {
            "costIds": [row["id"] for row in context["plan"]["scenario"]["future_costs"]],
            "commercialRef": "", "note": "Assign actual implementation work once to the selected original grant package or commercial workorder."},
        "checks": checks})


def preview(operations, context, body):
    object_value(body, ("expectedVersion", "installationId", "expectedRevision", "document", "returnReview"), "installation preview")
    _current(context, body.get("expectedVersion"))
    ident = body.get("installationId")
    expected_revision = revision(body.get("expectedRevision", 0), True)
    previous = None
    if ident is None:
        if expected_revision != 0:
            fail("A new installation starts at edition zero before its first save.")
    else:
        previous = get(operations, context["program"]["id"], ident)
        if previous["revision"] != expected_revision:
            fail("Another installation edition is saved. Reopen its current edition.", "INSTALLATION_CONFLICT", 409)
    document = normalized(context, body.get("document"))
    if previous and previous["preview"]["document"].get("workshare"):
        old = previous["preview"]["document"]["workshare"]
        if document.get("workshare", {}).get("caseId") != old["caseId"]:
            fail("Keep this installation joined to its original Workshare case.", "WORKSHARE_CASE_CONFLICT", 409)
    original_commercial = commercial.verify_document(operations, context, document)
    commercial.verify_transition(operations, context, previous, document, original=original_commercial)
    original_workshare = workshares.verify_document(operations, context, document)
    workshares.verify_transition(operations, context, previous, document, original=original_workshare)
    original_workflow = workflows.verify_document(operations, context, document)
    workflows.verify_transition(operations, context, previous, document, original=original_workflow)
    snapshot = capture(context, document)
    value = {"schema": SCHEMA, "installationId": ident, "expectedRevision": expected_revision,
             "source": _source(context), "document": document, "snapshot": snapshot, "report": report(snapshot, document),
             "previous": None if previous is None else {"id": previous["id"], "revision": previous["revision"], "sha256": previous["sha256"]},
             "changes": differences(previous["preview"]["document"], document) if previous else []}
    if body.get("returnReview") is not None:
        import operations_installation_returns as receiving
        value["returnReview"] = receiving.verify_stage_application(operations, context, body["returnReview"], previous, document)
    value["previewSha256"] = digest(value)
    return value


def save(operations, context, data, actor, version, note):
    object_value(data, ("installationId", "expectedRevision", "document", "expectedPreviewSha256", "returnReview"), "installation save")
    candidate = preview(operations, context, {"expectedVersion": context["program"]["version"],
        **{key: data.get(key) for key in ("installationId", "expectedRevision", "document")},
        **({"returnReview": data["returnReview"]} if data.get("returnReview") is not None else {})})
    if candidate["previewSha256"] != domain.sha(data.get("expectedPreviewSha256"), "Reviewed installation", False):
        fail("The selected input or original records changed. Review the current installation.", "INSTALLATION_PREVIEW_CONFLICT", 409)
    count, distinct = operations.db.execute(
        "SELECT COUNT(*),COUNT(DISTINCT installation_id) FROM ops_installations WHERE program_id=?",
        (context["program"]["id"],)).fetchone()
    if count >= MAX_EDITIONS or candidate["installationId"] is None and distinct >= MAX_INSTALLATIONS:
        fail("This case has reached its retained installation-edition capacity.", status=413)
    ident = candidate["installationId"] or "installation-" + uuid.uuid4().hex
    row = {"id": ident, "revision": candidate["expectedRevision"] + 1, "version": version,
           "createdAt": now(), "actor": actor, "note": short_text(note, "Installation save reason", 12000, True),
           "preview": candidate}
    row["sha256"] = digest(row)
    operations.db.execute("INSERT INTO ops_installations VALUES(?,?,?,?)",
                         (context["program"]["id"], ident, row["revision"], canonical(row)))
    return {"before": candidate["previous"], "after": summary(row), "kind": "installation", "recordId": ident,
            "revision": row["revision"], "sha256": row["sha256"], "unchanged": False}


def show(operations, context, installation_id, selected_revision=None):
    row = get(operations, context["program"]["id"], installation_id, selected_revision)
    try:
        current = capture(context, normalized(context, row["preview"]["document"]))
        before = row["preview"]["snapshot"]
        changed = current["records"] != before["records"] or current["sources"] != before["sources"] or \
            current["plan"]["contentSha256"] != before["plan"]["contentSha256"]
        current_state = {"available": True, "selectedRecordsChanged": changed,
                         "caseVersion": context["program"]["version"]}
    except (Problem, KeyError):
        current_state = {"available": False, "selectedRecordsChanged": True,
                         "caseVersion": context["program"]["version"]}
    return {**row, "current": current_state}


def history(operations, program_id, installation_id, before=None, limit=25):
    identity(installation_id)
    domain.integer(limit, "Installation history page size", 1, 100)
    if before is not None:
        revision(before)
    rows = [json.loads(row[0]) for row in operations.db.execute(
        "SELECT body_json FROM ops_installations WHERE program_id=? AND installation_id=?"
        + (" AND revision<?" if before is not None else "") + " ORDER BY revision DESC LIMIT ?",
        (program_id, installation_id, before, limit + 1) if before is not None else (program_id, installation_id, limit + 1))]
    more = len(rows) > limit
    rows = rows[:limit]
    return {"editions": [summary(row) for row in rows], "nextBefore": rows[-1]["revision"] if more else None}


def _record_matches(events, final_records):
    """Index complete native states retained by their existing mutation events."""
    result = defaultdict(set)
    def visit(value):
        if isinstance(value, dict):
            if isinstance(value.get("id"), str) and isinstance(value.get("version"), int) and "recordedBy" in value:
                result[(value["id"], value["version"])].add(digest(value))
            for item in value.values():
                visit(item)
        elif isinstance(value, list):
            for item in value:
                visit(item)
    for values in final_records.values():
        visit(values)
    for event in events:
        visit(event.get("before"))
        visit(event.get("after"))
    return result


def validate_import(context, rows, events, source_version, source_files=None, *, plan_for_version=None):
    if not isinstance(rows, list) or len(rows) > MAX_EDITIONS:
        fail("The complete installation history is invalid.")
    by_id, seen = {}, set()
    states = _record_matches(events, context["records"])
    for row in rows:
        object_value(row, ("id", "revision", "version", "createdAt", "actor", "note", "preview", "sha256"),
                     "saved installation edition")
        ident, number = identity(row.get("id")), revision(row.get("revision"))
        if (ident, number) in seen:
            fail("The complete case repeats an installation edition.")
        seen.add((ident, number))
        by_id.setdefault(ident, []).append(row)
        domain.integer(row.get("version"), "Installation save version", 2, source_version)
        domain.timestamp(row.get("createdAt"), "Original installation save time")
        short_text(row.get("actor"), "Original installation author", 300, True)
        short_text(row.get("note"), "Original installation save reason", 12000, True)
        if digest({key: value for key, value in row.items() if key != "sha256"}) != row.get("sha256"):
            fail("A retained installation edition differs from its complete identity.")
        candidate = row.get("preview")
        object_value(candidate, ("schema", "installationId", "expectedRevision", "source", "document", "snapshot",
            "report", "previous", "changes", "previewSha256", "returnReview"), "saved installation preview")
        if candidate.get("schema") != SCHEMA or candidate.get("expectedRevision") != number - 1:
            fail("A retained installation uses a different edition contract.")
        if digest({key: value for key, value in candidate.items() if key != "previewSha256"}) != candidate.get("previewSha256"):
            fail("A retained installation preview differs from its selected input.")
        snapshot = candidate.get("snapshot")
        if not isinstance(snapshot, dict) or set(snapshot) != {"program", "plan", "records", "sources"}:
            fail("The complete original installation snapshot is required.")
        selected_plan = plan_for_version(row["version"] - 1) if plan_for_version else context["plan"]
        if (any(snapshot["plan"].get(key) != selected_plan.get(key) for key in
                ("scenario", "planning", "report", "source", "revision", "contentSha256"))
                or snapshot["program"]["mode"] != context["program"]["mode"]
                or snapshot["program"]["version"] != row["version"] - 1
                or candidate["source"] != _source(snapshot)):
            fail("The installation must retain its original selected case and funding plan.")
        document = normalized(snapshot, candidate.get("document"))
        if document.get("commercial"):
            if source_files is None:
                fail("Receive the complete original commercial source files with this Installation.")
            commercial.verify_document(None, snapshot, document, lambda source_id: source_files.get("sources/" + source_id))
        if document.get("workshare"):
            if source_files is None:
                fail("Receive the complete original Workshare attachments with this installation.")
            workshares.verify_document(None, snapshot, document, lambda source_id: source_files.get("sources/" + source_id))
        if document.get("workflowPeriods"):
            if source_files is None:
                fail("Receive the complete original recurring-work source with this Installation.")
            workflows.verify_document(None, snapshot, document, lambda source_id: source_files.get("sources/" + source_id))
        if document != candidate["document"] or capture(snapshot, document) != snapshot:
            fail("The installation's selected records or sources are incomplete.")
        for source_id, metadata in snapshot["sources"].items():
            present = context["sources"].get(source_id)
            if not present or any(present.get(key) != metadata.get(key) for key in
                ("id", "filename", "bytes", "sha256", "createdAt", "observedAt", "mediaType", "kind", "sourceUrl")):
                fail("An installation source is absent from the complete case.")
        for values in snapshot["records"].values():
            for record in values:
                if record["version"] >= row["version"] or digest(record) not in states[(record["id"], record["version"])]:
                    fail("A selected installation record is missing from its original case history.")
        if candidate["report"] != report(snapshot, document):
            fail("The installation report differs from its retained original observations.")
        event = events[row["version"] - 1]
        if (event.get("action") != "installation.save" or event.get("recordId") != ident
                or event.get("after") != summary(row)):
            fail("The installation edition does not join its original save event.")
    if len(by_id) > MAX_INSTALLATIONS:
        fail("The complete case has too many installations.")
    for ident, values in by_id.items():
        values.sort(key=lambda row: row["revision"])
        previous = None
        for number, row in enumerate(values, 1):
            candidate = row["preview"]
            expected_previous = None if previous is None else {
                "id": ident, "revision": previous["revision"], "sha256": previous["sha256"]}
            if (row["revision"] != number or candidate["previous"] != expected_previous
                    or candidate["installationId"] != (ident if previous else None)
                    or candidate["changes"] != (differences(previous["preview"]["document"], candidate["document"]) if previous else [])
                    or previous is not None and previous["version"] >= row["version"]):
                fail("The original installation edition sequence is incomplete.")
            commercial.verify_transition(None, candidate["snapshot"], previous, candidate["document"],
                lambda source_id: source_files.get("sources/" + source_id))
            workshares.verify_transition(None, candidate["snapshot"], previous, candidate["document"],
                lambda source_id: source_files.get("sources/" + source_id))
            workflows.verify_transition(None, candidate["snapshot"], previous, candidate["document"],
                lambda source_id: source_files.get("sources/" + source_id))
            previous = row
    if {(event.get("recordId"), event.get("after", {}).get("revision")) for event in events
            if event.get("action") == "installation.save"} != seen:
        fail("The complete case is missing an original saved installation.")


def html_document(row, original_workshare=None, original_commercial=None):
    value, document = row["preview"], row["preview"]["document"]
    e = lambda item: escape(str(item if item is not None else "Unentered"), quote=True)
    def table(headings, values):
        return "<div class=\"table\"><table><thead><tr>" + "".join("<th>" + e(item) + "</th>" for item in headings) \
            + "</tr></thead><tbody>" + "".join("<tr>" + "".join("<td>" + item + "</td>" for item in items) + "</tr>" for items in values) \
            + "</tbody></table></div>"
    def pretty(item):
        return e(canonical(item) if isinstance(item, (dict, list)) else item)
    body = "<h1>" + e(document["name"]) + "</h1><p>Installation edition " + str(row["revision"]) + " · " \
        + e(document["stage"]) + " · saved " + e(row["createdAt"]) + " by " + e(row["actor"]) + "</p>"
    body += "<p><strong>Original case purpose:</strong> " + e(value["source"]["mode"]) + ". Source case " \
        + e(value["source"]["caseId"]) + ", version " + str(value["source"]["version"]) + ".</p>"
    body += "<p>" + e(row["note"]) + "</p>"
    for key, label in (("workorder", "Original commissioning"), ("task", "Useful customer task"), ("source", "Source meaning and authority"),
                       ("payment", "Payment and complete-task budget"), ("receiving", "Receiving and maintenance"),
                       ("assignments", "Original funded and commercial assignments")):
        body += "<h2>" + label + "</h2>" + table(["Field", "Selected value"],
            [[e(name), pretty(item)] for name, item in document[key].items()])
    body += dispatch.installation_section(document)
    body += commercial.html_section(original_commercial)
    body += workshares.html_section(original_workshare)
    body += workflows.html_section(document)
    body += use_calendar.installation_section(document)
    body += "<h2>Acceptance and corrections</h2>" + table(
        ["Step", "Original criterion", "State", "Operator / observed", "Result / source"],
        [[e(item["title"]), e(item["criterion"]), e(item["state"]),
          e(item["operator"]) + "<br>" + e(item["observedAt"]), e(item["note"]) + "<pre>" +
          pretty({key: item[key] for key in ("sourceIds", "workIds", "purchaseIds", "outcomeIds")}) + "</pre>"]
         for item in document["checks"]])
    body += "<h2>Selected original deployment, work and purchase records</h2>"
    for kind, rows in value["snapshot"]["records"].items():
        if rows:
            body += "<h3>" + e(kind) + "</h3>" + "".join("<details><summary>" + e(item.get("name") or item.get("description") or item["id"])
                + "</summary><pre>" + e(json.dumps(item, ensure_ascii=False, indent=2)) + "</pre></details>" for item in rows)
    body += "<h2>Retained report</h2><pre>" + e(json.dumps(value["report"], ensure_ascii=False, indent=2)) + "</pre>"
    body += "<h2>Complete original files</h2>" + table(["File", "Bytes", "SHA-256"],
        [["<a download href=\"sources/" + e(item["id"]) + "\">" + e(item["filename"]) + "</a>",
          str(item["bytes"]), e(item["sha256"])] for item in value["snapshot"]["sources"].values()])
    body += "<h2>Changes from the preceding edition</h2>" + table(["Field", "Before", "This edition"],
        [[e(item["field"]), pretty(item["before"]), pretty(item["after"])] for item in value["changes"]])
    body += "<h2>Open the complete operating case</h2><p>Import this entire ZIP through the original SF47 Delivery operations "
    body += "Import complete case control or its operations import command. The selected installation edition, every earlier edition, "
    body += "original work, purchases, source files and planning history open together. The receiving workspace supplies its own private access authority.</p>"
    body += "<p>Installation " + e(row["id"]) + " · edition SHA-256 " + e(row["sha256"]) + "</p>"
    return ("<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
            "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; style-src 'unsafe-inline'\">"
            "<title>" + e(document["name"]) + "</title><style>"
            "body{margin:0 auto;padding:32px;max-width:1180px;background:#fff;color:#202020;font:15px/1.55 system-ui,sans-serif}"
            "h1{font-size:28px}h2{margin-top:32px;border-bottom:1px solid #bbb;padding-bottom:8px}h3{font-size:17px}"
            "table{border-collapse:collapse;width:100%}th,td{text-align:left;vertical-align:top;padding:10px;border:1px solid #bbb}"
            "th{background:#eee}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 ui-monospace,monospace}"
            ".table{overflow:auto}td{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#222;text-decoration:underline}"
            "details{border:1px solid #ccc;padding:12px;margin:8px 0}summary{cursor:pointer}@media(max-width:650px){body{padding:16px}}"
            "</style><body>" + body + "</body></html>\n").encode("utf-8")


def selected_files(context, rows, installation_id, selected_revision, source_files=None):
    ident = identity(installation_id)
    number = revision(selected_revision)
    row = next((value for value in rows if value["id"] == ident and value["revision"] == number), None)
    if row is None:
        fail("The selected installation edition is unavailable.", "INSTALLATION_NOT_FOUND", 404)
    original = None
    if row["preview"]["document"].get("workshare"):
        if source_files is None:
            fail("Export the original Workshare source together with the selected installation.")
        original = workshares.verify_document(None, row["preview"]["snapshot"], row["preview"]["document"],
                                             lambda source_id: source_files.get("sources/" + source_id))
    if row["preview"]["document"].get("workflowPeriods"):
        if source_files is None:
            fail("Export the complete recurring-work source with the selected Installation.")
        workflows.verify_document(None, row["preview"]["snapshot"], row["preview"]["document"],
                                  lambda source_id: source_files.get("sources/" + source_id))
    original_commercial = None
    if row["preview"]["document"].get("commercial"):
        if source_files is None:
            fail("Export the complete original quotation and customer-response source files with this Installation.")
        original_commercial = commercial.verify_document(None, row["preview"]["snapshot"], row["preview"]["document"],
            lambda source_id: source_files.get("sources/" + source_id))
    document = html_document(row, original, original_commercial)
    selection = {"schema": SELECTION_SCHEMA, "caseId": context["program"]["id"],
                 "caseVersion": context["program"]["version"], "installationId": ident,
                 "revision": number, "sha256": row["sha256"],
                 "document": {"path": "installation.html", "bytes": len(document),
                              "sha256": hashlib.sha256(document).hexdigest()}}
    return {"installation-selection.json": (canonical(selection) + "\n").encode("utf-8"),
            "installation.html": document}


def selection_from_files(document, files):
    selected_names = {"installation-selection.json", "installation.html"}
    if not selected_names.intersection(files):
        return None
    if not selected_names.issubset(files):
        fail("The selected installation handover is incomplete.")
    try:
        selection = json.loads(files["installation-selection.json"])
        object_value(selection, ("schema", "caseId", "caseVersion", "installationId", "revision", "sha256", "document"),
                     "installation handover selection")
        ident, number = identity(selection.get("installationId")), revision(selection.get("revision"))
        row = next((value for value in document.get("installations", [])
                    if value["id"] == ident and value["revision"] == number), None)
        raw = files["installation.html"]
        descriptor = {"path": "installation.html", "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}
        if (not row or selection != {"schema": SELECTION_SCHEMA, "caseId": document["program"]["id"],
                "caseVersion": document["program"]["version"], "installationId": ident, "revision": number,
                "sha256": row["sha256"], "document": descriptor}):
            fail("The installation selection or readable handover differs from its retained edition.")
        # Keep the exact received rendition across later software/template changes.
        # Only the normalized saved edition drives the native operator; this HTML
        # remains a complete downloaded document under the archive's file manifest.
        raw.decode("utf-8")
    except (ValueError, TypeError, KeyError, AttributeError, UnicodeError) as exc:
        if isinstance(exc, Problem):
            raise
        raise Problem("The installation selection is unreadable.", 422, "INVALID_INSTALLATION") from exc
    return {"id": ident, "revision": number, "sha256": selection["sha256"]}

"""Return a complete customer Installation through the original Operations case.

The receiver freezes observations against one saved edition. The owner stages
explicit selections as evidence, then uses Installation preview/save unchanged.
The original workspace transaction, request journal and complete ZIP own custody.
"""
from __future__ import annotations

import base64
from copy import deepcopy
from html import escape
import hashlib
import io
import json
import zipfile
import re
import uuid

from model import Problem, canonical, digest, now, text, inspect_planning_history
import operations_domain as domain
import operations_installations as installations

SCHEMA = "stellar-forge.sf47-installation-return.v1"
PURPOSE = "INSTALLATION_RETURN"
STAGE_PURPOSE = "INSTALLATION_RETURN_REVIEW"
MAX_REVIEW = 8 * 1024 * 1024
MAX_REVIEWS = 200
MAX_PROOF_DEPTH = 16
OBSERVATION_KEYS = ("state", "operator", "observedAt", "note", "sourceIds",
                    "workIds", "purchaseIds", "outcomeIds")
DEFINITION_KEYS = ("id", "title", "criterion", "tranche", "required")
SOURCE_KEYS = ("id", "filename", "mediaType", "kind", "sourceUrl", "observedAt",
               "bytes", "sha256", "createdAt")


def fail(message, code="INVALID_INSTALLATION_RETURN", status=422):
    raise Problem(message, status, code)


def obj(value, fields, label):
    if not isinstance(value, dict) or set(value) - set(fields):
        fail("Use the complete declared " + label + " fields.")
    return value


def equal(left, right):
    # JSON equality must distinguish true from 1 in every nested value.
    return canonical(left) == canonical(right)


def ref(row):
    return {key: row[key] for key in ("id", "revision", "sha256")}


def review_id(value):
    if not isinstance(value, str) or not re.fullmatch(r"review-[a-f0-9]{32}", value):
        fail("Select the original receiving review identity.")
    return value


def case_id(value):
    if not isinstance(value, str) or not re.fullmatch(r"operation-[a-f0-9]{32}", value):
        fail("Select the original operating case identity.")
    return value


def bounded(value):
    if len(canonical(value).encode("utf-8")) > MAX_REVIEW:
        fail("This complete receiving review exceeds the original 8 MiB source bound. "
             "Keep the full returned case and review a supported installation scope.",
             "INSTALLATION_RETURN_SIZE", 413)
    return value


def context_view(context):
    return {"program": {key: deepcopy(context["program"][key])
                        for key in ("id", "name", "mode", "calendarStart", "version")},
            "plan": deepcopy(context["plan"]), "records": deepcopy(context["records"]),
            "sources": deepcopy(context["sources"])}


def review_context(row):
    snapshot = row["snapshot"]
    return {"program": {**deepcopy(snapshot["program"]), "version": row["version"] - 1},
            "plan": deepcopy(snapshot["plan"]), "records": deepcopy(snapshot["records"]),
            "sources": {item["id"]: deepcopy(item) for item in snapshot["sources"]}}


def checked_installation(row):
    if not isinstance(row, dict) or digest({key: value for key, value in row.items()
                                           if key != "sha256"}) != row.get("sha256"):
        fail("The original Installation edition changed.", "INSTALLATION_RETURN_CHANGED", 409)
    installations.identity(row.get("id"))
    installations.revision(row.get("revision"))
    value = row.get("preview", {})
    if value.get("schema") != installations.SCHEMA or digest({key: item for key, item in value.items()
            if key != "previewSha256"}) != value.get("previewSha256"):
        fail("The original Installation preview is incomplete.")
    snapshot, document = value["snapshot"], value["document"]
    if (not equal(installations.normalized(snapshot, document), document)
            or not equal(installations.capture(snapshot, document), snapshot)
            or not equal(installations.report(snapshot, document), value["report"])
            or value["source"] != installations._source(snapshot)
            or row["revision"] != value["expectedRevision"] + 1):
        fail("The original Installation no longer reconstructs from its complete snapshot.")
    return row


def selected_baseline(ops, context, selection):
    obj(selection, ("installationId", "revision", "sha256"), "saved Installation selection")
    row = installations.get(ops, context["program"]["id"], selection.get("installationId"),
                            selection.get("revision"))
    if row["sha256"] != domain.sha(selection.get("sha256"), "Selected Installation", False):
        fail("The selected saved Installation has changed.", "INSTALLATION_RETURN_BASELINE", 409)
    return checked_installation(row)


def acceptance_basis(context, document):
    # Observation links and named results do not redefine the work being checked.
    selected = deepcopy(document)
    selected["checks"] = [{**{key: item[key] for key in DEFINITION_KEYS},
        "state": "OPEN", "operator": "", "observedAt": None, "note": "",
        "sourceIds": [], "workIds": [], "purchaseIds": [], "outcomeIds": []}
        for item in document["checks"]]
    snapshot = installations.capture(context, installations.normalized(context, selected))
    fields = ("merchantDeploymentId", "buyerDeploymentIds", "workorder", "task", "source",
              "payment", "receiving", "workshare", "workflowPeriods", "coordination")
    return {"definition": {key: deepcopy(document[key]) for key in fields if key in document},
            "plan": {key: snapshot["plan"][key] for key in ("revision", "contentSha256", "source")},
            "deployments": snapshot["records"]["deployments"], "sources": snapshot["sources"]}


def normalized_return(context, baseline, supplied):
    obj(supplied, ("installationId", "revision", "sha256", "name", "recipient",
                   "environment", "note", "observations"), "receiving return")
    if (supplied.get("installationId"), supplied.get("revision"), supplied.get("sha256")) != \
            (baseline["id"], baseline["revision"], baseline["sha256"]):
        fail("Keep the complete original saved edition selection.")
    originals = baseline["preview"]["document"]["checks"]
    observations = supplied.get("observations")
    if not isinstance(observations, list) or len(observations) != len(originals):
        fail("Record every original check, including unfinished or inapplicable work.")
    by_id = {}
    for value in observations:
        obj(value, ("id", *OBSERVATION_KEYS), "original check observation")
        ident = value.get("id")
        if ident in by_id or not any(item["id"] == ident for item in originals):
            fail("Keep each original check identity exactly once.")
        by_id[ident] = value
    document = deepcopy(baseline["preview"]["document"])
    document["checks"] = [{**{key: item[key] for key in DEFINITION_KEYS},
                            **{key: by_id[item["id"]].get(key) for key in OBSERVATION_KEYS}}
                           for item in originals]
    document = installations.normalized(context, document)
    return {"installationId": baseline["id"], "revision": baseline["revision"], "sha256": baseline["sha256"],
            "name": text(supplied.get("name"), "Receiving return name", 300, True),
            "recipient": text(supplied.get("recipient"), "Intended receiving owner", 500, True),
            "environment": text(supplied.get("environment"), "Actual application, host and configuration", 8000, True),
            "note": text(supplied.get("note"), "Whole receiving outcome and limitations", 12000, True),
            "observations": [{key: item[key] for key in ("id", *OBSERVATION_KEYS)} for item in document["checks"]]}, document


def seed(ops, context, body):
    obj(body, ("expectedVersion", "installationId", "revision", "sha256"), "return seed")
    installations._current(context, body.get("expectedVersion"))
    baseline = selected_baseline(ops, context, {key: body.get(key) for key in ("installationId", "revision", "sha256")})
    return {"schema": SCHEMA + ".seed", "source": installations._source(context), "baseline": ref(baseline),
            "inputs": {"installationId": baseline["id"], "revision": baseline["revision"], "sha256": baseline["sha256"],
                "name": baseline["preview"]["document"]["name"] + " — receiving return",
                "recipient": "", "environment": "", "note": "",
                "observations": [{"id": check["id"], "state": "OPEN", "operator": "", "observedAt": None,
                                 "note": "", "sourceIds": [], "workIds": [], "purchaseIds": [], "outcomeIds": []}
                                for check in baseline["preview"]["document"]["checks"]]},
            "checks": [{key: item[key] for key in DEFINITION_KEYS} for item in baseline["preview"]["document"]["checks"]]}


def evaluate_return(context, baseline, supplied):
    context, baseline = context_view(context), checked_installation(deepcopy(baseline))
    inputs, document = normalized_return(context, baseline, supplied)
    selected = installations.capture(context, document)
    original_basis = acceptance_basis(baseline["preview"]["snapshot"], baseline["preview"]["document"])
    receiving_basis = acceptance_basis(context, document)
    changes = installations.differences(original_basis, receiving_basis)
    report = installations.report(selected, document)
    result = {"schema": SCHEMA, "source": installations._source(context), "inputs": inputs,
              "baseline": baseline, "document": document, "snapshot": selected, "report": report,
              "receivingBasisChanges": changes, "basisUnchanged": not changes}
    result["previewSha256"] = digest(result)
    return bounded(result)


def preview(ops, context, body):
    obj(body, ("expectedVersion", "inputs"), "return preview")
    installations._current(context, body.get("expectedVersion"))
    supplied = body.get("inputs")
    if not isinstance(supplied, dict):
        fail("Use the complete receiving input.")
    baseline = selected_baseline(ops, context, {key: supplied.get(key) for key in ("installationId", "revision", "sha256")})
    return evaluate_return(context, baseline, supplied)


def row_summary(row):
    value = row["installationReturn"] if row["purpose"] == PURPOSE else row["installationReturnReview"]
    selection = value["baseline"] if row["purpose"] == PURPOSE else value["currentInstallation"]
    return {"id": row["id"], "version": row["version"], "purpose": row["purpose"],
            "businessSha256": row["businessSha256"], "sha256": row["sha256"],
            "previewSha256": value["previewSha256"],
            "installationId": selection["id"], "revision": selection["revision"],
            "name": value["inputs"]["name"], "createdAt": row["createdAt"], "actor": row["actor"]}


def save_row(ops, context, purpose, candidate, actor, version, note):
    count = ops.db.execute("SELECT COUNT(*) FROM ops_reviews WHERE program_id=?", (context["program"]["id"],)).fetchone()[0]
    if count >= MAX_REVIEWS:
        fail("The original case has reached its 200 retained review capacity.", status=413)
    snapshot = ops._business(context)
    field = "installationReturn" if purpose == PURPOSE else "installationReturnReview"
    row = {"id": "review-" + uuid.uuid4().hex, "version": version, "createdAt": now(), "actor": actor,
           "note": text(note, "Named receiving review note", 12000, True),
           "businessSha256": digest(snapshot), "snapshot": snapshot, "report": domain.report(**context),
           "purpose": purpose, field: candidate}
    row["sha256"] = digest(row)
    bounded(row)
    ops.db.execute("INSERT INTO ops_reviews VALUES(?,?,?)", (context["program"]["id"], row["id"], canonical(row)))
    return row


def record(ops, context, data, actor, version, note):
    obj(data, ("inputs", "expectedPreviewSha256"), "receiving return save")
    candidate = preview(ops, context, {"expectedVersion": context["program"]["version"], "inputs": data.get("inputs")})
    if candidate["previewSha256"] != domain.sha(data.get("expectedPreviewSha256"), "Reviewed return", False):
        fail("The receiving input or source case changed. Review the same saved draft.", "INSTALLATION_RETURN_PREVIEW", 409)
    row = save_row(ops, context, PURPOSE, candidate, actor, version, note)
    return {"before": None, "after": row_summary(row), "kind": "review", "recordId": row["id"],
            "reviewSha256": row["sha256"], "previewSha256": candidate["previewSha256"], "unchanged": False}


def validate_row_identity(row, purpose):
    if not isinstance(row, dict) or row.get("purpose") != purpose:
        fail("Select the original receiving review.", "INSTALLATION_RETURN_NOT_FOUND", 404)
    review_id(row.get("id"))
    domain.integer(row.get("version"), "Receiving review version", 2, 10000000)
    domain.timestamp(row.get("createdAt"), "Receiving review creation")
    text(row.get("actor"), "Named receiving operator", 300, True)
    text(row.get("note"), "Receiving review note", 12000, True)
    if digest({key: value for key, value in row.items() if key != "sha256"}) != row.get("sha256") or \
            digest(row.get("snapshot")) != row.get("businessSha256"):
        fail("The complete original receiving review changed.", "INSTALLATION_RETURN_CHANGED", 409)
    bounded(row)


def validate_return(row):
    validate_row_identity(row, PURPOSE)
    value = row.get("installationReturn", {})
    context = review_context(row)
    actual = evaluate_return(context, value.get("baseline"), value.get("inputs"))
    if not equal(actual, value) or not equal(domain.report(**context), row["report"]):
        fail("The receiving return differs from its original inputs, criterion or retained records.")
    if value["baseline"]["version"] >= row["version"]:
        fail("Receiving must follow its selected saved Installation.")
    return row


def validate_sources(context, files):
    for ident, metadata in context["sources"].items():
        if metadata.get("id") != ident:
            fail("A receiving source identity changed.")
        raw = files.get("sources/" + ident)
        if not isinstance(raw, bytes) or len(raw) != metadata["bytes"] or hashlib.sha256(raw).hexdigest() != metadata["sha256"]:
            fail("Retain every complete receiving source with its original hash.")


def validate_return_in_case(row, context, events, saved_installations, files, *, plan_for_version=None):
    validate_return(row)
    if plan_for_version is not None:
        import operations_amendments as amendments
        if amendments.plan_core(review_context(row)["plan"]) != amendments.plan_core(plan_for_version(row["version"] - 1)):
            fail("The receiving observation differs from the native plan selected at its original save.")
    value = row["installationReturn"]
    baseline = value["baseline"]
    if not any(equal(item, baseline) for item in saved_installations):
        fail("The returned case lost its selected original Installation edition.")
    states = installations._record_matches(events, context["records"])
    for kind, values in value["snapshot"]["records"].items():
        for item in values:
            if item["version"] >= row["version"] or digest(item) not in states.get((item["id"], item["version"]), set()):
                fail("The receiving observation lost its original record history.")
    for ident, metadata in value["snapshot"]["sources"].items():
        if not equal(context["sources"].get(ident), metadata):
            fail("The receiving observation lost an original source identity.")
    event = events[row["version"] - 1]
    if (event.get("action") != "installation.return" or event.get("recordId") != row["id"]
            or not equal(event.get("after"), row_summary(row))
            or event.get("actor") != row["actor"] or event.get("note") != row["note"]):
        fail("The receiving return lost its exact original save event.")
    validate_sources({"sources": value["snapshot"]["sources"]}, files)



def planning_evidence(ops, program_id):
    """Keep native history/source content stable across preview and its later save."""
    program, _ = ops._program(program_id)
    raw = ops.workspace.export(program["planId"])
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        original = json.loads(archive.read("workspace.json"))
        source = archive.read("original-source.json")
    # Export time describes an individual download, not the selected plan. Every
    # original revision and the exact source bytes remain in this complete proof.
    document = {key: original[key] for key in ("schema", "plan", "revisions")}
    return {"document": document, "originalSource": {"bytes": len(source),
        "sha256": hashlib.sha256(source).hexdigest(), "contentBase64": base64.b64encode(source).decode("ascii")}}


def plan_for_proof(proof, files):
    import operations_amendments as amendments
    import operations_work_intake as work_intake
    from operations import Operations
    context, events = proof["context"], proof["events"]
    evidence = proof.get("planningEvidence")
    if evidence is None:
        if proof.get("amendments") or proof.get("workIntakes") or any(
                event.get("action", "").startswith("amendment.") for event in events):
            fail("Retain the original native planning history behind this amended receiving case.")
        return lambda version: context["plan"]
    obj(evidence, ("document", "originalSource"), "original native planning evidence")
    source = obj(evidence.get("originalSource"), ("bytes", "sha256", "contentBase64"), "original planner source")
    try:
        raw = base64.b64decode(source.get("contentBase64", ""), validate=True)
        if (type(source.get("bytes")) is not int or source["bytes"] != len(raw)
                or hashlib.sha256(raw).hexdigest() != source.get("sha256")):
            fail("The original planning source bytes changed.")
        document = evidence["document"]
        inspect_planning_history(document, raw)
        selected = next((row for row in document["revisions"] if row["revision"] == context["plan"]["revision"]), None)
        if (document["plan"]["id"] != context["plan"]["id"]
                or document["plan"]["source"] != context["plan"]["source"] or selected is None
                or amendments.plan_core(selected) != amendments.plan_core(context["plan"])):
            fail("The complete original planning history does not contain the selected receiving plan.")
        history = amendments.validate_import(Operations, context, proof.get("amendments", []), events, None,
            work_intakes=proof.get("workIntakes", []), planning_document=document)
        selected_plan = lambda version: amendments.plan_at(history, context["plan"], version)
        work_intake.validate_import(context, proof.get("workIntakes", []), events, files, plan_for_version=selected_plan)
        return selected_plan
    except (KeyError, TypeError, ValueError, UnicodeError) as exc:
        if isinstance(exc, Problem):
            raise
        raise Problem("The complete native planning evidence is unreadable.", 422, "INVALID_INSTALLATION_RETURN") from exc


def retained_review_pin(value):
    obj(value, ("id", "sha256"), "retained owner review selection")
    return {"id": review_id(value.get("id")),
            "sha256": domain.sha(value.get("sha256"), "Retained owner review", False)}


def retained_review(reviews, selection, before_version=None):
    pin = retained_review_pin(selection)
    found = [row for row in reviews if row.get("id") == pin["id"]]
    if len(found) != 1 or found[0].get("sha256") != pin["sha256"]:
        fail("The retained owner review differs from this exact selected case.", "INSTALLATION_RETURN_SELECTION", 409)
    row = found[0]
    validate_row_identity(row, STAGE_PURPOSE)
    if before_version is not None and row["version"] >= before_version:
        fail("A continued return must reference an earlier original owner review.")
    return row


def case_review_rows(ops, program_id):
    return [json.loads(row[0]) for row in ops.db.execute(
        "SELECT body_json FROM ops_reviews WHERE program_id=? ORDER BY rowid", (program_id,))
        if json.loads(row[0]).get("purpose") in (PURPOSE, STAGE_PURPOSE)]


def retained_original_files(ops, context, row):
    """Reconstruct original returned names from the owner's already retained bytes."""
    value, original_files = row["installationReturnReview"], {}
    for mapping in value["sourceMappings"]:
        original, retained = mapping["original"], mapping["retained"]
        actual, raw = ops.source(context["program"]["id"], retained["id"])
        if (not equal(actual, retained) or not equal(context["sources"].get(retained["id"]), retained)
                or len(raw) != original["bytes"] or hashlib.sha256(raw).hexdigest() != original["sha256"]):
            fail("An original returned file differs from its retained owner mapping.", "INSTALLATION_RETURN_SOURCE", 409)
        original_files["sources/" + original["id"]] = raw
    validate_proof(value["returnedProof"], original_files)
    return original_files


def proof_selection(ops, context, supplied):
    if supplied.get("retainedReview") is not None:
        rows = case_review_rows(ops, context["program"]["id"])
        origin = retained_review(rows, supplied["retainedReview"])
        proof = deepcopy(origin["installationReturnReview"]["returnedProof"])
        if (supplied.get("returnedCaseId") != proof["context"]["program"]["id"]
                or supplied.get("reviewId") != proof["review"]["id"]
                or supplied.get("reviewSha256") != proof["review"]["sha256"]):
            fail("Keep the original customer return behind the selected owner review.", "INSTALLATION_RETURN_SELECTION", 409)
        return proof, retained_original_files(ops, context, origin), origin
    proof = proof_for(ops, supplied.get("returnedCaseId"), supplied.get("reviewId"))
    files = {"sources/" + ident: ops.source(proof["context"]["program"]["id"], ident)[1]
             for ident in proof["context"]["sources"]}
    validate_proof(proof, files)
    return proof, files, None


def proof_for(ops, program_id, selected_review):
    context = context_view(ops._context(case_id(program_id)))
    row = ops.review(program_id, review_id(selected_review))
    validate_return(row)
    events = [json.loads(value[0]) for value in ops.db.execute(
        "SELECT body_json FROM ops_events WHERE program_id=? ORDER BY version", (program_id,))]
    import operations_amendments as amendments
    import operations_work_intake as work_intake
    proof = {"schema": SCHEMA + ".original-case-evidence", "context": context,
             "installations": installations.load(ops, program_id), "events": events, "review": row,
             "planningEvidence": planning_evidence(ops, program_id), "amendments": amendments.load(ops, program_id),
             "workIntakes": work_intake.load(ops, program_id), "receivingReviews": case_review_rows(ops, program_id)}
    return bounded(proof)


def validate_proof(proof, files, *, _depth=0):
    if _depth > MAX_PROOF_DEPTH:
        fail("The retained receiving lineage exceeds the supported complete proof depth.", "INSTALLATION_RETURN_SIZE", 413)
    bounded(proof)
    obj(proof, ("schema", "context", "installations", "events", "review", "planningEvidence",
                "amendments", "workIntakes", "receivingReviews"), "complete original receiving evidence")
    if proof.get("schema") != SCHEMA + ".original-case-evidence":
        fail("Use the original returned case evidence.")
    context, events = proof["context"], proof["events"]
    if not equal(context_view(context), context) or set(context["records"]) != set(domain.KINDS):
        fail("The full receiving case selection is incomplete.")
    if not isinstance(events, list) or len(events) != context["program"]["version"]:
        fail("The complete original receiving history is required.")
    for number, event in enumerate(events, 1):
        if event.get("version") != number or digest({key: value for key, value in event.items() if key != "sha256"}) != event.get("sha256"):
            fail("An original receiving history event changed.")
    plan = context["plan"]
    if digest({"scenario": plan["scenario"], "planning": plan["planning"]}) != plan["contentSha256"]:
        fail("The selected original receiving plan changed.")
    for kind, values in context["records"].items():
        seen = set()
        if not isinstance(values, list):
            fail("The original receiving record collection is incomplete.")
        for record in values:
            if record.get("id") in seen:
                fail("The receiving case repeats an original record.")
            seen.add(record.get("id"))
            domain.integer(record.get("version"), "Receiving record version", 1, context["program"]["version"])
            prepared = domain.prepare(kind, record, {**context, "restoring": True}, record)
            if any(key != "state" and not equal(record.get(key), item) for key, item in prepared.items()):
                fail("An original receiving record differs from its normalized source.")
    validate_sources(context, files)
    selected_plan = plan_for_proof(proof, files)
    installations.validate_import(context, proof["installations"], events, context["program"]["version"], files,
                                  plan_for_version=selected_plan)
    validate_return_in_case(proof["review"], context, events, proof["installations"], files, plan_for_version=selected_plan)
    if "receivingReviews" in proof:
        if not isinstance(proof["receivingReviews"], list) or len(proof["receivingReviews"]) > MAX_REVIEWS:
            fail("Keep the complete bounded original receiving review history.")
        if not any(equal(row, proof["review"]) for row in proof["receivingReviews"]):
            fail("The selected original return is absent from its complete receiving review history.")
        validate_import(context, proof["receivingReviews"], events, proof["installations"], files,
                        plan_for_version=selected_plan, _depth=_depth + 1)
    elif any(row["preview"].get("returnReview") is not None for row in proof["installations"]):
        fail("The received Installation lost its original staged-review binding.")
    return proof


def normalized_review(supplied, returned, current):
    obj(supplied, ("returnedCaseId", "reviewId", "reviewSha256", "installationId",
                   "expectedRevision", "name", "note", "choices", "retainedReview"), "owner receiving review")
    case_id(supplied.get("returnedCaseId"))
    review_id(supplied.get("reviewId"))
    if supplied.get("reviewId") != returned["id"] or supplied.get("reviewSha256") != returned["sha256"]:
        fail("Keep the exact returned receiving review selection.", "INSTALLATION_RETURN_SELECTION", 409)
    if supplied.get("installationId") != current["id"] or supplied.get("expectedRevision") != current["revision"]:
        fail("The owner's Installation changed. Review its current edition.", "INSTALLATION_RETURN_CURRENT", 409)
    original = returned["installationReturn"]["document"]["checks"]
    wanted = {item["id"] for item in original}
    values, seen = supplied.get("choices"), set()
    if not isinstance(values, list) or len(values) != len(wanted):
        fail("Explicitly keep or apply every returned observation.")
    choices = {}
    for value in values:
        obj(value, ("id", "action", "note"), "owner check decision")
        if value.get("id") not in wanted or value["id"] in seen:
            fail("Keep each original returned check decision once.")
        seen.add(value["id"])
        choices[value["id"]] = {"id": value["id"],
            "action": domain.enum(value.get("action"), ("KEEP", "APPLY"), "Owner receiving choice"),
            "note": text(value.get("note"), "Owner decision reason", 8000, True)}
    return {"returnedCaseId": supplied["returnedCaseId"], "reviewId": returned["id"],
            "reviewSha256": returned["sha256"], "installationId": current["id"], "expectedRevision": current["revision"],
            "name": text(supplied.get("name"), "Owner review name", 300, True),
            "note": text(supplied.get("note"), "Owner receiving review scope", 12000, True),
            "choices": [choices[item["id"]] for item in original],
            **({"retainedReview": retained_review_pin(supplied["retainedReview"])} if supplied.get("retainedReview") is not None else {})}


def evaluate_review(context, current, proof, supplied):
    context, current = context_view(context), checked_installation(deepcopy(current))
    returned = validate_return(proof["review"])
    baseline = returned["installationReturn"]["baseline"]
    if current["id"] != baseline["id"]:
        fail("Return this report to its original Installation identity.", "INSTALLATION_RETURN_BASELINE", 409)
    inputs = normalized_review(supplied, returned, current)
    if inputs["returnedCaseId"] != proof["context"]["program"]["id"]:
        fail("Keep the selected imported receiving case.")
    value = returned["installationReturn"]
    original_basis = acceptance_basis(baseline["preview"]["snapshot"], baseline["preview"]["document"])
    current_basis = acceptance_basis(context, current["preview"]["document"])
    basis_changes = installations.differences(original_basis, current_basis)
    current_checks = {item["id"]: item for item in current["preview"]["document"]["checks"]}
    choices = {item["id"]: item for item in inputs["choices"]}
    owner_records = {kind: {item["id"]: item for item in rows} for kind, rows in context["records"].items()}
    returned_records = {kind: {item["id"]: item for item in rows} for kind, rows in value["snapshot"]["records"].items()}
    comparisons = []
    for observation in value["document"]["checks"]:
        ident, present = observation["id"], current_checks.get(observation["id"])
        definition_changes = installations.differences(
            {key: observation[key] for key in DEFINITION_KEYS},
            {key: present[key] for key in DEFINITION_KEYS} if present else None)
        eligible = not basis_changes and not value["receivingBasisChanges"] and not definition_changes
        links = {}
        for field, kind in (("workIds", "work"), ("purchaseIds", "purchases"), ("outcomeIds", "outcomes")):
            matched, evidence = [], []
            for key in observation[field]:
                (matched if equal(owner_records[kind].get(key), returned_records[kind][key]) else evidence).append(key)
            links[field] = {"sameOwnerRecordIds": matched, "retainedAsEvidenceIds": evidence}
        selected = choices[ident]
        if selected["action"] == "APPLY" and not eligible:
            fail("This criterion or its source/configuration changed. Keep the original result and obtain fresh receiving: " + ident,
                 "INSTALLATION_RETURN_FRESH_REVIEW", 409)
        comparisons.append({"id": ident, "title": observation["title"], "eligible": eligible,
            "definitionChanges": definition_changes, "ownerObservation": deepcopy(present),
            "returnedObservation": deepcopy(observation), "decision": selected, "recordLinks": links})
    result = {"schema": SCHEMA + ".owner-preview", "source": installations._source(context), "inputs": inputs,
              "baseline": deepcopy(baseline), "currentInstallation": current, "returnedProof": deepcopy(proof),
              "basisChanges": basis_changes, "receivingBasisChanges": deepcopy(value["receivingBasisChanges"]),
              "checks": comparisons, "newOwnerChecks": [deepcopy(item) for item in current_checks.values()
                  if item["id"] not in {row["id"] for row in value["document"]["checks"]}],
              "sources": [deepcopy(item) for _, item in sorted(proof["context"]["sources"].items())],
              "appliedChecks": sum(item["decision"]["action"] == "APPLY" for item in comparisons)}
    result["previewSha256"] = digest(result)
    return bounded(result)


def review_preview(ops, context, body):
    obj(body, ("expectedVersion", "inputs"), "owner return preview")
    installations._current(context, body.get("expectedVersion"))
    supplied = body.get("inputs")
    if not isinstance(supplied, dict):
        fail("Use the complete owner receiving choices.")
    current = installations.get(ops, context["program"]["id"], supplied.get("installationId"))
    proof, files, _ = proof_selection(ops, context, supplied)
    baseline = proof["review"]["installationReturn"]["baseline"]
    retained = installations.get(ops, context["program"]["id"], baseline["id"], baseline["revision"])
    if not equal(retained, baseline):
        fail("The receiving baseline is not the owner's retained original edition.", "INSTALLATION_RETURN_BASELINE", 409)
    return evaluate_review(context, current, proof, supplied)


def stage_document(candidate, mappings, receipt_id):
    document = deepcopy(candidate["currentInstallation"]["preview"]["document"])
    checks = {item["id"]: item for item in document["checks"]}
    mapped = {item["original"]["id"]: item["retained"]["id"] for item in mappings}
    for row in candidate["checks"]:
        if row["decision"]["action"] != "APPLY":
            continue
        observation = row["returnedObservation"]
        target = checks[row["id"]]
        for key in ("state", "operator", "observedAt", "note"):
            target[key] = observation[key]
        target["sourceIds"] = list(dict.fromkeys([mapped[key] for key in observation["sourceIds"]] + [receipt_id]))
        for key in ("workIds", "purchaseIds", "outcomeIds"):
            target[key] = deepcopy(row["recordLinks"][key]["sameOwnerRecordIds"])
    return document


def receipt_body(candidate, mappings):
    return {"schema": SCHEMA + ".owner-evidence", "previewSha256": candidate["previewSha256"],
            "source": candidate["source"], "inputs": candidate["inputs"], "returnedProof": candidate["returnedProof"],
            "checks": candidate["checks"], "sourceMappings": mappings}


def stage(ops, context, data, actor, version, note):
    obj(data, ("inputs", "expectedPreviewSha256"), "owner receiving stage")
    candidate = review_preview(ops, context, {"expectedVersion": context["program"]["version"], "inputs": data.get("inputs")})
    if candidate["previewSha256"] != domain.sha(data.get("expectedPreviewSha256"), "Reviewed return selection", False):
        fail("The owner or returned case changed. Preview the original selection again.", "INSTALLATION_RETURN_PREVIEW", 409)
    sources = context["sources"]
    proof, original_files, origin = proof_selection(ops, context, candidate["inputs"])
    if not equal(proof, candidate["returnedProof"]):
        fail("The selected complete return changed before staging.", "INSTALLATION_RETURN_SOURCE", 409)
    prior_mappings = {mapping["original"]["id"]: mapping for mapping in
                      origin["installationReturnReview"]["sourceMappings"]} if origin else {}
    mappings, added = [], []
    for metadata in candidate["sources"]:
        raw = original_files["sources/" + metadata["id"]]
        if len(raw) != metadata["bytes"] or hashlib.sha256(raw).hexdigest() != metadata["sha256"]:
            fail("The selected original receiving file changed.", "INSTALLATION_RETURN_SOURCE", 409)
        prior_mapping = prior_mappings.get(metadata["id"])
        existing = sources.get(prior_mapping["retained"]["id"] if prior_mapping else metadata["id"])
        if prior_mapping and not equal(existing, prior_mapping["retained"]):
            fail("The retained return mapping differs from its original owner review.", "INSTALLATION_RETURN_SOURCE", 409)
        if existing is not None and (prior_mapping is not None or equal(existing, metadata)):
            owner_metadata, owner_raw = ops.source(context["program"]["id"], existing["id"])
            if owner_raw != raw:
                fail("The original shared source identity has different bytes.")
            retained = owner_metadata
        else:
            # Equivalent bytes do not erase differing source URLs, times or provenance.
            retained = ops._source_add(context["program"]["id"], {
                **{key: metadata[key] for key in ("filename", "mediaType", "kind", "sourceUrl", "observedAt")},
                "contentBase64": base64.b64encode(raw).decode("ascii")})
            added.append(retained)
        mappings.append({"original": deepcopy(metadata), "retained": deepcopy(retained), "copied": retained["id"] != metadata["id"]})
    raw = (canonical(bounded(receipt_body(candidate, mappings))) + "\n").encode("utf-8")
    receipt = ops._source_add(context["program"]["id"], {"filename": "installation-return-" + candidate["inputs"]["reviewId"] + ".json",
        "mediaType": "application/json", "kind": "other", "sourceUrl": "",
        "observedAt": candidate["returnedProof"]["review"]["createdAt"], "contentBase64": base64.b64encode(raw).decode("ascii")})
    added.append(receipt)
    document = installations.normalized(ops._context(context["program"]["id"]), stage_document(candidate, mappings, receipt["id"]))
    value = {**candidate, "schema": SCHEMA + ".owner-stage", "sourceMappings": mappings,
             "receipt": receipt, "document": document}
    row = save_row(ops, context, STAGE_PURPOSE, value, actor, version, note)
    return {"before": None, "after": row_summary(row), "kind": "review", "recordId": row["id"],
            "reviewSha256": row["sha256"], "previewSha256": candidate["previewSha256"],
            "installationId": candidate["currentInstallation"]["id"],
            "expectedRevision": candidate["currentInstallation"]["revision"],
            "document": document, "sourceChange": {"added": added}, "unchanged": False}


def validate_stage(row, context, events, saved_installations, files, *, reviews=(), plan_for_version=None, _depth=0):
    validate_row_identity(row, STAGE_PURPOSE)
    value = row["installationReturnReview"]
    before = review_context(row)
    if plan_for_version is not None:
        import operations_amendments as amendments
        if amendments.plan_core(before["plan"]) != amendments.plan_core(plan_for_version(row["version"] - 1)):
            fail("The staged owner review differs from its original selected native plan.")
    origin = retained_review(reviews, value["inputs"]["retainedReview"], row["version"]) if value["inputs"].get("retainedReview") else None
    if origin and not equal(origin["installationReturnReview"]["returnedProof"], value["returnedProof"]):
        fail("The continued owner review changed its selected original returned proof.")
    prior_mappings = {mapping["original"]["id"]: mapping for mapping in
                      origin["installationReturnReview"]["sourceMappings"]} if origin else {}
    candidate = evaluate_review(before, value["currentInstallation"], value["returnedProof"], value["inputs"])
    expected_keys = set(candidate) | {"sourceMappings", "receipt", "document"}
    if set(value) != expected_keys or value.get("schema") != SCHEMA + ".owner-stage" or not equal(
            {**candidate, "schema": SCHEMA + ".owner-stage"}, {key: value[key] for key in candidate}):
        fail("The owner's staged return differs from its complete original preview.")
    if not equal(domain.report(**before), row["report"]):
        fail("The owner receiving business report changed.")
    available = {(item["id"], item["revision"], item["sha256"]): item for item in saved_installations}
    for item in (value["baseline"], value["currentInstallation"]):
        if not equal(available.get((item["id"], item["revision"], item["sha256"])), item) or item["version"] >= row["version"]:
            fail("The owner receiving review lost its exact earlier Installation.")
    mappings, originals = value["sourceMappings"], candidate["sources"]
    if not isinstance(mappings, list) or len(mappings) != len(originals):
        fail("The complete original receiving source mapping is required.")
    reconstructed, after_sources, added = {}, deepcopy(before["sources"]), []
    seen = set()
    for mapping, original in zip(mappings, originals):
        obj(mapping, ("original", "retained", "copied"), "receiving source mapping")
        retained = mapping["retained"]
        if not equal(mapping["original"], original) or retained["id"] in seen or not equal(context["sources"].get(retained["id"]), retained):
            fail("A complete receiving source mapping changed.")
        seen.add(retained["id"])
        if any(retained.get(key) != original.get(key) for key in ("filename", "mediaType", "kind", "sourceUrl", "observedAt", "bytes", "sha256")):
            fail("The owner must preserve each original file's complete meaning and bytes.")
        copied = retained["id"] != original["id"]
        if mapping.get("copied") is not copied:
            fail("The original source-copy observation changed.")
        if copied:
            if retained["id"] in before["sources"]:
                if not origin or not equal(prior_mappings.get(original["id"]), mapping) or not equal(before["sources"][retained["id"]], retained):
                    fail("A copied return source must retain its exact earlier owner mapping.")
            else:
                if origin:
                    fail("The continued owner review lost a file retained by its selected earlier review.")
                added.append(retained)
        elif not equal(before["sources"].get(original["id"]), original):
            fail("The reused original source was not present before staging.")
        after_sources[retained["id"]] = retained
        raw = files.get("sources/" + retained["id"])
        if not isinstance(raw, bytes) or len(raw) != original["bytes"] or hashlib.sha256(raw).hexdigest() != original["sha256"]:
            fail("A returned original file is missing from the owner's full case.")
        reconstructed["sources/" + original["id"]] = raw
    validate_proof(candidate["returnedProof"], reconstructed, _depth=_depth + 1)
    receipt = value["receipt"]
    if receipt["id"] in before["sources"] or receipt["id"] in seen or not equal(context["sources"].get(receipt["id"]), receipt):
        fail("The owner receiving receipt lost its distinct original identity.")
    raw = (canonical(receipt_body(candidate, mappings)) + "\n").encode("utf-8")
    if files.get("sources/" + receipt["id"]) != raw or receipt["bytes"] != len(raw) or receipt["sha256"] != hashlib.sha256(raw).hexdigest():
        fail("The full owner receiving receipt differs from the selected report and files.")
    after_sources[receipt["id"]] = receipt
    added.append(receipt)
    document = installations.normalized({**before, "sources": after_sources}, stage_document(candidate, mappings, receipt["id"]))
    if not equal(document, value["document"]):
        fail("The staged Installation document differs from the explicit owner choices.")
    states = installations._record_matches(events, context["records"])
    for rows in before["records"].values():
        for record in rows:
            if record["version"] >= row["version"] or digest(record) not in states.get((record["id"], record["version"]), set()):
                fail("The owner receiving selection lost its earlier original records.")
    event = events[row["version"] - 1]
    if (event.get("action") != "installation.return-stage" or event.get("recordId") != row["id"]
            or not equal(event.get("after"), row_summary(row)) or not equal(event.get("sourceChange"), {"added": added})
            or event.get("actor") != row["actor"] or event.get("note") != row["note"]):
        fail("The staged return does not match its original source and review event.")
    return row


def validate_import(context, reviews, events, saved_installations, files, *, plan_for_version=None, _depth=0):
    wanted, found = {"installation.return": set(), "installation.return-stage": set()}, set()
    for row in sorted(reviews, key=lambda item: item.get("version", 0)):
        if row.get("purpose") == PURPOSE:
            validate_return_in_case(row, context, events, saved_installations, files, plan_for_version=plan_for_version)
            wanted["installation.return"].add(row["id"])
        elif row.get("purpose") == STAGE_PURPOSE:
            validate_stage(row, context, events, saved_installations, files, reviews=reviews,
                           plan_for_version=plan_for_version, _depth=_depth)
            wanted["installation.return-stage"].add(row["id"])
        else:
            continue
        if row["id"] in found:
            fail("The complete case repeats a receiving review.")
        found.add(row["id"])
    for installation in saved_installations:
        candidate = installation["preview"]
        if candidate.get("returnReview") is not None:
            selected = retained_review(reviews, candidate["returnReview"], installation["version"])
            prior = next((item for item in saved_installations if item["id"] == installation["id"]
                          and item["revision"] == installation["revision"] - 1), None)
            require_stage_application(candidate["snapshot"], selected, prior, candidate["document"])
    for action, ids in wanted.items():
        if {event.get("recordId") for event in events if event.get("action") == action} != ids:
            fail("The complete case lost an original Installation receiving review.")



def stage_snapshot(row):
    value, before = row["installationReturnReview"], review_context(row)
    sources = {**before["sources"], **{item["retained"]["id"]: item["retained"] for item in value["sourceMappings"]},
               value["receipt"]["id"]: value["receipt"]}
    return installations.capture({**before, "sources": sources}, value["document"])


def selected_stage_basis(snapshot):
    import operations_amendments as amendments
    return {"mode": snapshot["program"]["mode"], "calendarStart": snapshot["program"].get("calendarStart"),
            "plan": amendments.plan_core(snapshot["plan"]), "records": snapshot["records"], "sources": snapshot["sources"]}


def stage_application_state(context, row, current):
    validate_row_identity(row, STAGE_PURPOSE)
    value, expected = row["installationReturnReview"], stage_snapshot(row)
    original = value["currentInstallation"]
    same_edition = current is not None and ref(current) == ref(original)
    installation_changes = installations.differences(original["preview"]["document"],
        current["preview"]["document"] if current else None)
    try:
        document = installations.normalized(context, value["document"])
        actual = installations.capture(context, document)
        selected_changes = installations.differences(selected_stage_basis(expected), selected_stage_basis(actual))
        document_changes = installations.differences(value["document"], document)
        unavailable = None
    except (Problem, KeyError) as exc:
        selected_changes, document_changes = [], []
        unavailable = str(exc)
    return {"schema": SCHEMA + ".stage-state", "returnReview": {"id": row["id"], "sha256": row["sha256"]},
            "source": installations._source(context), "stagedInstallation": ref(original),
            "currentInstallation": ref(current) if current else None, "sameInstallationEdition": same_edition,
            "installationChanges": installation_changes, "selectedBasisChanges": selected_changes,
            "documentChanges": document_changes, "unavailable": unavailable,
            "canSave": same_edition and not selected_changes and not document_changes and unavailable is None}


def require_stage_application(context, row, current, document):
    state = stage_application_state(context, row, current)
    if not equal(document, row["installationReturnReview"]["document"]):
        fail("The staged Installation document changed. Regenerate the owner review for the current selection.",
             "INSTALLATION_RETURN_STAGE_CHANGED", 409)
    if not state["canSave"]:
        fail("The staged Installation and current case differ. Compare the original owner review, then regenerate "
             "and review its current selection.", "INSTALLATION_RETURN_STAGE_CHANGED", 409)
    return {"id": row["id"], "sha256": row["sha256"]}


def verify_stage_application(ops, context, selection, current, document):
    pin = retained_review_pin(selection)
    row = ops.review(context["program"]["id"], pin["id"])
    row = retained_review([row], pin, context["program"]["version"] + 1)
    return require_stage_application(context, row, current, document)


def review_seed(ops, context, body):
    obj(body, ("expectedVersion", "retainedReview"), "retained owner review seed")
    installations._current(context, body.get("expectedVersion"))
    pin = retained_review_pin(body.get("retainedReview"))
    row = retained_review(case_review_rows(ops, context["program"]["id"]), pin)
    value = row["installationReturnReview"]
    retained_original_files(ops, context, row)
    current = installations.get(ops, context["program"]["id"], value["currentInstallation"]["id"])
    proof, returned = value["returnedProof"], value["returnedProof"]["review"]
    inputs = {**deepcopy(value["inputs"]), "retainedReview": pin, "expectedRevision": current["revision"],
              "choices": [{"id": choice["id"], "action": "KEEP", "note": choice["note"]} for choice in value["inputs"]["choices"]]}
    applications = [{"id": item["id"], "revision": item["revision"], "sha256": item["sha256"], "version": item["version"]}
        for item in installations.load(ops, context["program"]["id"])
        if equal(item["preview"].get("returnReview"), pin) and equal(item["preview"]["document"], value["document"])]
    return bounded({"schema": SCHEMA + ".owner-seed", "source": installations._source(context),
        "retainedReview": pin, "returned": deepcopy(returned), "inputs": inputs,
        "previousChoices": deepcopy(value["inputs"]["choices"]), "application": stage_application_state(context, row, current),
        "savedInstallations": applications})


def list_reviews(ops, context):
    result = []
    for raw in ops.db.execute("SELECT body_json FROM ops_reviews WHERE program_id=? ORDER BY rowid DESC",
                             (context["program"]["id"],)):
        row = json.loads(raw[0])
        if row.get("purpose") in (PURPOSE, STAGE_PURPOSE):
            result.append(row_summary(row))
    return {"schema": SCHEMA + ".reviews", "caseId": context["program"]["id"],
            "version": context["program"]["version"], "reviews": result}


def readable(row):
    receiving = row["purpose"] == PURPOSE
    value = row["installationReturn"] if receiving else row["installationReturnReview"]
    esc = lambda value: escape(str(value if value is not None else ""), quote=True)
    pretty = lambda value: esc(json.dumps(value, ensure_ascii=False, indent=2))
    checks = value["document"]["checks"] if receiving else value["checks"]
    body = "<h1>" + esc(value["inputs"]["name"]) + "</h1><p>Recorded by " + esc(row["actor"]) + " at " + esc(row["createdAt"]) + ".</p>"
    body += "<p>" + esc(row["note"]) + "</p><p>Original case purpose: <strong>" + esc(value["source"]["mode"]) + "</strong>.</p>"
    body += "<h2>Selected Installation</h2><pre>" + pretty(ref(value["baseline"])) + "</pre>"
    body += "<h2>" + ("Receiving observations" if receiving else "Explicit owner decisions") + "</h2>"
    for item in checks:
        body += "<section><h3>" + esc(item.get("title") or item["id"]) + "</h3><pre>" + pretty(item) + "</pre></section>"
    body += "<h2>Complete selected input</h2><pre>" + pretty(value["inputs"]) + "</pre>"
    body += "<h2>Source or configuration changes</h2><pre>" + pretty(value.get("basisChanges", value.get("receivingBasisChanges"))) + "</pre>"
    if not receiving:
        body += "<h2>Complete file mapping</h2><pre>" + pretty(value["sourceMappings"]) + "</pre>"
    body += "<h2>Receiving and reopening</h2><p>Import this entire Operations ZIP. It preserves the original planning history, "
    body += "Installation editions, work and purchase observations, named reviews and every original attached file. "
    body += "Choose Receiving returns in the original Operations application. An owner first reviews the imported return, "
    body += "then stages explicit choices and previews/saves a new Installation through the original controls. "
    body += "Changed criteria require fresh receiving. Named statements are recorded observations; they do not create "
    body += "an external acceptance, payment or new accounting record.</p>"
    body += "<p>Review " + esc(row["id"]) + " · SHA-256 " + esc(row["sha256"]) + "</p>"
    return ('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
            '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'">'
            '<title>' + esc(value["inputs"]["name"]) + '</title><style>'
            'body{max-width:1100px;margin:auto;padding:28px;color:#202020;background:white;font:15px/1.6 system-ui}'
            'h1{font-size:28px}h2{margin-top:32px;border-bottom:1px solid #bbb}section{border:1px solid #ccc;padding:16px;margin:12px 0}'
            'pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 ui-monospace,monospace}'
            '@media(max-width:640px){body{padding:16px}}</style><body>' + body + '</body></html>\n').encode("utf-8")


def selected_files(context, reviews, selected):
    ident = review_id(selected)
    row = next((item for item in reviews if item.get("id") == ident and item.get("purpose") in (PURPOSE, STAGE_PURPOSE)), None)
    if row is None:
        fail("Select the original Installation return.", "INSTALLATION_RETURN_NOT_FOUND", 404)
    raw = readable(row)
    marker = {"schema": SCHEMA + ".selection", "caseId": context["program"]["id"],
              "caseVersion": context["program"]["version"], "review": row_summary(row),
              "document": {"path": "installation-return.html", "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}}
    return {"installation-return-selection.json": (canonical(marker) + "\n").encode("utf-8"),
            "installation-return.html": raw}


def selection_from_files(document, files):
    names = {"installation-return-selection.json", "installation-return.html"}
    if not names.intersection(files):
        return None
    if not names.issubset(files):
        fail("The complete receiving return selection is missing.")
    try:
        marker = json.loads(files["installation-return-selection.json"])
        selected = marker["review"]["id"]
        row = next((item for item in document["reviews"] if item.get("id") == selected
                    and item.get("purpose") in (PURPOSE, STAGE_PURPOSE)), None)
        raw = files["installation-return.html"]
        expected = {"schema": SCHEMA + ".selection", "caseId": document["program"]["id"],
                    "caseVersion": document["program"]["version"], "review": row_summary(row) if row else None,
                    "document": {"path": "installation-return.html", "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}}
        if not row or not equal(marker, expected):
            fail("The selected complete receiving return differs from its retained original.")
        raw.decode("utf-8")
    except (TypeError, ValueError, KeyError, UnicodeError) as exc:
        if isinstance(exc, Problem):
            raise
        raise Problem("The complete receiving return selection is unreadable.", 422, "INVALID_INSTALLATION_RETURN") from exc
    return row_summary(row)

