    importedAt: new Date().toISOString(), ...input.binding,
    sourceBinding: 'RETAINED_CLIENT_FILES_AND_OPERATOR_ROUTE_SELECTION',
    reservation: 'ABSENT_NO_SF81_RECORD', outbox: 'NO_SF98_CAPTURE_OR_ENQUEUE',
