    if(!['--report','--outbox','--out'].includes(argv[i])||
      !argv[i+1]||Object.hasOwn(o,argv[i]))fail('USAGE: --report SF97_REPORT --outbox ORIGINAL_SF98_OUTBOX_DIR --out NEW_PRIVATE_DIR');
    o[argv[i]]=argv[i+1];
