    fail('PERFORMANCE_SERVICE_SOURCE_REQUIRED','Select a complete opening/closing service source for a service quantity basis.');
  if(result.optionId!==null&&!['NATIVE_SUCCESS','INBOX_ACCEPTED'].includes(result.basis))
