"""Receive a selected original Workshare into the native Customer Installation.

The commercial source remains an immutable Operations attachment. Installation
editions bind its original case, complete plan and phase identities; native
payment and receiving choices stay in the existing Installation document.
"""
from __future__ import annotations

from copy import deepcopy
from html import escape
import hashlib
import json

from model import Problem, canonical, digest
import operations_domain as domain
import operations_dispatch as dispatch
from workshare_intake import load_workshares

SCHEMA = "stellar-forge.sf47-workshare-installation.v1"
SOURCE_FIELDS = ("sourceId", "expectedSourceSha256", "packetSourceId", "expectedPacketSha256")
BINDING_FIELDS = ("schema", "sourceId", "sourceSha256", "packetSourceId", "packetSha256",
                  "caseId", "planSha256", "phaseChecks")


def fail(message, code="INVALID_WORKSHARE_INSTALLATION", status=422):
    raise Problem(message, status, code)


def exact(value, keys, label):
    if not isinstance(value, dict) or set(value) - set(keys):
        fail("Use the complete " + label + " object with its original field names.")
    return value


def original_id(value, label):
    if (not isinstance(value, str) or not value or len(value) > 500
            or any(ord(char) < 32 for char in value)):
        fail("Select the original " + label + ".")
    return value


def source_selection(context, raw):
    """Resolve existing immutable attachment identities without rewriting bytes."""
    result = {}
    for key, sha_key in (("sourceId", "expectedSourceSha256"),
                         ("packetSourceId", "expectedPacketSha256")):
        ident = raw.get(key)
        if ident is None and key == "packetSourceId":
            if raw.get(sha_key) is not None:
                fail("Select the original receiving packet with its SHA-256.")
            result[key], result[sha_key] = None, None
            continue
        domain.reference_list([ident], context["sources"], "Original Workshare source")
        metadata = context["sources"][ident]
        expected = domain.sha(raw.get(sha_key), "Original Workshare source", False)
        if metadata["sha256"] != expected:
            fail("The selected original Workshare attachment differs.", "WORKSHARE_SOURCE_CONFLICT", 409)
        result[key], result[sha_key] = ident, expected
    if result["sourceId"] == result["packetSourceId"]:
        fail("Select the complete commissioning document and its distinct receiving packet.")
    return result


def normalize_binding(context, raw):
    value = exact(deepcopy(raw), BINDING_FIELDS, "selected Workshare binding")
    if value.get("schema") != SCHEMA:
        fail("Use the native selected Workshare binding.")
    sources = source_selection(context, {
        "sourceId": value.get("sourceId"), "expectedSourceSha256": value.get("sourceSha256"),
        "packetSourceId": value.get("packetSourceId"), "expectedPacketSha256": value.get("packetSha256")})
    pairs = value.get("phaseChecks")
    if not isinstance(pairs, list) or not pairs or len(pairs) > 100:
        fail("Bind every original Workshare phase to its installation acceptance step.")
    case_id = original_id(value.get("caseId"), "Workshare case")
    phases, checks, normalized = set(), set(), []
    for row in pairs:
        exact(row, ("phaseId", "checkId"), "Workshare phase binding")
        phase, check = original_id(row.get("phaseId"), "phase"), original_id(row.get("checkId"), "acceptance step")
        if check != phase_check_id(case_id, phase):
            fail("Retain the native stable acceptance identity for each original phase.")
        if phase in phases or check in checks:
            fail("Keep each original Workshare phase and installation step once.")
        phases.add(phase); checks.add(check)
        normalized.append({"phaseId": phase, "checkId": check})
    return {"schema": SCHEMA, "sourceId": sources["sourceId"],
            "sourceSha256": sources["expectedSourceSha256"], "packetSourceId": sources["packetSourceId"],
            "packetSha256": sources["expectedPacketSha256"], "caseId": case_id,
            "planSha256": domain.sha(value.get("planSha256"), "Original Workshare plan", False),
            "phaseChecks": normalized}


def read_source(operations, context, selection, reader=None):
    selected = source_selection(context, selection)
    read = reader or (lambda ident: operations.source(context["program"]["id"], ident)[1])
    def original(ident):
        if ident is None:
            return None
        raw = read(ident)
        metadata = context["sources"][ident]
        if not isinstance(raw, bytes) or len(raw) != metadata["bytes"] or hashlib.sha256(raw).hexdigest() != metadata["sha256"]:
            fail("The complete original Workshare file differs from its retained attachment.")
        value = json.loads(raw.decode("utf-8"))
        if not isinstance(value, dict):
            fail("Use the complete original Workshare JSON object.")
        return value
    try:
        commissioning, packet = original(selected["sourceId"]), original(selected["packetSourceId"])
        workshares = load_workshares(commissioning, packet, require_proposed_usd=False)
        for workshare in workshares:
            commercial = workshare["plan"]["commercial"]
            original_id(commercial.get("currency"), "commercial currency")
            original_id(commercial.get("price_status"), "commercial price status")
        originals = {row["case_id"]: row for row in commissioning["cases"]}
        packets = {} if packet is None else {row["prepared_case"]["id"]: row for row in packet["packets"]}
        return {"selection": selected, "commissioning": commissioning, "packet": packet,
                "workshares": workshares, "originals": originals, "packets": packets}
    except Problem:
        raise
    except (KeyError, TypeError, ValueError, AttributeError, UnicodeError) as error:
        raise Problem("The original Workshare commissioning source is unreadable: " + str(error),
                      422, "INVALID_WORKSHARE_SOURCE") from error


def case_inventory(operations, context, body):
    exact(body, ("expectedVersion", *SOURCE_FIELDS), "Workshare source selection")
    from operations_installations import _current, _source
    _current(context, body.get("expectedVersion"))
    original = read_source(operations, context, body)
    return {"schema": SCHEMA, "source": _source(context), "selection": original["selection"],
            "cases": [{"caseId": row["caseId"], "title": row["plan"]["title"],
                       "customer": row["plan"]["customer"], "supplier": row["plan"]["supplier"],
                       "planSha256": row["planSha256"], "commercial": deepcopy(row["plan"]["commercial"]),
                       "hours": row["hours"], "phaseCount": row["phaseCount"], "packetPresent": row["packetPresent"]}
                      for row in original["workshares"]]}


def selected_case(original, case_id):
    row = next((row for row in original["workshares"] if row["caseId"] == case_id), None)
    if row is None:
        fail("Select an original case from this complete commissioning document.", "WORKSHARE_CASE_NOT_FOUND", 404)
    return row


def resolve_binding(operations, context, binding, reader=None):
    value = normalize_binding(context, binding)
    original = read_source(operations, context, {
        "sourceId": value["sourceId"], "expectedSourceSha256": value["sourceSha256"],
        "packetSourceId": value["packetSourceId"], "expectedPacketSha256": value["packetSha256"]}, reader)
    row = selected_case(original, value["caseId"])
    if row["planSha256"] != value["planSha256"]:
        fail("The installation selects a different original Workshare plan.", "WORKSHARE_PLAN_CONFLICT", 409)
    phases = {phase["id"]: phase for phase in row["plan"]["phases"]}
    if set(phases) != {item["phaseId"] for item in value["phaseChecks"]}:
        fail("Retain every selected original Workshare phase in the installation.")
    return {"binding": value, "workshare": row, "commissioningCase": deepcopy(original["originals"][value["caseId"]]),
            "receivingPacket": deepcopy(original["packets"].get(value["caseId"]))}


def verify_document(operations, context, document, reader=None):
    if "workshare" not in document:
        return None
    original = resolve_binding(operations, context, document["workshare"], reader)
    plan = original["workshare"]["plan"]
    phases = {phase["id"]: phase for phase in plan["phases"]}
    checks = {check["id"]: check for check in document["checks"]}
    for selected in document["workshare"]["phaseChecks"]:
        phase, check = phases[selected["phaseId"]], checks.get(selected["checkId"])
        if (check is None or check["title"] != phase["title"] or check["criterion"] != phase["acceptance"]
                or not check["required"] or document["workshare"]["sourceId"] not in check["sourceIds"]):
            fail("Preserve each original commercial phase criterion and its source; record acceptance in its native step.")
    if document["workorder"] != workorder_document(plan, document["workshare"]):
        fail("Keep the selected Workshare's original reference, payer, scope and commercial terms. "
             "Receive a changed original source to revise those fields.", "WORKSHARE_WORKORDER_CONFLICT", 409)
    return original


def verify_transition(operations, context, previous, document, reader=None, original=None):
    """Validate source refresh against the saved edition after each document is checked.

    Appended source references and reordered evidence links do not create a new
    acceptance observation. An explicitly changed operator, observation time,
    result or native work/purchase/outcome evidence remains a new observation.
    """
    if previous is None:
        return
    before = previous["preview"]["document"]
    old_binding, binding = before.get("workshare"), document.get("workshare")
    if old_binding is None:
        return
    if binding is None or old_binding["caseId"] != binding["caseId"]:
        fail("Keep this installation attached to its original commercial case; "
             "create a separate installation for another case.", "WORKSHARE_CASE_CONFLICT", 409)
    if old_binding == binding:
        return
    # Imported saved snapshots retain their original program IDs. Read the
    # immutable bytes through the current native case (or the received bundle),
    # while validating each edition against its own original source metadata.
    read = reader or (lambda ident: operations.source(context["program"]["id"], ident)[1])
    old_original = verify_document(operations, previous["preview"]["snapshot"], before, read)
    current_original = original or verify_document(operations, context, document, read)
    old_row, row = old_original["workshare"], current_original["workshare"]
    old_phases = {phase["id"]: phase for phase in old_row["plan"]["phases"]}
    old_checks = {check["id"]: check for check in before["checks"]}
    checks = {check["id"]: check for check in document["checks"]}

    def observation(check):
        return {**{key: check.get(key) for key in ("operator", "observedAt", "note")},
                **{key: sorted(check.get(key, []))
                   for key in ("workIds", "purchaseIds", "outcomeIds")}}

    for phase in row["plan"]["phases"]:
        phase_id = phase["id"]
        if phase_id not in old_phases:
            continue
        changed = (old_phases[phase_id] != phase
                   or old_row["effort"][phase_id] != row["effort"][phase_id])
        check_id = phase_check_id(binding["caseId"], phase_id)
        old_check, check = old_checks[check_id], checks[check_id]
        if changed and check["state"] == "ACCEPTED" and observation(check) == observation(old_check):
            fail("The original phase or effort changed: " + phase_id + ". Record a new acceptance "
                 "observation or keep this phase open; its prior acceptance remains in the saved edition.",
                 "WORKSHARE_ACCEPTANCE_CONFLICT", 409)


def phase_check_id(case_id, phase_id):
    return "workshare-" + hashlib.sha256((case_id + "\0" + phase_id).encode("utf-8")).hexdigest()[:32]


def terms_text(plan):
    commercial = plan["commercial"]
    lines = [str(commercial["currency"]) + " " + str(commercial["amount"]) + " · " + str(commercial["price_status"])]
    for milestone in commercial["milestones"]:
        lines.append(str(milestone["label"]) + ": " + str(commercial["currency"]) + " " +
                     str(milestone["amount"]) + " — " + str(milestone.get("trigger", "")))
    lines.append("Complete commercial terms, phase assignments, rights, dependencies and changes are retained in the attached original Workshare.")
    return "\n".join(lines)


def workorder_document(plan, binding):
    """Keep copied original commercial fields identical in seed, save and receive."""
    return {"sourceId": binding["sourceId"], "reference": binding["caseId"],
            "payer": plan["customer"], "scope": plan["outcome"], "terms": terms_text(plan)}


def seed(operations, context, body):
    """Prepare a complete editable native document; saving remains installation.save."""
    exact(body, ("expectedVersion", *SOURCE_FIELDS, "workshareCaseId",
                 "installationId", "expectedRevision", "document"), "Workshare installation selection")
    import operations_installations as installations
    installations._current(context, body.get("expectedVersion"))
    ident = body.get("installationId")
    number = installations.revision(body.get("expectedRevision", 0), True)
    previous = None
    if ident is not None:
        previous = installations.get(operations, context["program"]["id"], ident)
        if previous["revision"] != number:
            fail("Reopen the installation's current edition before receiving this source.", "INSTALLATION_CONFLICT", 409)
    elif number != 0:
        fail("Use edition zero for a new installation.")
    original = read_source(operations, context, body)
    row = selected_case(original, original_id(body.get("workshareCaseId"), "Workshare case"))
    plan = row["plan"]
    if body.get("document") is not None:
        document = installations.normalized(context, body["document"])
    elif previous:
        document = deepcopy(previous["preview"]["document"])
    else:
        document = installations.seed(context)
    old_binding = document.get("workshare")
    old_original = verify_document(operations, context, document) if old_binding else None
    if old_binding and old_binding["caseId"] != row["caseId"]:
        fail("Create a separate installation for a different original commercial case.", "WORKSHARE_CASE_CONFLICT", 409)
    old_checks = {item["id"]: item for item in document["checks"]}
    old_phases = {} if not old_original else {phase["id"]: phase for phase in old_original["workshare"]["plan"]["phases"]}
    old_effort = {} if not old_original else old_original["workshare"]["effort"]
    removed = set() if not old_binding else {item["checkId"] for item in old_binding["phaseChecks"]}
    document["checks"] = [item for item in document["checks"] if item["id"] not in removed]
    bindings, reset = [], []
    for phase in plan["phases"]:
        check_id = phase_check_id(row["caseId"], phase["id"])
        if any(item["id"] == check_id for item in document["checks"]):
            fail("The original phase identity collides with another installation check.")
        same_phase = old_phases.get(phase["id"]) == phase and old_effort.get(phase["id"]) == row["effort"][phase["id"]]
        existing = old_checks.get(check_id) if same_phase else None
        check = deepcopy(existing) if existing else {"id": check_id, "title": phase["title"],
            "criterion": phase["acceptance"], "tranche": None, "required": True, "state": "OPEN",
            "operator": "", "observedAt": None, "note": "", "sourceIds": [],
            "workIds": [], "purchaseIds": [], "outcomeIds": []}
        check["sourceIds"] = list(dict.fromkeys([*check["sourceIds"], original["selection"]["sourceId"]]))
        if not existing:
            check["note"] = "Original assigned phase owner: " + str(phase["owner"]) + ". Planned effort: " + \
                row["effort"][phase["id"]] + " hours. Dependencies: " + ", ".join(phase["depends_on"])
            if check_id in old_checks:
                reset.append(phase["id"])
        document["checks"].append(check)
        bindings.append({"phaseId": phase["id"], "checkId": check_id})
    selected = original["selection"]
    document["workshare"] = {"schema": SCHEMA, "sourceId": selected["sourceId"],
        "sourceSha256": selected["expectedSourceSha256"], "packetSourceId": selected["packetSourceId"],
        "packetSha256": selected["expectedPacketSha256"], "caseId": row["caseId"],
        "planSha256": row["planSha256"], "phaseChecks": bindings}
    # A source refresh updates original commercial fields and preserves actual
    # deployment, native payment, receiving and independent acceptance selections.
    document["name"] = plan["title"]
    document["workorder"] = workorder_document(plan, document["workshare"])
    for field in ("name", "purpose", "request", "completeOutput"):
        plan_key = "title" if field == "name" else "outcome"
        previous_value = old_original["workshare"]["plan"][plan_key] if old_original else ""
        if not document["task"][field] or document["task"][field] == previous_value:
            document["task"][field] = plan[plan_key]
    document["assignments"]["commercialRef"] = row["caseId"] + " · plan " + row["planSha256"]
    linked = [selected["sourceId"]] + ([selected["packetSourceId"]] if selected["packetSourceId"] else [])
    document["source"]["sourceIds"] = list(dict.fromkeys([*document["source"]["sourceIds"], *linked]))
    document["payment"]["termsSourceIds"] = list(dict.fromkeys([*document["payment"]["termsSourceIds"], *linked]))
    old_reference = ("Original Workshare " + old_binding["caseId"] + " · plan " + old_binding["planSha256"]) if old_binding else ""
    if not document["source"]["reference"] or document["source"]["reference"] == old_reference:
        document["source"]["reference"] = "Original Workshare " + row["caseId"] + " · plan " + row["planSha256"]
    if not document["source"]["authority"] or (old_original and document["source"]["authority"] == old_original["workshare"]["plan"].get("rights", "")):
        document["source"]["authority"] = str(plan.get("rights", ""))
    if not document["source"]["changePolicy"] or (old_original and document["source"]["changePolicy"] == old_original["workshare"]["plan"].get("change_process", "")):
        document["source"]["changePolicy"] = str(plan.get("change_process", ""))
    dispatch.reconcile_checks(document)
    document = installations.normalized(context, document)
    verify_document(operations, context, document)
    return {"schema": SCHEMA, "source": installations._source(context), "installationId": ident,
            "expectedRevision": number, "document": document,
            "workshare": {"caseId": row["caseId"], "planSha256": row["planSha256"],
                          "commercial": deepcopy(plan["commercial"]), "hours": row["hours"],
                          "phaseCount": len(plan["phases"]), "resetPhaseIds": reset},
            "sourceChanges": installations.differences(previous["preview"]["document"], document) if previous else []}


def html_section(original):
    if original is None:
        return ""
    row, binding = original["workshare"], original["binding"]
    plan, commercial = row["plan"], row["plan"]["commercial"]
    e = lambda value: escape(str(value), quote=True)
    html = "<h2>Original commercial Workshare</h2><p>" + e(plan["title"]) + " · " + e(plan["customer"]) + \
        " / " + e(plan["supplier"]) + "</p><p>" + e(commercial["currency"]) + " " + e(commercial["amount"]) + \
        " · " + e(commercial["price_status"]) + " · " + e(row["hours"]) + " planned hours</p>"
    html += "<p>Original case " + e(binding["caseId"]) + " · plan SHA-256 " + e(binding["planSha256"]) + "</p>"
    html += "<table><thead><tr><th>Phase / owner</th><th>Effort / dependencies</th><th>Complete assignment and acceptance</th></tr></thead><tbody>"
    for phase in plan["phases"]:
        html += "<tr><td>" + e(phase["title"]) + "<br>" + e(phase["owner"]) + "</td><td>" + \
            e(row["effort"][phase["id"]]) + " hours<br>" + e(", ".join(phase["depends_on"])) + \
            "</td><td>" + e(phase["description"]) + "<br><strong>Acceptance:</strong> " + e(phase["acceptance"]) + "</td></tr>"
    html += "</tbody></table><details><summary>Complete original commissioning case and commercial terms</summary><pre>" + \
        e(json.dumps(original["commissioningCase"], ensure_ascii=False, indent=2)) + "</pre></details>"
    if original["receivingPacket"] is not None:
        html += "<details><summary>Complete original receiving packet</summary><pre>" + \
            e(json.dumps(original["receivingPacket"], ensure_ascii=False, indent=2)) + "</pre></details>"
    return html

"""Join complete original recurring customer work to saved Installation editions."""
from __future__ import annotations

from copy import deepcopy
from html import escape
import hashlib

from model import Problem, digest
import operations_domain as domain
from operations_workflow_source import read_bundle, period_summary, identity

SCHEMA = "stellar-forge.sf47-workflow-installation.v1"
SOURCE_FIELDS = ("sourceId", "expectedSourceSha256")
PERIOD_FIELDS = ("cycleId", "checkId", "seriesId", "seriesRevision", "runId", "period",
                 "recordedState", "runRevision", "completedAt", "deliveryIds", "customerFiles",
                 "customerBytes", "completedSteps", "stepCount", "recoveredSteps", "basisSha256")


def fail(message, code="INVALID_WORKFLOW_INSTALLATION", status=422):
    raise Problem(message, status, code)


def exact(value, fields, label):
    if not isinstance(value, dict) or set(value) - set(fields):
        fail("Use the original " + label + " fields.")
    return value


def source_selection(context, value):
    ident = value.get("sourceId")
    domain.reference_list([ident], context["sources"], "Original recurring-work source")
    expected = domain.sha(value.get("expectedSourceSha256"), "Original recurring-work source", False)
    if context["sources"][ident]["sha256"] != expected:
        fail("The selected complete recurring-work source changed.", "WORKFLOW_SOURCE_CONFLICT", 409)
    return {"sourceId": ident, "expectedSourceSha256": expected}


def read_source(operations, context, selection, reader=None):
    selected = source_selection(context, selection)
    read = reader or (lambda ident: operations.source(context["program"]["id"], ident)[1])
    raw = read(selected["sourceId"])
    metadata = context["sources"][selected["sourceId"]]
    if (not isinstance(raw, bytes) or len(raw) != metadata["bytes"]
            or hashlib.sha256(raw).hexdigest() != metadata["sha256"]):
        fail("Receive every original byte of the selected customer operating source.")
    return {"selection": selected, **read_bundle(raw)}


def check_id(profile_id, cycle_id):
    return "period-" + hashlib.sha256((profile_id + "\0" + cycle_id).encode()).hexdigest()[:32]


def binding_period(profile_id, original):
    value = period_summary(original)
    result = {key: deepcopy(value[key]) for key in ("cycleId", "seriesId", "seriesRevision", "runId",
              "period", "runRevision", "completedAt", "deliveryIds", "customerFiles", "customerBytes",
              "completedSteps", "stepCount", "recoveredSteps", "basisSha256")}
    result.update({"checkId": check_id(profile_id, value["cycleId"]), "recordedState": value["state"]})
    return result


def normalize_binding(context, value):
    exact(value, ("schema", "sourceId", "sourceSha256", "profileId", "periods"), "recurring-work binding")
    if value.get("schema") != SCHEMA:
        fail("Select the original native recurring-work binding.")
    selected = source_selection(context, {"sourceId": value.get("sourceId"),
                                         "expectedSourceSha256": value.get("sourceSha256")})
    profile_id = identity(value.get("profileId"), "profile")
    periods = value.get("periods")
    if not isinstance(periods, list) or not 1 <= len(periods) <= 100:
        fail("Retain each selected complete customer period.")
    seen, normalized = set(), []
    for row in periods:
        if not isinstance(row, dict) or set(row) != set(PERIOD_FIELDS):
            fail("Keep the complete original recorded period selection.")
        cycle_id = identity(row["cycleId"], "cycle")
        identity(row["seriesId"], "series"); identity(row["runId"], "run")
        if cycle_id in seen or row["checkId"] != check_id(profile_id, cycle_id):
            fail("Keep each recurring acceptance step attached to its original cycle once.")
        seen.add(cycle_id)
        domain.sha(row["basisSha256"], "Selected original period", False)
        for key in ("seriesRevision",):
            domain.integer(row[key], "Original series edition", 1, 10000000)
        if row["runRevision"] is not None:
            domain.integer(row["runRevision"], "Original native run revision", 1, 10000000)
        for key in ("customerFiles", "customerBytes", "completedSteps", "stepCount", "recoveredSteps"):
            domain.integer(row[key], "Original " + key, 0, 2147483647)
        exact(row["period"], ("start", "end"), "period dates")
        for key in ("start", "end"):
            domain.calendar(row["period"].get(key), "Original period " + key)
        if row["period"]["start"] > row["period"]["end"]:
            fail("Retain the original customer period order.")
        if not isinstance(row["recordedState"], str) or not row["recordedState"]:
            fail("Retain the recorded native run state.")
        if row["completedAt"] is not None:
            domain.timestamp(row["completedAt"], "Original run completion time")
        ids = row["deliveryIds"]
        if not isinstance(ids, list) or len(ids) > 1000 or len(set(ids)) != len(ids):
            fail("Keep the explicitly selected original customer delivery identities.")
        for ident in ids:
            identity(ident, "customer delivery")
        normalized.append(deepcopy(row))
    return {"schema": SCHEMA, "sourceId": selected["sourceId"],
            "sourceSha256": selected["expectedSourceSha256"], "profileId": profile_id, "periods": normalized}


def title_and_criterion(original):
    cycle, series = original["cycle"], original["series"]
    request = cycle["request"]
    title = str(series["name"]) + " · " + str(request["label"])
    criterion = ("Review the complete original customer task for cycle " + cycle["id"] +
        ", period " + request["period"]["start"] + " to " + request["period"]["end"] +
        ", native run " + cycle["runId"] + ". Confirm its useful result in the receiving application. " +
        ("Review every complete file in the explicitly selected customer deliveries." if original["customers"] else
         "Review the complete original native results; this period selects no separate customer file delivery."))
    return title, criterion


def verify_document(operations, context, document, reader=None):
    if "workflowPeriods" not in document:
        return None
    binding = normalize_binding(context, document["workflowPeriods"])
    original = read_source(operations, context, {"sourceId": binding["sourceId"],
                           "expectedSourceSha256": binding["sourceSha256"]}, reader)
    if original["manifest"]["profileId"] != binding["profileId"]:
        fail("Keep this Installation attached to the selected original customer profile.", "WORKFLOW_PROFILE_CONFLICT", 409)
    available = {value["cycle"]["id"]: value for value in original["periods"]}
    checks = {row["id"]: row for row in document["checks"]}
    selected = []
    for row in binding["periods"]:
        value = available.get(row["cycleId"])
        if value is None or binding_period(binding["profileId"], value) != row:
            fail("The saved period differs from its complete original source and selection.", "WORKFLOW_PERIOD_CONFLICT", 409)
        check = checks.get(row["checkId"])
        title, criterion = title_and_criterion(value)
        if (check is None or check["title"] != title or check["criterion"] != criterion
                or check["required"] is not True or binding["sourceId"] not in check["sourceIds"]):
            fail("Keep the native recurring acceptance step, full criterion and original source.")
        if check["state"] == "ACCEPTED" and row["recordedState"] != "COMPLETE":
            fail("Retain this period's native completion before recording its complete-result acceptance. "
                 "The current run and correction stay visible in the source.", "WORKFLOW_RESULT_INCOMPLETE", 409)
        selected.append(value)
    return {**original, "binding": binding, "selectedPeriods": selected}


def verify_transition(operations, context, previous, document, reader=None, original=None):
    if previous is None:
        return
    before = previous["preview"]["document"]
    old = before.get("workflowPeriods")
    if old is None:
        return
    binding = document.get("workflowPeriods")
    if binding is None or binding["profileId"] != old["profileId"]:
        fail("Keep this Installation attached to its original customer profile; use a separate Installation "
             "for another customer.", "WORKFLOW_PROFILE_CONFLICT", 409)
    old_periods = {row["cycleId"]: row for row in old["periods"]}
    periods = {row["cycleId"]: row for row in binding["periods"]}
    if not old_periods.keys() <= periods.keys():
        fail("Retain earlier selected customer periods when appending a later operating edition.",
             "WORKFLOW_PERIOD_HISTORY", 409)
    old_checks = {row["id"]: row for row in before["checks"]}
    checks = {row["id"]: row for row in document["checks"]}
    for key, row in periods.items():
        earlier = old_periods.get(key)
        if earlier is None or earlier["basisSha256"] == row["basisSha256"]:
            continue
        old_check, check = old_checks[earlier["checkId"]], checks[row["checkId"]]
        observed = lambda value: {**{field: value[field] for field in ("operator", "observedAt", "note")},
                                  **{field: sorted(value[field]) for field in ("workIds", "purchaseIds", "outcomeIds")}}
        if check["state"] == "ACCEPTED" and observed(check) == observed(old_check):
            fail("This original period, native run or selected customer delivery changed. Record the new "
                 "useful-result observation; its earlier acceptance remains in the preceding edition.",
                 "WORKFLOW_ACCEPTANCE_CONFLICT", 409)


def inventory(operations, context, body):
    exact(body, ("expectedVersion", *SOURCE_FIELDS), "recurring-work source selection")
    from operations_installations import _current, _source
    _current(context, body.get("expectedVersion"))
    original = read_source(operations, context, body)
    return {"schema": SCHEMA, "source": _source(context), "selection": original["selection"],
            "profile": {"id": original["manifest"]["profileId"], "name": original["profile"]["profile"]["name"],
                        "sourceWorkspaceId": original["manifest"]["sourceWorkspaceId"]},
            "periods": [period_summary(value) for value in original["periods"]],
            "sourceFiles": original["manifest"]["files"],
            "otherDeliveries": deepcopy(original["handover"].get("otherDeliveries", []))}


def seed(operations, context, body):
    exact(body, ("expectedVersion", *SOURCE_FIELDS, "cycleIds", "installationId",
                 "expectedRevision", "document"), "customer-period receiving selection")
    import operations_installations as installations
    installations._current(context, body.get("expectedVersion"))
    ident = body.get("installationId")
    number = installations.revision(body.get("expectedRevision", 0), True)
    previous = None
    if ident is not None:
        previous = installations.get(operations, context["program"]["id"], ident)
        if previous["revision"] != number:
            fail("Reopen the current Installation edition before receiving this period.", "INSTALLATION_CONFLICT", 409)
    elif number != 0:
        fail("Use edition zero when preparing a new Installation.")
    original = read_source(operations, context, body)
    profile_id = original["manifest"]["profileId"]
    wanted = body.get("cycleIds")
    if not isinstance(wanted, list) or not wanted or len(wanted) > 100 or len(set(wanted)) != len(wanted):
        fail("Select each complete original customer period once.")
    for key in wanted:
        identity(key, "cycle")
    if body.get("document") is not None:
        document = installations.normalized(context, body["document"])
    elif previous:
        document = deepcopy(previous["preview"]["document"])
    else:
        document = installations.seed(context)
    old = document.get("workflowPeriods")
    saved_document = previous["preview"]["document"] if previous else None
    saved_binding = saved_document.get("workflowPeriods") if saved_document else None
    if any(value and value["profileId"] != profile_id for value in (old, saved_binding)):
        fail("Create a separate Installation for another original customer profile.", "WORKFLOW_PROFILE_CONFLICT", 409)
    if old:
        verify_document(operations, context, document)
    current_periods = {value["cycle"]["id"]: value for value in original["periods"]}
    # A historical edition may be the editable draft. Carry periods which were
    # subsequently saved in the current edition, without replacing the chosen
    # draft's observations for its own periods.
    saved_periods = {} if saved_binding is None else {row["cycleId"]: row for row in saved_binding["periods"]}
    draft_periods = {} if old is None else {row["cycleId"]: row for row in old["periods"]}
    old_periods = {**saved_periods, **draft_periods}
    selected_ids = list(dict.fromkeys([*old_periods, *wanted]))
    if not set(selected_ids) <= current_periods.keys():
        fail("Capture the complete earlier and new periods together before refreshing this Installation.",
             "WORKFLOW_PERIOD_HISTORY", 409)
    old_checks = {row["id"]: row for row in document["checks"]}
    for row in saved_periods.values():
        if row["cycleId"] not in draft_periods:
            saved_check = next(value for value in saved_document["checks"] if value["id"] == row["checkId"])
            if row["checkId"] in old_checks:
                fail("The carried original period acceptance identity collides with another draft check.")
            old_checks[row["checkId"]] = saved_check
    removed = {row["checkId"] for row in old_periods.values()}
    document["checks"] = [row for row in document["checks"] if row["id"] not in removed]
    bound, reset = [], []
    for key in selected_ids:
        value = current_periods[key]
        selected = binding_period(profile_id, value)
        check_key = selected["checkId"]
        if any(row["id"] == check_key for row in document["checks"]):
            fail("The original period acceptance identity collides with another Installation check.")
        existing = old_checks.get(check_key)
        unchanged = old_periods.get(key, {}).get("basisSha256") == selected["basisSha256"]
        if existing is not None and unchanged:
            check = deepcopy(existing)
        else:
            title, criterion = title_and_criterion(value)
            check = {"id": check_key, "title": title, "criterion": criterion, "tranche": None,
                     "required": True, "state": "OPEN", "operator": "", "observedAt": None, "note": "",
                     "sourceIds": [], "workIds": [], "purchaseIds": [], "outcomeIds": []}
            if existing is not None:
                reset.append(key)
        check["sourceIds"] = list(dict.fromkeys([*check["sourceIds"], original["selection"]["sourceId"]]))
        document["checks"].append(check); bound.append(selected)
    document["workflowPeriods"] = {"schema": SCHEMA, "sourceId": original["selection"]["sourceId"],
        "sourceSha256": original["selection"]["expectedSourceSha256"], "profileId": profile_id, "periods": bound}
    if not old and not document.get("workshare"):
        first = current_periods[selected_ids[0]]
        if document["name"] == "Customer installation":
            document["name"] = str(original["profile"]["profile"]["name"]) + " · recurring work"
        if not document["task"]["name"]:
            document["task"]["name"] = str(first["series"]["name"])
        if not document["task"]["request"]:
            document["task"]["request"] = "Complete original requests are retained in the attached Console profile, selected cycles and native reports."
        if not document["task"]["completeOutput"]:
            document["task"]["completeOutput"] = "The original native task has completed and its useful result is reviewed in the receiving application with the selected complete customer files."
        if not document["task"]["repeatTrigger"]:
            document["task"]["repeatTrigger"] = "The next explicitly selected original customer period or changed source edition."
    document["source"]["sourceIds"] = list(dict.fromkeys([*document["source"]["sourceIds"], original["selection"]["sourceId"]]))
    document["receiving"]["sourceIds"] = list(dict.fromkeys([*document["receiving"]["sourceIds"], original["selection"]["sourceId"]]))
    document = installations.normalized(context, document)
    verify_document(operations, context, document)
    return {"schema": SCHEMA, "source": installations._source(context),
            "installationId": ident, "expectedRevision": number, "document": document,
            "workflow": {"profileId": profile_id, "periods": [period_summary(current_periods[key]) for key in selected_ids],
                         "resetCycleIds": reset},
            "sourceChanges": installations.differences(previous["preview"]["document"], document) if previous else []}


def report(document):
    binding = document.get("workflowPeriods")
    if binding is None:
        return None
    checks = {value["id"]: value for value in document["checks"]}
    periods = [{**deepcopy(value), "acceptanceState": checks[value["checkId"]]["state"],
                "observingOperator": checks[value["checkId"]]["operator"],
                "observedAt": checks[value["checkId"]]["observedAt"]}
               for value in binding["periods"]]
    return {"profileId": binding["profileId"], "sourceId": binding["sourceId"],
            "sourceSha256": binding["sourceSha256"], "periods": periods,
            "recordedCompletePeriods": sum(row["recordedState"] == "COMPLETE" for row in periods),
            "acceptedPeriods": sum(row["acceptanceState"] == "ACCEPTED" for row in periods),
            "distinctSelectedDeliveries": len({key for row in periods for key in row["deliveryIds"]})}


def html_section(document):
    value = report(document)
    if value is None:
        return ""
    e = lambda value: escape(str(value if value is not None else "Unentered"), quote=True)
    rows = []
    for row in value["periods"]:
        rows.append("<tr><td>" + e(row["period"]["start"]) + " to " + e(row["period"]["end"]) +
                    "<br>" + e(row["cycleId"]) + "</td><td>" + e(row["runId"]) + "<br>" +
                    e(row["recordedState"]) + " · " + str(row["completedSteps"]) + " / " + str(row["stepCount"]) +
                    "</td><td>" + str(row["customerFiles"]) + " complete selected files<br>" +
                    str(row["customerBytes"]) + " bytes</td><td>" + e(row["acceptanceState"]) +
                    "<br>" + e(row["observingOperator"]) + "<br>" + e(row["observedAt"]) + "</td></tr>")
    return ("<h2>Original customer operating periods</h2><p>Profile " + e(value["profileId"]) +
            ". Each period retains its original run and explicit file selection; the receiving operator's "
            "acceptance belongs to this saved Installation edition.</p><div class=\"table\"><table><thead><tr>"
            "<th>Customer period</th><th>Recorded native run</th><th>Selected customer files</th>"
            "<th>Actual receiving acceptance</th></tr></thead><tbody>" + "".join(rows) +
            "</tbody></table></div><p><a download href=\"sources/" + e(value["sourceId"]) +
            "\">Download the complete original profile, reports and customer files</a></p>")

"""Resource allocation over an immutable original SF47 operating forecast.

The source forecast owns scope, costs, collections and observed records.
This module owns explicitly entered availability, resource effort, dependencies,
priorities and date alternatives. Chosen dates return through forecast.preview.
"""
from __future__ import annotations

from copy import deepcopy
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation
from html import escape
import hashlib
import io
import json
import re
import zipfile

from model import canonical, csv_bytes, digest, text, short_id, Problem
import operations_domain as domain
import forecast as forecasts
import portfolio_schedule as allocation
import portfolio_installations as installation_plans

SCHEMA = "stellar-forge.sf47-portfolio.v1"
ENGINE_VERSION = 1
MAX_PORTFOLIOS = 40
MAX_ALTERNATIVES = 23
MAX_RESOURCES = 100
MAX_DAYS = forecasts.MAX_DAYS
ZERO = Decimal(0)
BASE_FIELDS = {"calendar", "resources", "tasks"}
FIELDS = BASE_FIELDS | {installation_plans.FIELD}


def fail(message, code="INVALID_PORTFOLIO", status=422):
    raise Problem(message, status, code)


def obj(raw, allowed, label):
    if not isinstance(raw, dict) or set(raw) - set(allowed):
        fail(label + ": use the declared object fields.")
    return raw


def array(raw, label, maximum):
    if not isinstance(raw, list) or len(raw) > maximum:
        fail(label + ": use an array of at most " + str(maximum) + " rows.")
    return raw


def number(raw, label, *, nullable=False):
    if raw is None or raw == "":
        if nullable:
            return None
        fail(label + ": enter a number.")
    if isinstance(raw, bool) or not isinstance(raw, (str, int, float)):
        fail(label + ": enter a finite number.")
    try:
        value = Decimal(str(raw))
    except InvalidOperation:
        fail(label + ": enter a finite number.")
    if not value.is_finite() or value < 0 or value > Decimal("1000000000") or value.as_tuple().exponent < -8:
        fail(label + ": use 0 to 1,000,000,000 with at most eight decimal places.")
    answer = format(value, "f")
    return answer.rstrip("0").rstrip(".") if "." in answer else answer


def integer(raw, label, maximum=MAX_DAYS):
    if isinstance(raw, bool) or not isinstance(raw, int) or not 0 <= raw <= maximum:
        fail(label + ": enter a whole number from 0 to " + str(maximum) + ".")
    return raw


def iso(raw, label, *, nullable=False):
    if raw in (None, "") and nullable:
        return None
    if not isinstance(raw, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
        fail(label + ": use YYYY-MM-DD.")
    try:
        date.fromisoformat(raw)
    except ValueError:
        fail(label + ": use a valid calendar date.")
    return raw


def dates(raw, label):
    values = [iso(x, label) for x in array(raw, label, MAX_DAYS)]
    if len(set(values)) != len(values):
        fail(label + ": do not repeat dates.")
    return sorted(values)


def unique(values, key, label):
    result = {}
    for row in values:
        if row[key] in result:
            fail(label + ": repeated identity " + str(row[key]) + ".")
        result[row[key]] = row
    return result


def source_tasks(saved):
    result = []
    for row in saved["report"]["packages"]:
        result.append({"id": "package/" + row["id"], "sourceKind": "package", "sourceId": row["id"],
            "title": row["id"], "remainingHours": row["remainingHours"],
            "startDate": row["startDate"], "endDate": row["endDate"], "tranche": row["tranche"],
            "remainingCostUsd": row["remainingCostUsd"], "scope": row.get("scope", ""),
            "sourceIds": []})
    for row in saved["report"]["commercial"]:
        if row["selected"]:
            result.append({"id": "commercial/" + row["id"], "sourceKind": "commercial", "sourceId": row["id"],
                "title": row["title"], "remainingHours": row["remainingHours"],
                "startDate": row["startDate"], "endDate": row["endDate"], "tranche": None,
                "remainingCostUsd": row["remainingUninvoicedCostUsd"], "scope": row["scope"],
                "sourceIds": row["sourceIds"], "caseRef": row["caseRef"], "sourceUrl": row["sourceUrl"],
                "stage": row["stage"],
                **({"timing": deepcopy(row["timing"])} if "timing" in row else {}),
                **({"nativePricing": deepcopy(row["nativePricing"]),
                    "nativeReceipts": deepcopy(row["receipts"]),
                    "currencyValuation": deepcopy(row["currencyValuation"])}
                   if "nativePricing" in row else {})})
    return result


def base_reference(saved):
    return {key: deepcopy(saved[key]) for key in ("id", "sha256", "previewSha256", "source")}


def check_source(context, saved):
    clean = {key: value for key, value in saved.items() if key != "current"}
    forecasts.validate_saved(clean, context["plan"])
    if forecasts.source_identity(context)["factsSha256"] != clean["source"]["factsSha256"]:
        fail("The case facts have changed since this forecast. Save an updated original forecast before allocating its work.",
             "PORTFOLIO_FORECAST_SOURCE_CHANGED", 409)
    return clean


def normalize_calendar(raw, saved):
    raw = obj(raw, {"startDate", "horizonDays", "weekdays", "holidays", "extraWorkingDates"}, "Calendar")
    start = iso(raw.get("startDate"), "Calendar start")
    horizon = integer(raw.get("horizonDays", 730), "Calendar horizon")
    if horizon < 1:
        fail("The calendar needs at least one date.")
    first = date.fromisoformat(saved["inputs"]["asOfDate"]) + timedelta(days=1)
    if date.fromisoformat(start) < first or date.fromisoformat(start) + timedelta(days=horizon) > first + timedelta(days=MAX_DAYS):
        fail("The allocation calendar must fit the original future forecast horizon.")
    weekdays = array(raw.get("weekdays"), "Open weekdays", 7)
    if any(isinstance(x, bool) or not isinstance(x, int) or not 0 <= x <= 6 for x in weekdays) or len(set(weekdays)) != len(weekdays):
        fail("Open weekdays use unique numbers 0 (Monday) through 6 (Sunday).")
    holidays = dates(raw.get("holidays", []), "Calendar holidays")
    extra = dates(raw.get("extraWorkingDates", []), "Extra working dates")
    if set(holidays) & set(extra):
        fail("A date cannot be both a holiday and an extra working date.")
    return {"startDate": start, "horizonDays": horizon, "weekdays": sorted(weekdays),
            "holidays": holidays, "extraWorkingDates": extra}


def normalize_resources(raw):
    result = []
    for item in array(raw, "Resources", MAX_RESOURCES):
        item = obj(item, {"id", "name", "hoursByWeekday", "hoursByDate", "note"}, "Resource")
        ident = short_id(item.get("id"), "Resource ID")
        weekly = array(item.get("hoursByWeekday"), "Seven daily availability values", 7)
        if len(weekly) != 7:
            fail("Enter seven daily availability values; unentered values may be null.")
        overrides = item.get("hoursByDate", {})
        if not isinstance(overrides, dict) or len(overrides) > MAX_DAYS:
            fail("Resource date overrides must map dates to hours.")
        result.append({"id": ident, "name": text(item.get("name", ident), "Resource name", 300, True),
            "hoursByWeekday": [number(x, ident + " weekday " + str(i), nullable=True) for i, x in enumerate(weekly)],
            "hoursByDate": {iso(k, "Capacity override date"): number(v, "Capacity override") for k, v in sorted(overrides.items())},
            "note": text(item.get("note", ""), "Availability basis", 12000)})
    unique(result, "id", "Resources")
    return result


def normalize_tasks(raw, sources, resources):
    resource_ids = {row["id"] for row in resources}
    index = {row["id"]: row for row in sources}
    result = []
    for item in array(raw, "Task assignments", len(sources)):
        item = obj(item, {"id", "effortHours", "dependsOn", "releaseDate", "dueDate", "minBusinessDays", "priority", "note"}, "Task")
        ident = text(item.get("id"), "Task ID", 150, True)
        if ident not in index:
            fail("Choose a task from the selected original forecast: " + ident)
        effort = item.get("effortHours", {})
        if not isinstance(effort, dict) or set(effort) - resource_ids:
            fail(ident + ": effort must reference an entered resource.")
        parents = array(item.get("dependsOn", []), ident + " dependencies", len(sources))
        if any(not isinstance(p, str) or p not in index or p == ident for p in parents) or len(set(parents)) != len(parents):
            fail(ident + ": choose distinct other source tasks as dependencies.")
        result.append({"id": ident, "effortHours": {k: number(v, ident + " effort", nullable=True) for k, v in sorted(effort.items())},
            "dependsOn": list(parents), "releaseDate": iso(item.get("releaseDate"), "Release date", nullable=True),
            "dueDate": iso(item.get("dueDate"), "Due date", nullable=True),
            "minBusinessDays": integer(item.get("minBusinessDays", 0), "Minimum working duration"),
            "priority": integer(item.get("priority", 100), "Priority", 1000000),
            "note": text(item.get("note", ""), "Task allocation basis", 12000)})
    selected = unique(result, "id", "Task assignments")
    if selected.keys() != index.keys():
        fail("Retain every original grant package and selected commercial task in this portfolio.")
    try:
        allocation._topology([{"id": r["id"], "depends_on": r["dependsOn"]} for r in result])
    except allocation.PlanningError as exc:
        fail(str(exc))
    return result


def normalize_fields(raw, saved, sources, base=None, context=None):
    merged = deepcopy(base or {})
    merged.update({k: deepcopy(v) for k, v in raw.items() if k in FIELDS})
    calendar = normalize_calendar(merged.get("calendar"), saved)
    resources = normalize_resources(merged.get("resources"))
    tasks = normalize_tasks(merged.get("tasks"), sources, resources)
    result = {"calendar": calendar, "resources": resources, "tasks": tasks}
    if installation_plans.FIELD in merged:
        result[installation_plans.FIELD] = installation_plans.normalize(
            context, sources, resources, merged[installation_plans.FIELD])
    return result


def allocation_fields(raw, base=None):
    base = base or {}
    result = {key: raw.get(key, base.get(key)) for key in BASE_FIELDS}
    if installation_plans.FIELD in raw or installation_plans.FIELD in base:
        result[installation_plans.FIELD] = raw.get(installation_plans.FIELD, base.get(installation_plans.FIELD, []))
    return result


def effort_size(fields):
    groups = fields.get(installation_plans.FIELD, [])
    bound = {row["taskId"] for row in groups}
    return (sum(max(1, len(row["effortHours"])) for row in fields["tasks"] if row["id"] not in bound)
            + sum(max(1, len(phase["effortHours"])) for row in groups for phase in row["phases"]))


def normalize(context, saved, raw):
    raw = obj(raw, {"schema", "name", "forecastId", "forecastSha256", *FIELDS, "alternatives", "note"}, "Portfolio")
    if raw.get("schema") != SCHEMA:
        fail("Use the supported portfolio schema.")
    if raw.get("forecastId") != saved["id"] or raw.get("forecastSha256") != saved["sha256"]:
        fail("The selected immutable forecast differs from this draft.", "PORTFOLIO_FORECAST_CHANGED", 409)
    sources = source_tasks(saved)
    if not sources:
        fail("This forecast has no retained work packages or selected commercial work.")
    fields = normalize_fields(raw, saved, sources, context=context)
    alternatives = []
    for item in array(raw.get("alternatives", []), "Alternatives", MAX_ALTERNATIVES):
        item = obj(item, {"id", "name", "note", *FIELDS}, "Alternative")
        ident = short_id(item.get("id"), "Alternative ID")
        if ident == "base":
            fail("The base alternative ID is reserved for the entered base allocation.")
        authored = normalize_fields(item, saved, sources, fields, context=context)
        alternatives.append({"id": ident, "name": text(item.get("name"), "Alternative name", 300, True),
            "note": text(item.get("note", ""), "Alternative basis", 12000, True),
            **{key: authored[key] for key in FIELDS if key in item}})
    unique(alternatives, "id", "Alternatives")
    all_fields = [fields] + [allocation_fields(row, fields) for row in alternatives]
    if sum(row["calendar"]["horizonDays"] * len(row["resources"]) for row in all_fields) > 300000:
        fail("The complete comparison exceeds 300,000 resource dates. Shorten its horizon or reduce the alternatives.")
    if sum(row["calendar"]["horizonDays"] * effort_size(row) for row in all_fields) > 3000000:
        fail("The complete comparison exceeds 3,000,000 task-resource dates. Shorten its horizon or reduce the alternatives.")
    return {"schema": SCHEMA, "name": text(raw.get("name"), "Portfolio name", 300, True),
            "forecastId": saved["id"], "forecastSha256": saved["sha256"], **fields,
            "alternatives": alternatives, "note": text(raw.get("note", ""), "Portfolio basis", 12000)}


def seed(context, saved, installation_selections=None, draft_inputs=None, include_inventory=False):
    saved = check_source(context, saved)
    sources = source_tasks(saved)
    people = saved["snapshot"]["plan"]["planning"]["contributors"]
    resources = [{"id": r["id"], "name": r["name"], "hoursByWeekday": [None] * 7, "hoursByDate": {},
                  "note": r.get("note", "")} for r in people]
    assignments = saved["snapshot"]["plan"]["planning"]["assignments"]
    assigned = {}
    for row in assignments:
        assigned.setdefault(row["costId"], {})[row["contributorId"]] = row["hours"]
    tasks = []
    for source in sources:
        effort = deepcopy(assigned.get(source["sourceId"], {})) if source["sourceKind"] == "package" else {}
        exact = all(role in {r["id"] for r in resources} for role in effort) and sum((Decimal(v) for v in effort.values()), ZERO) == Decimal(source["remainingHours"])
        tasks.append({"id": source["id"], "effortHours": effort if exact else {}, "dependsOn": [],
            "releaseDate": source["timing"]["reviewedReleaseDate"] if "timing" in source else source["startDate"],
            "dueDate": None if "timing" in source else source["endDate"],
            "minBusinessDays": 0, "priority": 100,
            "note": ("Original start condition: " + source["timing"]["startCondition"]) if "timing" in source
                else ("Exact original pinned contributor assignments retained; their sum matches remaining hours." if exact and effort else "")})
    inputs = {"schema": SCHEMA, "name": "Delivery allocation — " + saved["inputs"]["name"],
        "forecastId": saved["id"], "forecastSha256": saved["sha256"],
        "calendar": {"startDate": saved["report"]["firstForecastDate"], "horizonDays": min(730, MAX_DAYS),
                     "weekdays": [0, 1, 2, 3, 4, 5, 6], "holidays": [], "extraWorkingDates": []},
        "resources": resources, "tasks": tasks, "alternatives": [], "note": ""}
    if draft_inputs is not None:
        inputs = normalize(context, saved, draft_inputs)
    if installation_selections is not None:
        inputs = installation_plans.seed(context, saved, sources, inputs, installation_selections)
    result = {"inputs": inputs, "baseForecast": base_reference(saved), "sourceTasks": sources,
        "originalCapacity": deepcopy(saved["report"]["capacity"]),
        "originalAssignments": deepcopy(assignments)}
    if include_inventory:
        result["installationCandidates"] = installation_plans.candidates(context, sources, current=True)
    if installation_plans.has_plans_field(inputs):
        result["installationSource"] = installation_plans.source_identity(context, inputs)
    return result


def finding(code, field, message):
    return {"code": code, "field": field, "message": message}


def cash_summary(report):
    current = report["scenarios"]["commercial"]
    result = {key: current[key] for key in ("additionalCashNeededUsd", "gapAfterOpeningCashUsd", "peakNeedDate", "endDeltaUsd")} | {
        "remainingCashOutflowUsd": report["totals"]["remainingCashOutflowWithCommercialUsd"],
        "cashScenarios": deepcopy(report["scenarios"]),
        **({"eventTiming": deepcopy(report["eventTiming"])} if "eventTiming" in report else {})}
    if "currencyValuation" in report:
        coverage = report["currencyValuation"]
        result.update({
            "currencyValuation": deepcopy(coverage),
            "scopeValuationComplete": coverage["complete"],
            "datedCashValuationComplete": coverage["datedCashComplete"],
            "financialComparisonEligible": coverage["complete"] and coverage["datedCashComplete"],
            "valuedPortion": deepcopy(current["valuedPortion"]),
            "knownRemainingCashOutflowUsd": report["totals"]["knownRemainingCashOutflowWithCommercialUsd"]})
    return result


def currency_rows(report):
    """Derived display/export rows; the complete original native source stays retained."""
    projects, receipts, rates = [], [], []
    for row in report["commercial"]:
        if "nativePricing" not in row:
            continue
        original, value = row["nativePricing"], row["currencyValuation"]
        price, cost = original["price"], original["deliveryCost"]
        projects.append({
            "id": row["id"], "title": row["title"], "selected": row["selected"],
            "priceCurrency": price["currency"], "priceNative": price["amount"],
            "priceRateId": price["fxRateId"], "priceUsd": value["price"]["amountUsd"],
            "costCurrency": cost["currency"], "deliveryCostNative": cost["amount"],
            "costRateId": cost["fxRateId"], "quotedDeliveryCostUsd": value["quotedTotalDeliveryCostUsd"],
            "effectiveDeliveryCostUsd": value["effectiveTotalDeliveryCostUsd"],
            "creditedPriceNative": value["creditedPriceNative"],
            "uncollectedPriceNative": value["uncollectedPriceNative"],
            "creditedCostNative": value["creditedCostNative"], "remainingCostNative": value["remainingCostNative"],
            "remainingUninvoicedCostUsd": row["remainingUninvoicedCostUsd"],
            "missingPriceCreditCashIds": "; ".join(value["missingPriceCreditCashIds"]),
            "missingCostCredits": "; ".join(x["kind"] + ":" + x["id"] for x in value["missingCostCredits"])})
        for item in row["receipts"]:
            receipts.append({
                "projectId": row["id"], "projectTitle": row["title"], "id": item["id"],
                "label": item["label"], "date": item["date"], "currency": price["currency"],
                **{key: item.get(key) for key in ("amountNative", "amountUsd", "appliedObservedUsd",
                    "remainingUsd", "appliedNative", "remainingNative", "valuedNativeCreditUsd",
                    "valuationRoundingUsd", "remainingRoundingUsd", "creditRoundingUsd", "settlementRoundingUsd")}})
    for item in report["currencyValuation"]["rates"]:
        rates.append({key: deepcopy(item.get(key)) for key in ("id", "baseCurrency", "quoteCurrency", "rate",
            "observationDate", "publicationDate", "basis", "rounding", "sourceUrl",
            "sourceReference", "sourceIds", "sourceSha256", "ageDays", "note")})
    return {"projects": projects, "receipts": receipts, "rates": rates}


def currency_report_html(report, table):
    if "currencyValuation" not in report:
        return ""
    coverage = report["currencyValuation"]
    rows = currency_rows(report)
    def display(values):
        output = []
        for row in values:
            shown = {}
            for key, value in row.items():
                if value is not None:
                    shown[key] = str(value)
                elif key == "date":
                    shown[key] = "Undated"
                elif key == "settlementRoundingUsd":
                    shown[key] = "—"
                else:
                    shown[key] = "Unvalued"
            output.append(shown)
        return output
    ready = coverage["complete"] and coverage["datedCashComplete"]
    pieces = ["<section><h2>Native currency and valuation</h2><p><strong>" +
        ("Selected scope and dated cash are valued." if ready else "Financial comparison is incomplete.") +
        "</strong> Operational work dates remain usable. Financial frontier membership and funding deltas require complete selected scope and dated cash valuation.</p>",
        "<p>" + escape(str(coverage["basis"])) + "</p>",
        table([("id","Work ID"),("title","Work"),("priceCurrency","Price currency"),("priceNative","Original price"),
               ("priceUsd","Valued price USD"),("costCurrency","Cost currency"),("deliveryCostNative","Original delivery cost"),
               ("quotedDeliveryCostUsd","Quoted delivery cost USD"),("effectiveDeliveryCostUsd","Effective delivery cost USD"),
               ("remainingUninvoicedCostUsd","Remaining uninvoiced cost USD")], display(rows["projects"])),
        "<h3>Original milestones and observed cash credits</h3>",
        table([("projectId","Work"),("id","Receipt"),("label","Milestone"),("date","Entered date"),("currency","Currency"),
               ("amountNative","Original amount"),("appliedNative","Native credit"),("remainingNative","Remaining native"),
               ("amountUsd","Valued amount USD"),("remainingUsd","Remaining USD"),
               ("settlementRoundingUsd","Settlement rounding USD")], display(rows["receipts"])),
        "<p>These are retained quote and planning amounts. Actual cash records stay in their recorded USD amounts. Missing native-credit allocations remain unresolved; reference exchange rates do not reconstruct settlement.</p>",
        "<h3>Selected exchange-rate sources</h3>",
        table([("id","Rate ID"),("baseCurrency","Base"),("quoteCurrency","Quote"),("rate","1 base equals quote"),
               ("observationDate","Observation"),("publicationDate","Publication"),("basis","Basis"),
               ("rounding","Rounding"),("ageDays","Age in days"),("sourceUrl","Original URL"),
               ("sourceReference","Source reference"),("sourceSha256","Retained source SHA-256"),("note","Operator note")], rows["rates"])]
    missing = [row for row in rows["projects"] if row["missingPriceCreditCashIds"] or row["missingCostCredits"]]
    if missing:
        pieces.append("<h3>Cash allocations requiring review</h3>" + table([
            ("id","Work"),("missingPriceCreditCashIds","Observed receipt IDs without native credits"),
            ("missingCostCredits","Cost records without native credits")], missing))
    scenario = report["scenarios"]["commercial"]
    pieces.append("<h3>Known portion of the dated cash projection</h3><p>This subtotal excludes unresolved amounts and cannot establish a complete funding requirement or ranking.</p>" +
        table([("additionalCashNeededUsd","Known funding need USD"),("gapAfterOpeningCashUsd","Known gap after opening cash USD"),
               ("peakNeedDate","Known peak date"),("endDeltaUsd","Known ending change USD")], [scenario["valuedPortion"]]))
    pieces.append("<p>Edit the original native amounts, explicit rates and cash credits in Operating forecast, save its reviewed successor, then create a new Portfolio allocation from that saved source. Existing saved portfolios retain their original valuation and source identities.</p></section>")
    return "\n".join(pieces)


def date_delta(new, old):
    return None if new is None or old is None else (date.fromisoformat(new) - date.fromisoformat(old)).days


def date_inputs(saved, chosen, name, event_deadlines=()):
    inputs = deepcopy(saved["inputs"])
    inputs["name"] = text(saved["inputs"]["name"] + " / " + name, "Selected forecast name", 300, True)
    overrides = {row["costId"]: row for row in inputs["packageOverrides"]}
    quotes = {row["id"]: row for row in inputs["commercial"]}
    reviewed_releases = {row["taskId"]: row["releaseDate"] for row in event_deadlines}
    for row in chosen:
        if row["sourceKind"] == "package":
            target = overrides.get(row["sourceId"])
            if target is None:
                target = {"costId": row["sourceId"]}
                inputs["packageOverrides"].append(target)
            target["startDate"], target["endDate"] = row["startDate"], row["endDate"]
        else:
            target = quotes[row["sourceId"]]
            target["startDate"], target["endDate"] = row["startDate"], row["endDate"]
            if "timing" in target:
                target["timing"]["reviewedReleaseDate"] = reviewed_releases[row["taskId"]]
        addition = "Portfolio " + name + ": entered availability, effort, dependencies and priority determine this remaining-work window."
        target["note"] = text((target.get("note", "") + "\n" + addition).strip(), "Selected date basis", 12000, True)
    return inputs


def calculate(context, saved, sources, fields, ident, name, note):
    index = {row["id"]: row for row in sources}
    findings = []
    bound = {row["taskId"] for row in fields.get(installation_plans.FIELD, [])}
    for resource in fields["resources"]:
        if any(x is None for x in resource["hoursByWeekday"]):
            findings.append(finding("CAPACITY_REQUIRED", "resources." + resource["id"],
                "Enter all seven daily availability values for " + resource["name"] + "."))
    for task in fields["tasks"]:
        source = index[task["id"]]
        if "timing" in source:
            retained_release = source["timing"]["reviewedReleaseDate"]
            if retained_release is None and task["releaseDate"] is None:
                findings.append(finding("EVENT_RELEASE_DATE_REQUIRED", "tasks." + task["id"] + ".releaseDate",
                    "Retain the original start condition and choose its reviewed release date before allocating this work: " + source["timing"]["startCondition"]))
            elif retained_release and task["releaseDate"] and task["releaseDate"] < retained_release:
                findings.append(finding("ORIGINAL_EVENT_RELEASE", "tasks." + task["id"] + ".releaseDate",
                    "Work cannot be released before the retained original reviewed trigger on " + retained_release + "."))
        if task["id"] in bound:
            continue
        values = task["effortHours"]
        if any(value is None for value in values.values()):
            findings.append(finding("EFFORT_REQUIRED", "tasks." + task["id"], "Enter every selected resource's remaining effort."))
        else:
            total = sum((Decimal(v) for v in values.values()), ZERO)
            expected = Decimal(index[task["id"]]["remainingHours"])
            if total != expected:
                findings.append(finding("EFFORT_TOTAL_REQUIRED", "tasks." + task["id"],
                    "Assign exactly " + forecasts.hours(expected) + " original remaining hours; currently assigned " + forecasts.hours(total) + "."))
    findings.extend(installation_plans.allocation_findings(context, sources, fields))
    common = {"id": ident, "name": name, "note": note, "findings": findings, "summary": None,
              "schedule": None, "chosenDates": [], "forecast": None}
    if installation_plans.FIELD in fields:
        common[installation_plans.FIELD] = installation_plans.report_groups(context, sources, fields)
    if findings:
        return {**common, "status": "INCOMPLETE"}
    calendar = fields["calendar"]
    pure = {"schema": allocation.SCHEMA, "id": ident, "title": name, "input_mode": context["program"]["mode"],
        "start_date": calendar["startDate"], "horizon_days": calendar["horizonDays"], "currency": "USD",
        "calendar": {"weekdays": calendar["weekdays"], "holidays": calendar["holidays"], "extra_working_dates": calendar["extraWorkingDates"]},
        "programme_ref": {"programId": context["program"]["id"], "forecastId": saved["id"], "forecastSha256": saved["sha256"]},
        "resources": [{"id": r["id"], "name": r["name"], "weekly_hours": r["hoursByWeekday"],
                       "hours_by_date": r["hoursByDate"], "hourly_cost": None} for r in fields["resources"]],
        "tasks": [{"id": r["id"], "title": index[r["id"]]["title"], "depends_on": r["dependsOn"],
                   "effort_hours": r["effortHours"], "release_date": r["releaseDate"] or calendar["startDate"],
                   "due_date": r["dueDate"], "minimum_business_days": r["minBusinessDays"], "priority": r["priority"],
                   "source_dates": {"startDate": index[r["id"]]["startDate"], "endDate": index[r["id"]]["endDate"]}} for r in fields["tasks"]]}
    try:
        timed = [task for task in pure["tasks"] if "timing" in index[task["id"]]]
        if timed:
            # Use the same native calendar for the contract's working-day clock.
            # Include an observed release before the forecast horizon without moving any work date.
            entered = {row["id"]: row["releaseDate"] for row in fields["tasks"]}
            releases = {task["id"]: index[task["id"]]["timing"]["reviewedReleaseDate"] or entered[task["id"]] for task in timed}
            for task in timed:
                task["release_date"] = entered[task["id"]] or releases[task["id"]]
            first = min([date.fromisoformat(calendar["startDate"])] + [date.fromisoformat(releases[task["id"]]) for task in timed])
            last = date.fromisoformat(calendar["startDate"]) + timedelta(days=calendar["horizonDays"])
            working = allocation.calendar_dates(first.isoformat(), (last - first).days, pure["calendar"])["days"]
            deadlines = []
            for task in timed:
                terms = index[task["id"]]["timing"]
                available = [stamp for stamp in working if stamp >= date.fromisoformat(releases[task["id"]])]
                duration = terms["deliveryBusinessDays"]
                if len(available) < duration:
                    return {**common, "status": "HORIZON_EXCEEDED",
                        "findings": [finding("EVENT_DEADLINE_OUTSIDE_HORIZON", "tasks." + task["id"],
                            "Extend the calendar to retain all " + str(duration) + " original delivery working days after the release date.")]}
                deadline = available[duration - 1].isoformat()
                if task["due_date"] is not None and task["due_date"] > deadline:
                    return {**common, "status": "INCOMPLETE",
                        "findings": [finding("ORIGINAL_EVENT_DEADLINE", "tasks." + task["id"] + ".dueDate",
                            "The original " + str(duration) + "-working-day term ends on " + deadline + ". Retain that deadline or an earlier one.")]}
                task["due_date"] = task["due_date"] or deadline
                deadlines.append({"taskId": task["id"], "releaseDate": releases[task["id"]], "workReleaseDate": task["release_date"],
                    "deliveryBusinessDays": duration, "contractDueDate": deadline, "selectedDueDate": task["due_date"],
                    "startCondition": terms["startCondition"]})
            common["eventDeadlines"] = deadlines
        expanded = installation_plans.expand(context, sources, fields, pure)
        schedule = allocation.plan_programme(expanded)
    except allocation.PlanningError as exc:
        return {**common, "status": "INCOMPLETE", "findings": [finding(exc.code, exc.field, str(exc))]}
    # Staffing rates do not replace the original forecast's complete quoted costs.
    schedule["method_notes"] = [line for line in schedule["method_notes"] if "cost" not in line.lower() and "frontier" not in line.lower()]
    schedule["method_notes"].append("The original operating forecast calculates all cash and quoted costs; resource hours allocate remaining work.")
    for row in schedule["tasks"]:
        for key in ("known_labor_cost", "unpriced_hours", "labor_cost"):
            row.pop(key, None)
    for row in schedule["resources"]:
        row.pop("hourly_cost", None)
    for key in ("known_labor_cost", "labor_cost", "unpriced_resources", "currency"):
        schedule["summary"].pop(key, None)
    brief = {"finishDate": schedule["summary"]["projected_finish_date"],
        "scheduledTasks": schedule["summary"]["scheduled_tasks"], "tasks": schedule["summary"]["tasks"],
        "totalHours": schedule["summary"]["effort_hours"], "lateTasks": schedule["summary"]["deadline_exceptions"],
        "maxLatenessDays": max((r["late_calendar_days"] or 0 for r in schedule["tasks"]), default=0)}
    if installation_plans.FIELD in fields:
        common[installation_plans.FIELD] = installation_plans.report_groups(context, sources, fields, schedule)
        native = {row["id"]: row for row in schedule["tasks"]}
        group_rows = {row["taskId"]: row for row in common[installation_plans.FIELD]}
        # Compare original source tasks across aggregate and phase alternatives.
        # Every detailed phase exception remains available in the native schedule.
        late_sources = 0
        for source in sources:
            if source["id"] in group_rows:
                group = group_rows[source["id"]]
                late = any((native[phase["scheduleTaskId"]]["late_calendar_days"] or 0) > 0 for phase in group["phases"])
            else:
                late = (native[source["id"]]["late_calendar_days"] or 0) > 0
            late_sources += int(late)
        brief["lateTasks"] = late_sources
        brief["phaseLateTasks"] = sum((row["late_calendar_days"] or 0) > 0 for row in schedule["tasks"]
                                      if row["id"].startswith("installation-phase/"))
        brief["sourceTasks"] = len(sources)
    if not schedule["summary"]["all_tasks_scheduled"]:
        unresolved = [r["id"] for r in schedule["tasks"] if r["finish_date"] is None]
        return {**common, "status": "HORIZON_EXCEEDED", "schedule": schedule, "summary": brief,
                "findings": [finding("UNSCHEDULED_WORK", ",".join(unresolved), "Increase entered capacity or extend the calendar to allocate all remaining work.")]}
    if bound:
        chosen = installation_plans.chosen_dates(context, sources, fields, schedule)
    else:
        chosen = []
        for row in schedule["tasks"]:
            source = index[row["id"]]
            start = row["first_work_date"] or row["ready_date"]
            end = row["finish_date"]
            chosen.append({"taskId": row["id"], "sourceKind": source["sourceKind"], "sourceId": source["sourceId"],
                "oldStartDate": source["startDate"], "oldEndDate": source["endDate"], "startDate": start, "endDate": end,
                "startShiftDays": date_delta(start, source["startDate"]), "endShiftDays": date_delta(end, source["endDate"])})
    chosen_index = {r["taskId"]: r for r in chosen}
    for quote in saved["report"]["commercial"]:
        if not quote["selected"]:
            continue
        window = chosen_index["commercial/" + quote["id"]]
        for receipt in quote["receipts"]:
            stamp = receipt["date"]
            if not stamp or (receipt["remainingUsd"] is not None and Decimal(receipt["remainingUsd"]) == 0):
                continue
            if stamp < window["startDate"]:
                findings.append(finding("COLLECTION_BEFORE_ALLOCATED_START", "commercial." + quote["id"] + ".receipts." + receipt["id"],
                    receipt["label"] + " remains on " + stamp + ", before allocated work starts on " + window["startDate"] + ". Review collection timing in the original forecast."))
            elif window["oldEndDate"] is not None and stamp >= window["oldEndDate"] and stamp < window["endDate"]:
                findings.append(finding("COLLECTION_BEFORE_REPLANNED_FINISH", "commercial." + quote["id"] + ".receipts." + receipt["id"],
                    receipt["label"] + " remains on " + stamp + "; the work now finishes on " + window["endDate"] + ". Review its collection basis in the original forecast."))
    for grant in saved["report"]["grants"]:
        ends = [chosen_index[r["id"]]["endDate"] for r in sources if r["sourceKind"] == "package" and r["tranche"] == grant["tranche"]]
        if grant["included"] and grant["forecastDate"] and Decimal(grant["remainingUsd"]) and ends and grant["forecastDate"] < max(ends):
            findings.append(finding("GRANT_COLLECTION_BEFORE_REPLANNED_FINISH", "grants." + str(grant["tranche"]),
                "The conditional grant receipt remains on " + grant["forecastDate"] + "; this tranche's allocated work finishes on " + max(ends) + ". Review the original payout timing assumption."))
    selected = forecasts.preview(context, date_inputs(saved, chosen, name, common.get("eventDeadlines", ())))
    if selected["report"]["totals"] != saved["report"]["totals"]:
        fail("The date allocation changed original forecast totals.", "PORTFOLIO_CASH_SOURCE_CONFLICT", 409)
    return {**common, "status": "READY", "schedule": schedule, "chosenDates": chosen,
            "summary": {**brief, **cash_summary(selected["report"]), "collectionTimingReviews": len(findings)},
            "forecast": {"inputs": selected["inputs"], "previewSha256": selected["previewSha256"], "report": selected["report"]}}


def build(context, saved, inputs):
    sources = source_tasks(saved)
    base = allocation_fields(inputs)
    alternatives = [calculate(context, saved, sources, base, "base", "Base allocation", inputs["note"])]
    for row in inputs["alternatives"]:
        fields = allocation_fields(row, base)
        alternatives.append(calculate(context, saved, sources, fields, row["id"], row["name"], row["note"]))
    original_end = max((row["endDate"] for row in sources if row["endDate"] is not None), default=saved["inputs"]["asOfDate"])
    baseline = {"name": saved["inputs"]["name"], "finishDate": original_end,
        "totalHours": forecasts.hours(sum((Decimal(r["remainingHours"]) for r in sources), ZERO)),
        "overloadedDays": saved["report"]["capacity"]["overloadedDays"],
        "peakWeeklyEquivalentHours": saved["report"]["capacity"]["peakWeeklyEquivalentHours"],
        **cash_summary(saved["report"])}
    currency_mode = "currencyValuation" in saved["report"]
    comparison = []
    ready = [row for row in alternatives if row["status"] == "READY"]
    comparable = [row for row in ready if not currency_mode or row["summary"]["financialComparisonEligible"]]
    vector = lambda x: (x["summary"]["finishDate"], x["summary"]["lateTasks"], Decimal(x["summary"]["additionalCashNeededUsd"]))
    for row in alternatives:
        summary = row["summary"]
        summary_copy = deepcopy(summary) if summary else {}
        if currency_mode:
            # Complete rate and native-money evidence stays in the original summary.
            # Comparison rows carry the scalar state instead of another full copy.
            summary_copy.pop("currencyValuation", None)
        value = {"id": row["id"], "name": row["name"], "status": row["status"], "frontier": False,
                 **summary_copy}
        eligible = row["status"] == "READY" and (not currency_mode or summary["financialComparisonEligible"])
        if currency_mode:
            value["financialComparisonEligible"] = eligible
            value["fundingNeedDeltaUsd"] = None
            if not eligible:
                value["frontier"] = None
                value["financialComparisonReason"] = (
                    "Complete the work allocation before comparing its finances." if row["status"] != "READY"
                    else "Resolve both the selected scope valuation and dated cash valuation in the original forecast.")
            elif not baseline["financialComparisonEligible"]:
                value["financialComparisonReason"] = "The alternative is valued; the original baseline still has unresolved valuation, so its funding delta is unavailable."
            else:
                value["financialComparisonReason"] = "Selected scope and dated cash valuation are complete."
        if row["status"] == "READY":
            value["finishShiftDays"] = date_delta(summary["finishDate"], original_end)
            if eligible:
                if not currency_mode or baseline["financialComparisonEligible"]:
                    value["fundingNeedDeltaUsd"] = forecasts.money(Decimal(summary["additionalCashNeededUsd"]) - Decimal(baseline["additionalCashNeededUsd"]))
                own = vector(row)
                value["frontier"] = not any(other["id"] != row["id"] and all(a <= b for a, b in zip(vector(other), own))
                    and any(a < b for a, b in zip(vector(other), own)) for other in comparable)
        comparison.append(value)
    result = {"sourceTasks": sources, "baseline": baseline, "alternatives": alternatives, "comparison": comparison,
        "comparisonBasis": "Entered alternatives compared by finish date, late-task count and original cash funding need.",
        "paymentTimingBasis": "Quoted receipts, grant receipts, invoice dates, amounts and original installment schedules retain their entered dates. Original completion and accrual expense rules use the selected work window."}
    if installation_plans.has_plans_field(inputs):
        result["installationCandidates"] = installation_plans.candidates(context, sources, inputs)
        result["paymentTimingBasis"] += (" Explicitly selected Installation delivery boundaries set commercial work windows; "
            "all retained later support still consumes native resource capacity. Original full quoted costs remain in the commercial forecast.")
    if currency_mode:
        result["comparisonBasis"] = (
            "Operationally ready alternatives keep their delivery dates. The financial frontier compares only alternatives with complete selected scope and dated cash valuation. "
            "Funding deltas also require a complete original baseline; unvalued amounts and known-only cash never become zero or a complete financial ranking.")
        result["financialComparison"] = {
            "reportingCurrency": "USD",
            "baselineEligible": baseline["financialComparisonEligible"],
            "eligibleAlternativeIds": [row["id"] for row in comparable],
            "excludedAlternativeIds": [row["id"] for row in alternatives if row["id"] not in {item["id"] for item in comparable}],
            "basis": result["comparisonBasis"]}
    return result

def preview(context, saved, raw):
    saved = check_source(context, saved)
    inputs = normalize(context, saved, raw)
    value = {"schema": SCHEMA, "engineVersion": ENGINE_VERSION, "source": forecasts.source_identity(context),
             "baseForecast": base_reference(saved), "inputs": inputs, "report": build(context, saved, inputs)}
    if installation_plans.has_plans_field(inputs):
        value["installationSource"] = installation_plans.source_identity(context, inputs)
    value["previewSha256"] = digest(value)
    return value


def validate_saved(value, pinned_plan=None):
    try:
        if not isinstance(value, dict) or value.get("schema") != SCHEMA or value.get("engineVersion") != ENGINE_VERSION:
            fail("Unsupported saved portfolio.")
        if digest({key: item for key, item in value.items() if key != "sha256"}) != value.get("sha256"):
            fail("The saved portfolio differs from its retained identity.", "PORTFOLIO_CHANGED", 409)
        short_id(value.get("id"), "Portfolio ID")
        domain.timestamp(value.get("createdAt"), "Portfolio creation")
        text(value.get("actor"), "Portfolio operator", 300, True)
        text(value.get("note"), "Portfolio save note", 12000)
        context, saved = value["snapshot"], value["baseForecastSnapshot"]
        if pinned_plan and (context["plan"]["contentSha256"] != pinned_plan["contentSha256"]
                            or context["plan"]["source"]["sha256"] != pinned_plan["source"]["sha256"]):
            fail("The portfolio belongs to another pinned plan.", "PORTFOLIO_SOURCE_CONFLICT", 409)
        rebuilt = preview(context, saved, value["inputs"])
        if (any(rebuilt[key] != value.get(key) for key in ("source", "baseForecast", "inputs", "report", "previewSha256"))
                or rebuilt.get("installationSource") != value.get("installationSource")):
            fail("The saved portfolio differs from its complete source calculation.", "PORTFOLIO_CHANGED", 409)
        return value
    except (KeyError, TypeError, ValueError, AttributeError, ArithmeticError) as exc:
        if isinstance(exc, Problem):
            raise
        fail("The complete saved portfolio is invalid: " + str(exc))


def summary(value):
    return {key: deepcopy(value[key]) for key in ("id", "createdAt", "actor", "source", "sha256", "previewSha256", "baseForecast")} | {
        "name": value["inputs"]["name"], "alternatives": len(value["report"]["alternatives"]),
        "readyAlternatives": sum(row["status"] == "READY" for row in value["report"]["alternatives"]),
        "comparison": deepcopy(value["report"]["comparison"]),
        **({"financialComparison": deepcopy(value["report"]["financialComparison"])}
           if "financialComparison" in value["report"] else {})}


def select(context, value, alternative_id):
    validate_saved(value, context["plan"])
    if forecasts.source_identity(context)["factsSha256"] != value["source"]["factsSha256"]:
        fail("The case facts changed. Refresh the source forecast and allocation before selecting its dates.",
             "PORTFOLIO_SOURCE_CHANGED", 409)
    row = next((r for r in value["report"]["alternatives"] if r["id"] == alternative_id), None)
    if row is None:
        fail("The selected saved alternative is unavailable.", "PORTFOLIO_ALTERNATIVE_NOT_FOUND", 404)
    if row["status"] != "READY":
        fail("Complete this alternative's availability, effort and event release dates before selecting its dates.")
    selected_input = next((item for item in value["inputs"]["alternatives"] if item["id"] == alternative_id), {})
    selected_fields = allocation_fields(selected_input, value["inputs"])
    selected_source = None
    if installation_plans.FIELD in selected_fields:
        selected_source = installation_plans.source_identity(context, selected_fields)
        if selected_source != installation_plans.source_identity(value["snapshot"], selected_fields):
            fail("The selected Installation edition changed. Reselect its current source before applying these dates.",
                 "PORTFOLIO_INSTALLATION_CHANGED", 409)
    candidate = forecasts.preview(context, row["forecast"]["inputs"])
    return {"inputs": candidate["inputs"], "selection": {"portfolioId": value["id"], "portfolioSha256": value["sha256"],
        "alternativeId": row["id"], "baseForecast": value["baseForecast"], "source": forecasts.source_identity(context),
        "previewSha256": candidate["previewSha256"], "chosenDates": deepcopy(row["chosenDates"]),
        **({"installationSource": selected_source, "installationPlans": deepcopy(row.get(installation_plans.FIELD, []))}
           if selected_source is not None else {})}}


def report_html(value):
    report = value["report"]
    def table(columns, rows):
        head = "".join("<th>" + escape(label) + "</th>" for key, label in columns)
        body = "".join("<tr>" + "".join("<td>" + escape("" if row.get(key) is None else str(row[key])) + "</td>" for key, label in columns) + "</tr>" for row in rows)
        return "<div class='scroll'><table><thead><tr>" + head + "</tr></thead><tbody>" + body + "</tbody></table></div>"
    parts = ["<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>",
        "<title>" + escape(value["inputs"]["name"]) + "</title><style>body{font:15px/1.5 system-ui,sans-serif;color:#202020;background:#fafafa;max-width:1200px;margin:32px auto;padding:0 24px}h1,h2{line-height:1.2}h2{margin-top:36px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #ccc;padding:8px;text-align:left;vertical-align:top}th{background:#e9e9e9}.scroll{overflow:auto}code{overflow-wrap:anywhere}p{max-width:95ch}a{color:#222}</style><body>",
        "<h1>" + escape(value["inputs"]["name"]) + "</h1><p>Original forecast: <code>" + escape(value["baseForecast"]["id"]) + "</code>. Saved allocation: <code>" + escape(value["id"]) + "</code>.</p>",
        "<p>" + escape(report["paymentTimingBasis"]) + "</p><p>" + escape(value["inputs"]["note"]) + "</p>",
        "<h2>Delivery and cash comparison</h2>",
        table([("name","Alternative"),("status","State"),("finishDate","Finish"),("totalHours","Hours"),("lateTasks","Late tasks"),
               ("additionalCashNeededUsd","Funding need USD"),("fundingNeedDeltaUsd","Change USD"),("frontier","Comparison frontier")], report["comparison"]),
        "<p>Original dated forecast finishes " + escape(report["baseline"]["finishDate"]) + ", with " + str(report["baseline"]["overloadedDays"]) + " calendar dates above its original weekly-equivalent capacity. " + escape(report["comparisonBasis"]) + "</p>"]
    if "financialComparison" in report:
        parts.append("<h2>Financial comparison eligibility</h2>" + table([
            ("name","Alternative"),("financialComparisonEligible","Eligible"),
            ("financialComparisonReason","Reason"),("fundingNeedDeltaUsd","Funding change USD"),
            ("frontier","Financial frontier")],
            [{**row, "fundingNeedDeltaUsd": "Unvalued" if row.get("fundingNeedDeltaUsd") is None else row["fundingNeedDeltaUsd"],
              "frontier": "Excluded" if row.get("frontier") is None else row["frontier"]} for row in report["comparison"]]))
        parts.append(currency_report_html(value["baseForecastSnapshot"]["report"], table))
    for row in report["alternatives"]:
        parts.extend(["<h2>" + escape(row["name"]) + "</h2><p>" + escape(row["note"]) + "</p>"])
        if row["findings"]:
            parts.append(table([("field","Input"),("message","Required detail")], row["findings"]))
        if row.get("forecast") and "currencyValuation" in row["forecast"]["report"]:
            coverage = row["summary"]
            parts.append("<p><strong>Financial valuation:</strong> " +
                ("complete" if coverage["financialComparisonEligible"] else "incomplete; allocation dates remain selectable") +
                ". Complete funding need USD: " + escape("Unvalued" if coverage["additionalCashNeededUsd"] is None else coverage["additionalCashNeededUsd"]) +
                ". Known portion funding need USD: " + escape(coverage["valuedPortion"]["additionalCashNeededUsd"]) + ".</p>")
        if row["schedule"]:
            parts.append(table([("title","Task"),("ready_date","Ready"),("first_work_date","First work"),("finish_date","Finish"),
                ("due_date","Due"),("late_calendar_days","Late days"),("effort_hours","Hours"),
                ("capacity_delay_business_days","Capacity delay")], row["schedule"]["tasks"]))
            parts.append("<p><a href='alternatives/" + escape(row["id"], quote=True) + "/resource-days.csv'>Resource calendar CSV</a> · <a href='alternatives/" + escape(row["id"], quote=True) + "/allocations.csv'>Task allocations CSV</a></p>")
    if any("timing" in row for row in report["sourceTasks"]):
        timing_rows = [{"title": row["title"], "startCondition": row["timing"]["startCondition"],
            "deliveryBusinessDays": row["timing"]["deliveryBusinessDays"],
            "reviewedReleaseDate": row["timing"]["reviewedReleaseDate"],
            "collectionConditions": "; ".join(item["receiptId"] + ": " + item["condition"] for item in row["timing"]["receiptConditions"])}
            for row in report["sourceTasks"] if "timing" in row]
        parts.append("<h2>Original event-dependent terms</h2>" + table([("title","Work"),("startCondition","Start condition"),
            ("reviewedReleaseDate","Original reviewed trigger"),("deliveryBusinessDays","Quoted delivery working days"),("collectionConditions","Original collections")], timing_rows))
        parts.append("<p>Undated work stays in the complete source scope. The original forecast lists its undated cash and hours separately until a reviewed release and work window are selected.</p>")
    parts.append("<h2>Original remaining scope</h2>" + table([("title","Work"),("sourceKind","Source"),("remainingHours","Hours"),("remainingCostUsd","Remaining cash USD"),("scope","Scope")], report["sourceTasks"]))
