.cohort-planning h2,.cohort-planning h3,.cohort-planning h4,.cohort-planning p{margin:0 0 .65rem}
.cohort-planning h2{font-size:1.65rem;line-height:1.2;font-weight:650}
.cohort-planning h3{font-size:1.1rem;font-weight:650}
.cohort-planning h4{font-size:.95rem;font-weight:650}
.cohort-planning button,.cohort-planning input,.cohort-planning select,.cohort-planning textarea{font:inherit}
.cohort-planning button{border:1px solid #acafb2;border-radius:3px;background:#fff;color:var(--cp-ink);padding:.48rem .75rem;line-height:1.4;cursor:pointer;max-width:100%}
.cohort-planning button:hover:not(:disabled){border-color:#565a5e;background:#f1f2f3}
.cohort-planning button:disabled{opacity:.48;cursor:default}
.cohort-planning button:focus-visible,.cohort-planning input:focus-visible,.cohort-planning select:focus-visible,.cohort-planning textarea:focus-visible,.cohort-planning summary:focus-visible{outline:2px solid #393d41;outline-offset:3px}
.cohort-planning input,.cohort-planning select,.cohort-planning textarea{width:100%;min-width:0;border:1px solid #afb3b7;border-radius:3px;background:#fff;color:var(--cp-ink);padding:.5rem .6rem;min-height:37px;font-weight:400}
.cohort-planning textarea{resize:vertical}
.cohort-planning input[readonly]{background:#f3f4f4}
.cohort-planning select[multiple]{padding:.25rem}
.cohort-planning select[multiple] option{padding:.4rem}
.cohort-planning label{display:flex;flex-direction:column;gap:.3rem;font-size:.82rem;font-weight:600;min-width:0}
.cohort-planning label small{font-size:.76rem;font-weight:400;color:var(--cp-muted);line-height:1.5}
.cohort-planning fieldset{min-width:0;border:1px solid var(--cp-line);border-radius:3px;padding:.9rem;margin:.25rem 0}
.cohort-planning legend{font-weight:650;font-size:.86rem;padding:0 .35rem}
.cohort-planning code{font:11px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}
