.cp-actions button{font-size:.82rem}
.cp-status{display:flex;align-items:center;gap:.45rem;flex-wrap:wrap;margin:.5rem 0 .8rem}
.cp-badge{display:inline-block;border:1px solid #c7cbce;border-radius:3px;background:#f5f5f5;padding:.12rem .4rem;font-size:.72rem;font-weight:600}
.cp-note,.cp-identity,.cp-report-state{color:var(--cp-muted);font-size:.84rem;overflow-wrap:anywhere}
.cp-note{margin:.55rem 0!important}
.cp-identity{font:11px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace}
.cp-notice,.cp-alert,.cp-recovery{border:1px solid #afb4b8;border-left:4px solid #6d747a;background:#f5f6f6;padding:.8rem 1rem;margin:.75rem 0}
.cp-alert{border-left-color:#464b50;background:#f3f3f3}
.cp-recovery .cp-actions{margin:.65rem 0 0}
.cp-tabs{display:flex;border-bottom:1px solid #9ea5aa;gap:0;overflow-x:auto;align-items:stretch;margin:1rem 0;padding:0}
.cp-tabs button,.cp-subtabs button{border:0;border-radius:0;border-bottom:3px solid transparent;white-space:nowrap;font-size:.82rem;padding:.65rem .8rem;background:#fff}
.cp-tabs button[aria-current=page],.cp-subtabs button[aria-current=page]{border-bottom-color:#343a3f;color:#202428;font-weight:700;background:#f1f2f3}
.cp-subtabs{display:flex;gap:.25rem;flex-wrap:wrap;border-bottom:1px solid var(--cp-line);margin:.8rem 0 1rem}
.cp-subtabs button{font-size:.78rem}
.cp-panel{border:1px solid var(--cp-line);border-radius:3px;background:#fff;margin-bottom:1rem;padding:1rem;min-width:0}
