.cp-table caption{text-align:left;font-size:.83rem;font-weight:650;padding:.35rem 0}
.cp-table th{font-weight:650;background:#f1f2f3;border-top:1px solid var(--cp-line);color:#42484d;white-space:normal;min-width:80px}
