.cp-table td{min-width:90px;max-width:380px;overflow-wrap:anywhere;white-space:pre-wrap}
.cp-table td small{display:block;color:var(--cp-muted);font-size:.7rem;margin-top:.3rem}
.cp-table td strong{font-weight:600}
.cp-table td button{font-size:.74rem;padding:.32rem .48rem;white-space:nowrap}
.cp-row-actions{display:flex;gap:.3rem;flex-wrap:wrap}
.cp-pager{display:flex;justify-content:flex-end;align-items:center;gap:.65rem;font-size:.78rem;margin:.8rem 0 .2rem;color:var(--cp-muted)}
.cp-pager button{font-size:.75rem}
.cp-filter{display:flex;gap:.5rem;align-items:flex-end;margin:0 0 1rem;flex-wrap:wrap}
.cp-filter label{min-width:250px;max-width:520px;flex:1}
.cp-filter button{font-size:.82rem}
.cp-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--cp-line);border-left:1px solid var(--cp-line);margin:.8rem 0 1rem}
.cp-metrics article{border-right:1px solid var(--cp-line);border-bottom:1px solid var(--cp-line);padding:.75rem .8rem;min-width:0}
.cp-metrics article span{display:block;font-size:.73rem;color:var(--cp-muted)}
.cp-metrics article strong{display:block;font-size:1.1rem;font-variant-numeric:tabular-nums;font-weight:650;margin-top:.3rem;overflow-wrap:anywhere}
.cp-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:.4rem;margin:.8rem 0 1rem}
.cp-calendar button{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:.25rem;padding:.65rem .55rem;min-width:0}
.cp-calendar span{font-size:.7rem;color:var(--cp-muted)}
.cp-calendar strong{font-size:.85rem;font-weight:600}
.cp-calendar small{font-size:.7rem;color:var(--cp-muted);overflow-wrap:anywhere}
.cp-calendar button[aria-pressed=true]{border:2px solid #3f474e;padding:calc(.65rem - 1px) calc(.55rem - 1px);background:#eceeef}
.cp-calendar .cp-calendar-off{background:#f4f4f4}
.cp-source-change,.cp-source-status{padding:.8rem .9rem;border:1px solid #c8cdd0;border-left:3px solid #798187;background:#f8f8f8;margin:.5rem 0}
.cp-source-change{border-left-color:#424a50}
