.forecast-currency-credit small{overflow-wrap:anywhere}
.forecast-currency-coverage{border:1px solid var(--forecast-line);padding:1rem;margin:1.2rem 0;background:#fafafa}
.forecast-currency-coverage h5{margin-top:0}
.forecast-coverage-state{display:inline-block;font-weight:600;padding:.35rem .55rem;border:1px solid #888;margin:0 0 .5rem}
.forecast-currency-coverage p:last-child{margin-bottom:0}
.forecast-valuation-warning{border-left:3px solid #555;background:#f4f4f4;padding:.7rem .85rem;font-size:.87rem}
.forecast-unvalued{color:#343434!important;font-weight:600!important}
.forecast-currency-project{border:1px solid var(--forecast-line)!important;padding:1rem!important;margin:1rem 0!important}
.forecast-currency-project>summary{overflow-wrap:anywhere}
.forecast-currency-project .forecast-stats{grid-template-columns:repeat(3,minmax(0,1fr))}
.forecast-currency-original{font-variant-numeric:tabular-nums;font-weight:600}
.forecast-currency-value{font-variant-numeric:tabular-nums}
.forecast-currency-reference{overflow-wrap:anywhere}
.forecast-currency-credits textarea{min-height:4.5rem}
@media(max-width:800px){
 .forecast-currency-credit{grid-template-columns:1fr 1fr}
 .forecast-currency-credit>p,.forecast-currency-credit>div:first-child{grid-column:1/-1}
