    if(session.sending){try{await session.sending;}catch{}if(available()&&session.accepted){const value=session.accepted;session.accepted=null;await onSaved(value);}return;}
    if(session.accepted){const value=session.accepted;session.accepted=null;await onSaved(value);return;}
    busy=true;sync();
    try {
      try {await initializeDesk();}
      catch(error) {
        if(!available())return;
        session.storageError=error.message||'Browser storage is unavailable.';
        tell('Saved browser drafts could not be opened. The current draft and complete desk download remain available; saved case reviews are loading.',true);
      }
      activeCheck();render();await loadReviews();
      if(session.selected&&!session.pending&&(!session.sourceReview||session.sourceReview.version!==current.program.version))await openSource();
      else render();
    } catch(error){if(available())tell(error.message,true);}
    finally{busy=false;sync();}
  })();
  return {root,ready,dispose,setHostBusy};
}

/* MIT. Original settlement receiving within the SF47 Operations workspace. */
.settlement-desk {
  --settlement-ink: #252525;
  --settlement-line: #b8b8b8;
  --settlement-muted: #575757;
  display: grid;
  gap: 20px;
  min-width: 0;
  color: var(--settlement-ink);
}
.settlement-desk *, .settlement-desk *::before, .settlement-desk *::after { box-sizing: border-box; }
.settlement-desk h3 { margin: 0 0 8px; font-size: 24px; line-height: 1.3; }
.settlement-desk h4 { margin: 0 0 10px; font-size: 17px; }
.settlement-desk p { max-width: 100ch; line-height: 1.55; }
.settlement-heading { display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; }
.settlement-heading > div { min-width: 0; }
.settlement-heading p { margin: 0; color: var(--settlement-muted); }
.settlement-desk .settlement-section, .settlement-desk fieldset {
  min-width: 0; margin: 0; padding: 20px; border: 1px solid var(--settlement-line); background: #fff;
}
.settlement-desk legend { padding: 0 8px; font-size: 15px; font-weight: 650; }
.settlement-desk form, .settlement-draft { display: grid; gap: 20px; min-width: 0; }
.settlement-desk label { display: grid; gap: 6px; min-width: 0; font-size: 13px; font-weight: 600; }
.settlement-desk small { display: block; font-size: 12px; line-height: 1.5; font-weight: 400; color: var(--settlement-muted); overflow-wrap: anywhere; }
.settlement-desk input, .settlement-desk select, .settlement-desk textarea {
  width: 100%; min-width: 0; max-width: 100%; padding: 9px 10px; border: 1px solid #9b9b9b;
  border-radius: 2px; background: #fff; color: #222; font: inherit;
}
.settlement-desk textarea { resize: vertical; }
.settlement-desk input[type=checkbox] { width: 18px; height: 18px; margin: 1px 0; accent-color: #303030; }
.settlement-desk input[type=file] { background: #f5f5f5; }
.settlement-desk select[multiple] { min-height: 88px; }
.settlement-desk button {
  padding: 9px 13px; border: 1px solid #999; border-radius: 2px;
  background: #f5f5f5; color: #222; font: 600 13px/1.4 system-ui, sans-serif;
  white-space: normal; text-align: center;
}
.settlement-desk button:hover:not(:disabled) { background: #e5e5e5; border-color: #555; }
.settlement-desk button.settlement-primary { background: #292929; border-color: #292929; color: #fff; }
.settlement-desk button.settlement-primary:hover:not(:disabled) { background: #050505; }
.settlement-desk button:focus-visible, .settlement-desk input:focus-visible,
.settlement-desk select:focus-visible, .settlement-desk textarea:focus-visible,
.settlement-desk summary:focus-visible { outline: 3px solid #707070; outline-offset: 3px; }
.settlement-desk :disabled { opacity: .6; cursor: default; }
.settlement-desk [hidden] { display: none !important; }
.settlement-fields { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 16px; margin: 12px 0 0; }
.settlement-fields .settlement-wide { grid-column: 1 / -1; }
.settlement-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.settlement-actions p { margin: 0; }
.settlement-metrics { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); border: 1px solid var(--settlement-line); }
.settlement-metrics > div { min-width: 0; padding: 15px; border-right: 1px solid var(--settlement-line); background: #f3f3f3; }
.settlement-metrics > div:last-child { border-right: 0; }
.settlement-metrics strong { display: block; font-size: 25px; font-weight: 650; line-height: 1.2; overflow-wrap: anywhere; }
.settlement-metrics span { display: block; font-size: 12px; margin-top: 6px; line-height: 1.5; }
.settlement-desk .settlement-note { color: var(--settlement-muted); font-size: 13px; }
.settlement-desk .settlement-message, .settlement-pending {
  padding: 13px 16px; border: 1px solid var(--settlement-line); border-left: 4px solid #555; background: #f4f4f4; margin: 0;
}
.settlement-desk .settlement-message:empty { display: none; }
.settlement-desk .settlement-message[role=alert] { border-left-width: 6px; background: #ededed; font-weight: 600; }
.settlement-pending h4 { margin-bottom: 6px; }
.settlement-transfers { display: grid; gap: 16px; min-width: 0; }
.settlement-transfer { border: 1px solid var(--settlement-line); min-width: 0; background: #fff; }
.settlement-transfer > header { display: flex; justify-content: space-between; gap: 12px; padding: 14px 16px; background: #f0f0f0; border-bottom: 1px solid var(--settlement-line); }
.settlement-transfer > header strong { overflow-wrap: anywhere; }
.settlement-status { display: inline-block; border: 1px solid #aaa; background: #fff; padding: 3px 6px; font-size: 11px; font-weight: 600; line-height: 1.5; }
.settlement-facts { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 14px; margin: 0; padding: 16px; }
.settlement-facts dt { color: var(--settlement-muted); font-size: 11px; margin-bottom: 5px; }
.settlement-facts dd { margin: 0; font-size: 13px; font-weight: 600; overflow-wrap: anywhere; }
.settlement-transfer .settlement-fields { padding: 0 16px 16px; }
.settlement-findings { margin: 0; padding: 12px 16px 12px 34px; border-top: 1px solid var(--settlement-line); background: #f6f6f6; font-size: 13px; line-height: 1.6; }
.settlement-table-wrap { max-width: 100%; overflow-x: auto; border: 1px solid var(--settlement-line); }
.settlement-desk table { border-collapse: collapse; width: 100%; text-align: left; font-size: 13px; }
.settlement-desk th, .settlement-desk td { padding: 10px 12px; border-bottom: 1px solid #d0d0d0; vertical-align: top; overflow-wrap: anywhere; }
.settlement-desk th { background: #eee; font-size: 12px; font-weight: 650; }
.settlement-desk tr:last-child td { border-bottom: 0; }
.settlement-desk .settlement-number { font-variant-numeric: tabular-nums; white-space: nowrap; }
.settlement-desk details { padding: 12px 0; }
.settlement-transfer details { padding: 12px 16px; border-top: 1px solid var(--settlement-line); }
.settlement-desk summary { cursor: pointer; font-size: 13px; font-weight: 650; }
.settlement-desk pre { padding: 14px; max-height: 420px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; background: #f1f1f1; border: 1px solid #ccc; color: #222; font: 12px/1.6 ui-monospace, SFMono-Regular, Consolas, monospace; }
.settlement-desk code { font: 12px/1.6 ui-monospace, SFMono-Regular, Consolas, monospace; overflow-wrap: anywhere; }
.settlement-history { display: grid; gap: 12px; }
.settlement-history article { padding: 16px; border: 1px solid var(--settlement-line); background: #fff; }
.settlement-history article > header { display: flex; justify-content: space-between; align-items: flex-start; gap: 14px; }
.settlement-history article p { margin: 5px 0 12px; font-size: 13px; }
@media (max-width: 920px) {
  .settlement-facts { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .settlement-metrics { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .settlement-metrics > div:nth-child(2) { border-right: 0; }
  .settlement-metrics > div:nth-child(-n+2) { border-bottom: 1px solid var(--settlement-line); }
}
@media (max-width: 580px) {
  .settlement-heading, .settlement-transfer > header, .settlement-history article > header { display: grid; }
  .settlement-fields, .settlement-facts { grid-template-columns: minmax(0,1fr); }
  .settlement-desk .settlement-section, .settlement-desk fieldset { padding: 14px; }
  .settlement-actions button { flex: 1 1 150px; }
  .settlement-desk input, .settlement-desk select, .settlement-desk textarea { font-size: 16px; }
  .settlement-desk h3 { font-size: 22px; }
  .settlement-metrics > div { padding: 12px; }
}

/**
 * Compare a complete adoption plan with an original frozen Operations cohort.
 * Native review classifications remain authoritative; this module joins them to
 * planned purchase opportunities without turning requests or task uses into sales.
 */
import {COHORT_PLAN_SCHEMA, COHORT_PLAN_REPORT_SCHEMA, evaluateCohortPlan} from './cohort_planning.mjs';

export const COHORT_DELIVERY_INPUT_SCHEMA = 'stellar-forge.sf47-cohort-delivery-input.v1';
