  const manifests = {}, resolvedManifestPeers = {}, dependencyLocks = {}, errors = [];
  for (const group of ['native', ...Object.keys(featurePeers)]) {
    const peers = group === 'native' ? spec.nativePeers ?? {} : featurePeers[group];
    dependencyLocks[group] = { status: 'declared', declared: Object.fromEntries(
      Object.entries(peers).map(([name, definition]) => [name, definition.version])) };
  }
  for (const [group, path] of Object.entries(runtimePackageManifests)) {
    try {
      const record = required(records, path), dependencies = record.data?.dependencies;
      if (!dependencies || typeof dependencies !== 'object' || Array.isArray(dependencies) ||
        !Object.keys(dependencies).length || Object.entries(dependencies).some(([name, version]) => !name || typeof version !== 'string'))
        throw new TypeError('Original runtime package manifest has no valid dependencies: ' + path);
      resolvedManifestPeers[group] = Object.fromEntries(Object.entries(dependencies).map(([name, version]) =>
        [name, { ...(spec.featurePeers?.[group]?.[name] ?? {}), version, probe: spec.featurePeers?.[group]?.[name]?.probe ?? name }]));
      manifests[group] = record.descriptor;
      const lockPath = lockPaths(path)[0];
      if (lockPath) {
        try {
          const originalLock = required(records, lockPath);
          dependencyLocks[group] = { ...inspectRuntimeDependencyLock(record.data, originalLock.data),
            declared: dependencies, source: originalLock.descriptor };
        } catch (error) {
          dependencyLocks[group] = { status: 'unavailable', declared: dependencies, path: lockPath, error: errorView(error) };
        }
      } else dependencyLocks[group] = { status: 'declared', declared: dependencies };
    } catch (error) { errors.push({ feature: group, path, ...errorView(error) }); }
  }
  return { nativePeers: clone(spec.nativePeers ?? {}), featurePeers, runtimePackageManifests,
    featureNames: [...new Set([...Object.keys(featurePeers), ...Object.keys(runtimePackageManifests)])].sort(),
    resolvedManifestPeers, manifests, dependencyLocks, errors };
}

/** Enrich existing records; the original recipe availability and presentation fields are preserved. */
export function enrichProductRequirements(source, catalog) {
  const paths = source.tree.map(item => item.path), contributions = contributionPaths(paths);
  const records = readJson(source, [distributionPath, ...contributions,
    ...catalog.products.map(product => product.path).filter(Boolean)]);
  const products = catalog.products.map(product => {
    if (!product.available) return product;
    try {
      const recipe = product.path ? validateSourceSelection(required(records, product.path).data, product.path) : undefined;
      const selected = recipe ? selectedContributionPaths(contributions, recipe) : contributions;
      const distribution = composeDistribution({ base: required(records, distributionPath).data,
        contributions: selected.map(path => ({ path, data: required(records, path).data })), selection: recipe });
      return { ...product, ...describeProductRequirements(distribution) };
    } catch (error) { return { ...product, capabilityError: errorView(error) }; }
  });
  return { ...catalog, products, capabilities: productRequirementIndex(products) };
}

/** Use the same original catalog implementation as the Runtime workspace. */
export async function loadProductRequirements({ repository, ref = 'HEAD', offline = true } = {}) {
  const { sourceBuildCatalog } = await import('../runtime-workspace/source-build-workspace.mjs');
  return sourceBuildCatalog({ repository, ref, offline });
}

export type RequirementKind = 'command' | 'application' | 'merchant' | 'export' | 'feature' | 'source';
export type RequirementOrder = 'source' | 'coverage' | 'runtime-groups' | 'commands';
export type Requirement = `${RequirementKind}:${string}`;
export interface CapabilitySource { id: string; path: string; kind: 'base' | 'contribution' }
export interface CapabilityDeclaration {
  id: Requirement; kind: RequirementKind; name: string; provision: 'registration'; sources: CapabilitySource[];
}
export interface CapabilityCounts {
  commands: number; applications: number; merchantProviders: number; exports: number;
  runtimeGroups: number; components: number; sources: number;
}
export interface ProductRecord {
  id: string | null; title: string; description?: string; path?: string | null; available: boolean;
  requirements?: Requirement[]; capabilityDeclarations?: CapabilityDeclaration[]; capabilityCounts?: CapabilityCounts;
  capabilityError?: { code: string; message: string };
  [key: string]: unknown;
}
export interface ProductCatalog<T extends ProductRecord = ProductRecord> {
  repository: string; sourceCommit: string; offline: boolean; products: T[];
  capabilities?: { id: Requirement; kind: RequirementKind; name: string; products: number }[];
}
export interface RequirementOptions {
  requirements?: Requirement[]; match?: 'all' | 'any'; sort?: RequirementOrder;
}
export interface RequirementMatch {
  covered: Requirement[]; missing: Requirement[]; complete: boolean; declarations: CapabilityDeclaration[];
}
export interface RequirementResult<T extends ProductRecord = ProductRecord> {
  schema: 'stellar-forge.product-requirements.v1';
  requirements: Requirement[]; match: 'all' | 'any'; sort: RequirementOrder; total: number;
  products: (T & { requirementMatch: RequirementMatch })[];
  unread: { id: string | null; title: string; error: { code: string; message: string } }[];
}
export interface SourceReviewRequest {
  repository: string; ref: string; selection: string; offline: boolean; python: string;
}
export type RequirementPlan<T extends ProductRecord = ProductRecord> = Omit<RequirementResult<T>, 'products'> & {
  repository: string; sourceCommit: string; offline: boolean; allMatchesExported: true;
  products: (T & { requirementMatch: RequirementMatch; reviewRequest?: SourceReviewRequest })[];
};
export const PRODUCT_REQUIREMENTS_SCHEMA: 'stellar-forge.product-requirements.v1';
export const REQUIREMENT_KINDS: readonly RequirementKind[];
export const REQUIREMENT_SORTS: readonly RequirementOrder[];
export function normalizeProductRequirements(requirements?: Requirement[]): Requirement[];
export function describeProductRequirements(distribution: {
  spec: Record<string, unknown>; sources: { id: string; path: string }[]; origins?: Record<string, unknown>;
}): { requirements: Requirement[]; capabilityDeclarations: CapabilityDeclaration[]; capabilityCounts: CapabilityCounts };
export function productRequirementIndex(products: ProductRecord[]): NonNullable<ProductCatalog['capabilities']>;
export function matchProductRequirements<T extends ProductRecord>(products: T[], options?: RequirementOptions): RequirementResult<T>;
export function exportRequirementPlan<T extends ProductRecord>(catalog: ProductCatalog<T>, options?: RequirementOptions): RequirementPlan<T>;
export function productReviewRequest(catalog: ProductCatalog, id: string, options?: {
  python?: string; requirements?: Requirement[];
}): SourceReviewRequest;

// MIT. Match exact required capabilities against original source product recipes.
export const PRODUCT_REQUIREMENTS_SCHEMA = 'stellar-forge.product-requirements.v1';
export const REQUIREMENT_KINDS = Object.freeze(['command', 'application', 'merchant', 'export', 'feature', 'source']);
export const REQUIREMENT_SORTS = Object.freeze(['source', 'coverage', 'runtime-groups', 'commands']);
const sorted = values => [...new Set(values)].sort((a, b) => a.localeCompare(b, 'en'));
const keys = value => Object.keys(value ?? {});
const need = (condition, message) => { if (!condition) throw new TypeError(message); };

export function normalizeProductRequirements(requirements = []) {
  need(Array.isArray(requirements) && requirements.length <= 128, 'Select at most 128 capability requirements.');
  for (const id of requirements) {
    need(typeof id === 'string' && id.length <= 1100 && !/[\u0000-\u001f\u007f]/.test(id),
      'Expected a capability such as command:buyer-runbook.');
    const at = id.indexOf(':');
    need(at > 0 && REQUIREMENT_KINDS.includes(id.slice(0, at)) && id.slice(at + 1).length > 0,
      'Unknown capability requirement: ' + id);
  }
  return sorted(requirements);
}

/** The original composer supplies every selected registration and its source owner. */
export function describeProductRequirements(distribution) {
  const { spec, sources, origins } = distribution;
  need(spec?.commands && Array.isArray(sources), 'Expected original composed product declarations.');
  const features = sorted([...keys(spec.featurePeers), ...keys(spec.runtimePackageManifests),
    ...(keys(spec.nativePeers).length ? ['native'] : [])]);
  const requirements = sorted([
    ...keys(spec.commands).map(name => 'command:' + name),
    ...keys(spec.applicationProviders).map(name => 'application:' + name),
    ...keys(spec.merchantProviders).map(name => 'merchant:' + name),
    ...keys(spec.exports).map(name => 'export:' + name),
    ...features.map(name => 'feature:' + name),
    ...sources.map(source => 'source:' + source.id),
  ]);
  const byPath = new Map(sources.map(source => [source.path, source]));
  const owner = paths => sorted(paths).map(path => byPath.get(path))
    .filter(Boolean).map(({ id, path }) => ({ id, path, kind: id === 'base' ? 'base' : 'contribution' }));
  const fieldFor = { command: 'commands', application: 'applicationProviders', merchant: 'merchantProviders', export: 'exports' };
  const capabilityDeclarations = requirements.map(id => {
    const at = id.indexOf(':'), kind = id.slice(0, at), name = id.slice(at + 1);
    const paths = kind === 'source' ? sources.filter(source => source.id === name).map(source => source.path) :
      kind === 'feature' ? name === 'native' ? Object.values(origins?.nativePeers ?? {}).flat() :
        [...(origins?.runtimePackageManifests?.[name] ?? []), ...Object.values(origins?.featurePeers?.[name] ?? {}).flat()] :
        origins?.[fieldFor[kind]]?.[name] ?? [];
    return { id, kind, name, provision: 'registration', sources: owner(paths) };
  });
  return { requirements, capabilityDeclarations, capabilityCounts: { commands: keys(spec.commands).length,
    applications: keys(spec.applicationProviders).length, merchantProviders: keys(spec.merchantProviders).length,
    exports: keys(spec.exports).length, runtimeGroups: features.filter(name => name !== 'native').length,
    components: new Set(spec.components ?? []).size, sources: sources.length } };
}
export function productRequirementIndex(products) {
  const found = new Map();
  for (const product of products) {
    if (!product.available || product.capabilityError) continue;
    for (const id of product.requirements ?? []) {
      const at = id.indexOf(':'), current = found.get(id) ?? { id, kind: id.slice(0, at), name: id.slice(at + 1), products: 0 };
      current.products++; found.set(id, current);
    }
  }
  return [...found.values()].sort((a, b) => a.kind.localeCompare(b.kind, 'en') || a.name.localeCompare(b.name, 'en'));
}

/** Feed the existing catalog search result here; its text ranking and product records remain intact. */
export function matchProductRequirements(products, { requirements = [], match = 'all', sort = 'source' } = {}) {
  need(Array.isArray(products), 'Expected original product catalog entries.');
  requirements = normalizeProductRequirements(requirements);
  need(['all', 'any'].includes(match), 'Choose all or any requirements.');
  need(REQUIREMENT_SORTS.includes(sort), 'Unknown requirement order: ' + sort);
  const rows = products.flatMap((product, position) => {
    const available = new Set(product.requirements ?? []);
    const covered = requirements.filter(id => available.has(id)), missing = requirements.filter(id => !available.has(id));
    if (requirements.length && (!product.available || product.capabilityError || !Array.isArray(product.requirements) ||
      (match === 'all' ? missing.length > 0 : covered.length === 0))) return [];
    return [{ product, position, covered, missing }];
  });
  if (sort !== 'source') rows.sort((a, b) =>
    b.covered.length - a.covered.length ||
    (sort === 'runtime-groups' ? (a.product.capabilityCounts?.runtimeGroups ?? Infinity) - (b.product.capabilityCounts?.runtimeGroups ?? Infinity) :
      sort === 'commands' ? (a.product.capabilityCounts?.commands ?? Infinity) - (b.product.capabilityCounts?.commands ?? Infinity) : 0) ||
    a.position - b.position);
  return {
    schema: PRODUCT_REQUIREMENTS_SCHEMA, requirements, match, sort, total: rows.length,
    products: rows.map(({ product, covered, missing }) => ({ ...product,
      requirementMatch: { covered, missing, complete: missing.length === 0,
        declarations: (product.capabilityDeclarations ?? []).filter(value => covered.includes(value.id)) } })),
    unread: products.filter(product => product.capabilityError).map(product =>
      ({ id: product.id, title: product.title, error: product.capabilityError })),
  };
}

export function exportRequirementPlan(catalog, options = {}) {
  const result = matchProductRequirements(catalog.products, options);
  return { ...result, repository: catalog.repository, sourceCommit: catalog.sourceCommit,
    offline: catalog.offline, allMatchesExported: true,
    products: result.products.map(product => ({ ...product,
      ...(product.available && !product.capabilityError && product.requirementMatch.complete ? {
        reviewRequest: productReviewRequest(catalog, product.id, { requirements: result.requirements }),
      } : {}),
    })) };
}

/** This JSON is accepted directly by the original runtime-workspace source-build-review command. */
export function productReviewRequest(catalog, id, { python = 'python3', requirements = [] } = {}) {
  const product = catalog.products.find(value => value.id === id);
  need(product?.available && !product.capabilityError, 'Choose a product with readable original declarations.');
  requirements = normalizeProductRequirements(requirements);
  const available = new Set(product.requirements ?? []);
  const missing = requirements.filter(value => !available.has(value));
  need(missing.length === 0, 'This product is missing requested capabilities: ' + missing.join(', '));
  need(typeof catalog.offline === 'boolean', 'Preserve the original Git reader mode.');
  need(typeof catalog.repository === 'string' && catalog.repository.startsWith('/') &&
    /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(catalog.sourceCommit ?? ''),
  'Load products from an existing Git repository to prepare a committed build request.');
  need(typeof python === 'string' && python.length > 0 && python.length <= 1024 &&
    !/[\u0000-\u001f\u007f]/.test(python) &&
    (python.includes('/') ? python.startsWith('/') : /^[A-Za-z0-9_.+-]+$/.test(python)),
  'Select the original Python interpreter.');
  return { repository: catalog.repository, ref: catalog.sourceCommit, selection: product.id,
    offline: catalog.offline, python };
}

// MIT. Browser projection of the same catalog and search implementation as the CLI.
import { exportCommandCatalog, findCatalogItem, searchCommandCatalog } from '/catalog.mjs';

const $ = id => document.getElementById(id);
const names = { command: 'Command', source: 'Source', feature: 'Runtime group',
  export: 'Package export', application: 'Applications provider', merchant: 'Merchant MCP provider' };
let catalog, result, selectedId = '', currentPage = 1, inputTimer;
const filters = () => ({ query: $('query').value, kind: $('kind').value,
  source: $('source').value, feature: $('feature').value, page: currentPage, pageSize: 40 });
const node = (tag, text, className) => {
  const value = document.createElement(tag);
  if (text !== undefined) value.textContent = text;
  if (className) value.className = className;
  return value;
};
function showError(error) {
  $('error').hidden = !error;
  $('error').textContent = error?.message ?? '';
}
function writeUrl() {
  const values = filters(), url = new URL(location.href);
  url.search = '';
  for (const [name, value] of Object.entries({ q: values.query, kind: values.kind === 'all' ? '' : values.kind,
    source: values.source, feature: values.feature, page: currentPage > 1 ? currentPage : '' }))
    if (value) url.searchParams.set(name, String(value));
  url.hash = selectedId ? encodeURIComponent(selectedId) : '';
  history.replaceState(null, '', url);
}
function selectSource(id) {
  $('source').value = id;
  currentPage = 1;
  render();
}
function itemButton(id, label = id) {
  const button = node('button', label);
  button.type = 'button';
  button.addEventListener('click', () => selectItem(id, true));
  return button;
}
function heading(parent, text) { parent.append(node('h3', text)); }
function list(parent, values, kind) {
  if (!values?.length) return;
  const ul = node('ul');
  for (const value of values) {
    const li = node('li');
    li.append(kind ? itemButton(kind + ':' + value, value) : node('code', value));
    ul.append(li);
  }
